    titleGujarati: 'શ્રી દામોદરદાસ હરસાનીની વાર્તા',
    titleBraj: 'દામોદરદાસ હરસાની કી વાર્તા', // The title in Braj Bhasha
    shloka: 'पठनीयं प्रयत्नेन सर्वहेतुविवर्जितम् ॥ १ ॥',
    arth:
        'શ્રીમદ્ ભાગવત શાસ્ત્રનો પ્રયત્નપૂર્વક કોઈપણ પ્રકારના લૌકિક કે અલૌકિક હેતુ વગર (નિષ્કામ ભાવે) પાઠ કરવો.',
    vartaContent:
        '''શ્રી દામોદરદાસ હરસાનીનો જન્મ વર્ધમાનપૂરમાં થયો હતો. તેમના પિતાજી શ્રી મહાદેવજીના અનન્ય ભક્ત હતા. શ્રી મહાદેવજીના વરદાનથી તેમના ઘરે દિવ્ય બાલકનો જન્મ થયો, તેથી તેમનું નામાભિધાન 'દામોદરદાસ' રાખવામાં આવ્યું. નાનપણથી જ દામોદરદાસજીના લક્ષણો અલૌકિક હતા.

જ્યારે શ્રીઆચાર્યજી મહાપ્રભુજી પોતાની પ્રથમ પૃથ્વી પરિક્રમા દરમિયાન દક્ષિણ ભારતમાંથી વર્ધમાનપૂર પધાર્યા, ત્યારે તેઓ દામોદરદાસજીના ઘરે બિરાજ્યા. શ્રીમહાપ્રભુજીના તેજોમય અને અલૌકિક સ્વરૂપના દર્શન થતાં જ દામોદરદાસજીના હૃદયમાં પૂર્વજન્મનો અંકુરિત ભક્તિભાવ જાગ્રત થઈ ગયો. તેમણે તુરંત જ શ્રીઆચાર્યજીના ચરણોમાં શરણાગતિ સ્વીકારી. શ્રીમહાપ્રભુજીએ તેમને નામનિવેદન કરાવીને પુષ્ટિમાર્ગીય દીક્ષા આપી. આ રીતે શ્રી દામોદરદાસ હરસાની શ્રીમહાપ્રભુજીના સર્વપ્રથમ સેવક (શિષ્ય) બન્યા.

દામોદરદાસજી નિત્ય શ્રીમહાપ્રભુજીની સેવામાં જ તલ્લીન રહેતા. શ્રીઆચાર્યજી જ્યારે જ્યારે પૃથ્વી પરિક્રમા કરતા ત્યારે દામોદરદાસજી સદા તેમની સાથે જ રહેતા. એકવાર શ્રીમહાપ્રભુજી ગોકુલ પધાર્યા અને ગોવિંદઘાટ પર બિરાજમાન હતા. તે સમયે શ્રીમહાપ્રભુજીના મનમાં ચિંતા થઈ કે "જીવ સ્વભાવથી દોષયુક્ત છે, તો તે પૂર્ણ પુરુષોત્તમ પ્રભુની સેવા કઈ રીતે કરી શકે?" તે જ રાત્રે શ્રીઠાકોરજી (શ્રીનાથજી) સાક્ષાત પ્રગટ થયા અને શ્રીમહાપ્રભુજીને આજ્ઞા કરી કે "જે જીવ બ્રહ્મસંબંધ કરશે તેના સર્વ દોષો નિવૃત્ત થઈ જશે." આ દિવ્ય ઘટનાના એકમાત્ર પ્રત્યક્ષ સાક્ષી શ્રી દામોદરદાસ હરસાની જ હતા. બીજે દિવસે સવારે શ્રીમહાપ્રભુજીએ સર્વપ્રથમ દામોદરદાસજીને જ બ્રહ્મસંબંધ આપીને પુષ્ટિમાર્ગની વિધિવત શરૂઆત કરી.

શ્રીઆચાર્યજી જ્યારે શ્રીમદ્ ભાગવતજીનું પારાયણ કરતા કે Subodhini (સુબોધિનીજી) પર્યાલોચના કરતા, ત્યારે દામોદરદાસજી અત્યંત એકાગ્ર ચિત્તે કથા શ્રવણ કરતા. શ્રીમહાપ્રભુજી જે ગૂઢ ભગવદ્-લીલા અને સિદ્ધાંત પ્રગટ કરતા, તેને દામોદરદાસજી પોતાના હૃદયકમળમાં ધારણ કરી લેતા. એકવાર દામોદરદાસજીને લૌકિક કાર્ય માટે બહાર જવાનું થયું, પરંતુ તેમનું ચિત્ત ક્ષણભર પણ શ્રીઆચાર્યજીના ચરણારવિંદ અને સેવામાંથી અલગ ન થયું. તેમની ગુરુભક્તિ અને ભગવદ્-ભાવ એવા અદ્ભુત હતા કે શ્રીમહાપ્રભુજી પણ તેમની પર અતિશય પ્રસન્ન રહેતા.

દામોદરદાસજીનું આખું જીવન ગુરુવચન અને ભગવદ્-આજ્ઞાનું પાલન કરવામાં જ વિત્યું. તેમણે ક્યારેય પોતાના સુખ કે લૌકિક પ્રતિષ્ઠાની પરવા ન કરી. તેઓ સદા શ્રીજીના સ્વરૂપાનંદમાં અને શ્રીઆચાર્યજીના ચરણકમળની સેવામાં જ મગ્ન રહ્યા.''',
    saar:
        'શુદ્ધ કૃપાપાત્ર જીવ ગુરુ અને ભગવાનના વચન પર અવિચળ વિશ્વાસ રાખે છે. ગુરુની આજ્ઞાનું અક્ષરશઃ પાલન કરવું, સ્વેચ્છાચારનો ત્યાગ કરવો અને સર્વસ્વ પ્રભુચરણોમાં સમર્પિત કરી દેવું એ જ પુષ્ટિમાર્ગીય ભક્તનું મુખ્ય લક્ષણ છે.',
  ),
  VartaModel(
    id: '2',
