    titleGujarati: 'શ્રી કૃષ્ણદાસ મેઘન સાંચોરા બ્રાહ્મણની વાર્તા',
    titleBraj: 'કૃષ્ણદાસ મેઘન કી વાર્તા',
    shloka: 'सर्वदा सर्वभावेन भजनीयो व्रजाधिपः ॥ २ ॥',
    arth:
        'સર્વદા અને સર્વ ભાવથી વ્રજેશ શ્રીકૃષ્ણનું નિષ્કામ ભાવે ભજન અને સેવા કરવી.',
    vartaContent:
        '''શ્રી કૃષ્ણદાસ મેઘન સાંચોરા બ્રાહ્મણ હતા અને તેઓ સાંચોર ગામમાં રહેતા હતા. તેઓ સ્વભાવે અત્યંત સરળ, નિષ્કપટ, નિર્માની અને સંસાર પ્રત્યે પૂર્ણ વિરક્ત હતા. જ્યારે શ્રીઆચાર્યજી મહાપ્રભુજી પૃથ્વી પરિક્રમા કરતા સાંચોર પધાર્યા, ત્યારે કૃષ્ણદાસજી શ્રીમહાપ્રભુજીના દિવ્ય દર્શન કરીને અતિશય આકર્ષાયા. તેમના હૃદયમાં પુષ્ટિમાર્ગીય ભક્તિનો અંકુર પ્રગટ થયો. તેમણે શ્રીમહાપ્રભુજીના ચરણોમાં શરણાગતિ સ્વીકારી નામનિવેદન મંત્ર પ્રાપ્ત કર્યો અને સર્વસ્વ છોડી શ્રીઆચાર્યજીના ચરણારવિંદમાં સેવા કરવા લાગ્યા.

કૃષ્ણદાસજી શ્રીમહાપ્રભુજીની સદા સાથે જ રહેતા અને તેમની સેવામાં રાત-દિવસ અહર્નિશ તત્પર રહેતા. એક સમયની વાત છે કે, શ્રીમહાપ્રભુજી પરિક્રમા દરમિયાન એક ગાઢ જંગલમાંથી પસાર થઈ રહ્યા હતા. તે સમયે મુસળધાર વરસાદ વરસવા લાગ્યો અને ચારે બાજુ પાણી ભરાઈ ગયું. શ્રીમહાપ્રભુજી અને અન્ય વૈષ્ણવો પાસે શ્રીઠાકોરજીના ભોગ-સામગ્રી અને સામગ્રી પધરાવવા માટે સૂકી જગ્યા નહોતી. કૃષ્ણદાસજીએ પોતાની આખી દેહ અને વસ્ત્રોનો આશરો આપીને ભોગ-સામગ્રીને ભીંજાવા ન દીધી અને શ્રીમહાપ્રભુજીની સેવા-સામગ્રી સુરક્ષિત રાખી. તેમની આવી અનન્ય અને કઠિન ગુરુસેવા જોઈને શ્રીમહાપ્રભુજી અત્યંત પ્રસન્ન થયા.

એકવાર કૃષ્ણદાસજીને શ્રીમહાપ્રભુજીએ કઈંક માગવા કહ્યું, ત્યારે કૃષ્ણદાસજીએ કહ્યું કે, "હે મહારાજ! મને લૌકિક કે અલૌકિક કોઈ વસ્તુની ઈચ્છા નથી. માત્ર આપના ચરણારવિંદની અવિચળ સેવા અને શ્રીજીના નામસ્મરણનો જ આશ્રય રહે, એ જ મારી પ્રાર્થના છે." શ્રીમહાપ્રભુજી તેમની નિષ્કામ ભક્તિ જોઈ અતિ પ્રસન્ન થયા અને તેમને આશીર્વાદ આપ્યા.

કૃષ્ણદાસજી ક્યારેય પણ પોતાનું અહં પ્રગટ થવા દેતા નહી. તેઓ અન્ય વૈષ્ણવોની નમ્ર ભાવે સેવા કરતા અને સદા શ્રીજીના ગુણગાનમાં લીન રહેતા. તેમનું આખું જીવન અનન્ય ભગવદ્-આશ્રય અને ગુરુભક્તિનું ઉત્તમ ઉદાહરણ બની રહ્યું.''',
    saar:
        'સાચો પુષ્ટિમાર્ગીય સેવક એ જ છે જે અનુકૂળ કે પ્રતિકૂળ પરિસ્થિતિમાં પણ પોતાની પરવા કર્યા વગર ગુરુ અને ભગવાનની સેવામાં તત્પર રહે છે. દેહાભિમાન અને લૌકિક ઈચ્છાઓનો ત્યાગ કરીને નિષ્કામ ભાવે ભજન કરવું એ જ ભગવદ્-પ્રાપ્તિનો સાચો માર્ગ છે.',
