    titleGujarati: 'શ્રી દામોદરદાસ સંભલવાળાની વાર્તા',
    titleBraj: 'દામોદરદાસ સંભલવાળા કી વાર્તા',
    shloka: 'स्वेच्छाचारविहीनेन भक्ती रसभरेण च ॥ ३ ॥',
    arth:
        'સ્વેચ્છાચાર (પોતાની મરજી કે અહંકાર) નો સંપૂર્ણ ત્યાગ કરીને ભક્તિરસથી ભરીને શ્રીકૃષ્ણની સેવા-સ્મરણ કરવું.',
    vartaContent:
        '''શ્રી દામોદરદાસ સંભલવાળા સંભલ નામના ગામના વતની હતા. તેઓ વ્યાપાર-રોજગારમાં અત્યંત હોશિયાર અને સમૃદ્ધ હતા, પરંતુ સંસારના તમામ સુખો હોવા છતાં તેમના મનમાં શાંતિ નહોતી અને અંતરમાં એક પ્રકારની અશાંતિ તથા ભગવદ્-વિપ્રયોગનો અનુભવ થતો હતો.

જ્યારે શ્રીઆચાર્યજી મહાપ્રભુજી પોતાની પૃથ્વી પરિક્રમા દરમિયાન સંભલ ગામમાં પધાર્યા અને ભાગવત કથા અને સુબોધિનીજીનો ઉપદેશ આપવાનું શરૂ કર્યું, ત્યારે દામોદરદાસજી પણ કથા શ્રવણ કરવા ગયા. શ્રીમહાપ્રભુજીના દિવ્ય, તેજોમય સ્વરૂપ અને અમૃતમયી વાણી સાંભળતા જ દામોદરદાસજીનું હૃદયદ્રવિત થઈ ગયું. તેમના સંસાર પ્રત્યેના મોહ-માયાના તમામ બંધનો ક્ષણભરમાં છૂટી ગયા. તેમણે શ્રીમહાપ્રભુજીના ચરણોમાં સાષ્ટાંગ પ્રણામ કર્યા અને શરણાગતિ સ્વીકારી બ્રહ્મસંબંધ પ્રાપ્ત કર્યો.

બ્રહ્મસંબંધ લીધા બાદ દામોદરદાસજીએ પોતાના ઘરમાં શ્રીઆચાર્યજીની આજ્ઞાનુસાર શ્રીઠાકોરજીનું સ્વરૂપ પધરાવી સેવાનો પ્રારંભ કર્યો. તેઓ ધંધા-વ્યાપારનું કામકાજ માત્ર નિર્વાહ પૂરતું જ કરતા, પરંતુ તેમનું ચિત્ત સદા-સર્વદા શ્રીજીના ચરણારવિંદમાં જ અર્પિત રહેતું. તેઓ ક્યારેય પોતાની મરજી કે સ્વેચ્છાચારથી સેવા ન કરતા. પુષ્ટિમાર્ગીય મર્યાદા, ગુરુજીની આજ્ઞા અને પદ્ધતિ અનુસાર જ નિત્ય સામગ્રી, શ્રંગાર અને ભોગ અર્પણ કરતા.

દામોદરદાસજીના ઘરે જો કોઈ ભગવદીય (વૈષ્ણવ) પધારતા તો તેઓ અત્યંત લીન થઈને નમ્ર ભાવે તેમનો સત્કાર કરતા. તેઓ સદા માનતા કે વૈષ્ણવોની સેવા એ પણ સાક્ષાત શ્રીજીની જ સેવા છે. તેમની આવી નિર્મળ અને અનન્ય નિષ્ઠા જોઈને શ્રીમહાપ્રભુજી તેમની પર સદા પ્રસન્ન રહેતા. દામોદરદાસજીએ પોતાનું આખું જીવન ગુરુવચનના પાલન અને નિષ્કામ ભક્તિરસમાં જ વિતાવ્યું.''',
    saar:
        'પોતાના અહંકાર, સ્વેચ્છાચાર કે લૌકિક બુદ્ધિનો ત્યાગ કરીને ગુરુદેવની આજ્ઞા અને પુષ્ટિમાર્ગીય રીતિ-નીતિ મુજબ સેવા-સ્મરણ કરવું એ જ સાચા પુષ્ટિ ભક્તનું લક્ષણ છે.',
  ),
  VartaModel(
    id: '4',
    number: '૦૪',
    titleGujarati: 'શ્રી પદ્મનાભદાસ કાનોજિયા બ્રાહ્મણની વાર્તા',
    titleBraj: 'પદ્મનાભદાસ કાનોજિયા કી વાર્તા',
    shloka: 'सदा भगवदीयानां संगः कार्यः प्रयत्नतः ॥ ४ ॥',
    arth:
        'સદા અને સર્વદા પ્રયત્નપૂર્વક ભગવદીયો (પ્રભુભક્તો/વૈષ્ણવો) નો સંગ કરવો, કારણ કે સત્સંગથી જ દિવ્ય ભક્તિરસ પ્રગટ થાય છે.',
    vartaContent:
        '''શ્રી પદ્મનાભદાસ કાનોજિયા કનૌજ શહેરના નિવાસી અને એક પરમ વિદ્વાન બ્રાહ્મણ હતા. શરૂઆતમાં તેઓ શાસ્ત્રજ્ઞાન અને અહંકારના કારણે અન્ય દેવોની ઉપાસના તથા લૌકિક કર્મકાંડમાં લાગેલા હતા. પરંતુ તેમના પૂર્વજન્મના સત્સંસ્કારોના કારણે તેમનો ઉદ્ધાર કરવાનો સમય નજીક આવ્યો.

જ્યારે શ્રીઆચાર્યજી મહાપ્રભુજી પોતાની ભારત પરિક્રમા દરમિયાન કનૌજ નગરીમાં પધાર્યા અને શ્રીમદ્ ભાગવતજીનું પરાયણ શરુ કર્યું, ત્યારે પદ્મનાભદાસજી પણ ત્યાં કથા શ્રવણ કરવા માટે આવ્યા. શ્રીમહાપ્રભુજીના મુખારવિંદથી નિતરતી અમૃતવાણી અને ભાગવતના ગૂઢ સુબોધિનીજીના બ્રહ્મસંબંધ સંબંધી વિચારો સાંભળીને પદ્મનાભદાસજીનો તમામ અહંકાર ક્ષણભરમાં ઓગળી ગયો. તેમને અનુભવાયું કે સાચો ધર્મ તો પ્રભુચરણમાં આત્મસમર્પણ કરવાનો જ છે.

તેમણે તુરંત જ શ્રીમહાપ્રભુજીના ચરણોમાં સાષ્ટાંગ પ્રણામ કરી શરણાગતિ સ્વીકારી અને બ્રહ્મસંબંધ પ્રાપ્ત કર્યો. દીક્ષા લીધા બાદ પદ્મનાભદાસજીનું હૃદય એવા ભક્તિરસથી છલકાઈ ગયું કે તેઓ શ્રીકૃષ્ણની વિવિધ લીલાઓના પદો અને કીર્તનોની રચના કરવા લાગ્યા. તેઓ રાત-દિવસ વૈષ્ણવોના સંગમાં રહી શ્રીજીના ગુણગાન ગાવતા અને પોતાના ઘરમાં પધરાવેલા શ્રીઠાકોરજીની અતિશય પ્રીતિથી સેવા કરતા.

એકવાર કનૌજના રાજાએ તેમની ભક્તિ અને નિષ્ઠાની પરીક્ષા લેવાનો પ્રયત્ન કર્યો, પરંતુ પદ્મનાભદાસજીનો અચળ ભગવદ્-આશ્રય જોઈને રાજા પોતે જ ચકિત થઈ ગયો અને નતમસ્તક થઈને તેમનો શિષ્ય બની ગયો. પદ્મનાભદાસજીએ ક્યારેય કોઈ લૌકિક પદ કે ધનની લાલચ ન રાખી અને જીવનના અંત સુધી ભગવદીયોના સંગમાં રહી કીર્તન-સેવા કરતા રહ્યા.''',
    saar:
        'ભગવદ્-ભક્તો (ભગવદીયો) નો સત્સંગ અને શ્રીહરિના દિવ્ય ગુણગાન જ જીવના હૃદયમાંથી અજ્ઞાન અને અહંકારનો નાશ કરે છે. ભગવદ્-આશ્રય જ સર્વોચ્ચ શક્તિ છે.',
  ),
  VartaModel(
    id: '5',
    number: '૦૫',
    titleGujarati: 'શ્રી ક્ષત્રાણી અડાવલવાળીની વાર્તા',
    titleBraj: 'ક્ષત્રાણી અડાવલવાળી કી વાર્તા',
    shloka: 'गृहम् सर्वम् विस्मृत्य भगवच्चरणं भजेत् ॥ ५ ॥',
    arth:
        'ઘર-સંસાર અને સર્વ લૌકિક બાબતોનો મોહ વિસરીને માત્ર શ્રીકૃષ્ણના ચરણારવિંદનું અનન્ય ભાવથી ભજન-સેવા કરવી.',
    vartaContent:
        '''અડાવલ ગામમાં રહેતા આ ક્ષત્રાણીજી શ્રીમહાપ્રભુજીના અત્યંત કૃપાપાત્ર અને અનન્ય સેવિકા હતા. તેઓ પૂર્વજન્મના સંસ્કારોથી જ ભગવદ્-ભાવથી પૂર્ણ હતા, પરંતુ લૌકિક દ્રષ્ટિએ તેમની આર્થિક સ્થિતિ અત્યંત ગરીબ હતી. તેમના ઘરમાં ધન કે ભૌતિક સાધનોની ભારે અછત રહેતી, છતાં તેમના હૃદયમાં શ્રીજી પ્રત્યેની પ્રીતિ અને સમર્પણ અનંત હતા.

જ્યારે શ્રીઆચાર્યજી મહાપ્રભુજી અડાવલ પધાર્યા, ત્યારે ક્ષત્રાણીજીએ તેમના દિવ્ય સ્વરૂપના દર્શન કરી અતિશય આનંદ અનુભવ્યો. તેમણે શ્રીઆચાર્યજી પાસેથી બ્રહ્મસંબંધ પ્રાપ્ત કર્યો અને પોતાના ઘરમાં શ્રીઠાકોરજી પધરાવીને ભાવપૂર્વક સેવા કરવાનો પ્રારંભ કર્યો. તેઓ પોતાના લૌકિક દુઃખો કે દરિદ્રતાની ક્યારેય ચિંતા કરતા નહીં; તેમનો મુખ્ય આધાર તો માત્ર પોતાના શ્રીજી જ હતા.

એક વખત ક્ષત્રાણીજીના ઘરમાં સામગ્રી સિદ્ધ કરવા માટે ધાન્ય કે લોટ પણ નહોતો. ઘરમાં ખાવા માટે કશું જ બચ્યું નહોતું અને કોઈની પાસે માંગવું એ પુષ્ટિમાર્ગીય આશ્રયના સિદ્ધાંતની વિરુદ્ધ હતું. આવી કઠિન પરિસ્થિતિમાં પણ ક્ષત્રાણીજી સહેજ પણ વિચલિત ન થયા કે મનમાં ખેદ ન લાવ્યા. તેમણે અત્યંત નમ્ર ભાવે પવિત્ર જળ અને તુલસીજી અર્પણ કરીને શ્રીઠાકોરજી સમક્ષ ક્ષમાયાચના કરી અને વિનંતી કરી કે "હે પ્રભુ! મારી પાસે આપની સેવા માટે લૌકિક સામગ્રી નથી, પણ મારું હૃદય અને પ્રીતિ આપના ચરણોમાં સમર્પિત છે."

ક્ષત્રાણીજીની આવી નિષ્કામ, નિષ્કપટ અને અચળ ભક્તિ જોઈને શ્રીજી સાક્ષાત પ્રસન્ન થયા. શ્રીઠાકોરજીએ તેમની ભાવપૂર્વક અર્પણ કરેલી સામગ્રી અને જળને સ્વીકાર્યા અને ક્ષત્રાણીજીને દિવ્ય અલૌકિક અનુભવ કરાવ્યો. ક્ષત્રાણીજીએ ક્યારેય પણ લૌકિક વસ્તુઓ માટે ભગવદ્-ચરણમાંથી ચિત્ત હટાવ્યું નહીં અને આખું જીવન અનન્ય આશ્રયમાં જ વિતાવ્યું.''',
    saar:
        'ભગવાન ક્યારેય બાહ્ય આડંબર, ધન કે મોટો વૈભવ નથી જોતા; તેઓ તો માત્ર ભક્તના હૃદયનો શુદ્ધ, નિષ્કપટ ભાવ અને અવિચળ આશ્રય જ જુએ છે. સંસારના અભાવ વચ્ચે પણ જો પ્રભુ પર પૂર્ણ વિશ્વાસ રહે, તો પ્રભુ સાક્ષાત પ્રગટ થઈને ભક્તનો મનોરથ પૂર્ણ કરે છે.',
  ),
  VartaModel(
