    titleGujarati: 'શ્રી ગોપાલદાસ વ્રજવાસીની વાર્તા',
    titleBraj: 'ગોપાલદાસ વ્રજવાસી કી વાર્તા',
    shloka: 'सर्व समर्पणं कार्यं कायेन मनसा गिरा ॥ ६ ॥',
    arth:
        'કાયા (શરીર), મન અને વાણીથી સર્વસ્વ ભગવાન અને ગુરુચરણોમાં નિષ્કામ ભાવે સમર્પિત કરવું.',
    vartaContent:
        '''શ્રી ગોપાલદાસ વ્રજભૂમિના નિત્ય નિવાસી હતા. તેઓ અનન્ય વ્રજભાવથી પૂર્ણ હતા અને ગોકુલ તથા ગિરિરાજજીની પરિક્રમા કરી નિત્ય ભગવદ્-સ્મરણ કરતા હતા. તેમનું હૃદય સહજ રીતે જ શ્રીકૃષ્ણની બાળલીલાઓ અને ગોપીજનોના અનન્ય પ્રેમભાવમાં ડૂબેલું રહેતું હતું.

જ્યારે શ્રીઆચાર્યજી મહાપ્રભુજી પોતાની પૃથ્વી પરિક્રમા દરમિયાન વ્રજમંડળમાં ગોકુલ પધાર્યા, ત્યારે ગોપાલદાસજીએ શ્રીમહાપ્રભુજીના અલૌકિક તેજોમય સ્વરૂપના દર્શન કર્યા. દર્શન માત્રથી જ તેમના હૃદયમાં અત્યંત આનંદ અને વિપ્રયોગની દિવ્ય લાગણી પ્રગટ થઈ. તેમણે તુરંત શ્રીમહાપ્રભુજીના ચરણોમાં શરણાગતિ સ્વીકારી, સાષ્ટાંગ પ્રણામ કર્યા અને નામનિવેદન તથા બ્રહ્મસંબંધ પ્રાપ્ત કર્યો.

બ્રહ્મસંબંધ લીધા પછી ગોપાલદાસજીએ પોતાની કાયા, મન અને વાણી સર્વસ્વ શ્રીમહાપ્રભુજી અને શ્રીઠાકોરજીના ચરણોમાં અર્પિત કરી દીધાં. તેઓ નિત્ય શ્રીગિરિરાજજીની તળેટીમાં રહીને ભગવદ્-કીર્તન કરતા. તેમની વાણીમાંથી નિતરતા રસિક પદો સાંભળીને અન્ય વૈષ્ણવો પણ પ્રભુ પ્રેમમાં લીન થઈ જતા. તેઓ ક્યારેય પણ લૌકિક બાબતો કે પોતાના શરીરના સુખ-દુઃખની પરવા ન કરતા. તેમની દ્રષ્ટિમાં તો વ્રજની રજ (ધૂળ) અને શ્રીજીની સેવા એ જ સર્વોચ્ચ ધન હતું.

એકવાર કોઈ વિધર્મી અધિકારીએ વ્રજવાસીઓ પર અડચણ ઊભી કરવાનો પ્રયત્ન કર્યો, ત્યારે ગોપાલદાસજીએ પોતાના અચળ ભગવદ્-આશ્રય અને દિવ્ય ભાવથી જ તે પરિસ્થિતિનો ઉકેલ લાવ્યો અને શ્રીજીની સેવા-સામગ્રીમાં જરાય અડચણ આવવા ન દીધી. ગોપાલદાસજીએ પોતાનું સંપૂર્ણ આયુષ્ય શ્રીજીના સ્વરૂપાનંદમાં અને ગુરુચરણોની અનન્ય નિષ્ઠામાં જ વિતાવ્યું.''',
    saar:
        'સાચો ભક્ત પોતાની વાણી, મન અને દેહથી માત્ર પ્રભુ અને ગુરુની સેવા જ કરે છે. સંસારના મોહનો ત્યાગ કરી વ્રજભાવ અને અનન્ય આશ્રય ધારણ કરવાથી જ પ્રભુની પૂર્ણ કૃપા પ્રાપ્ત થાય છે.',
  ),
