    vartaContent:
        '''શ્રી રામદાસજી ચૌહાણ વંશના એક પરાક્રમી ક્ષત્રિય હતા. તેમનું પ્રારંભિક જીવન એક યોદ્ધા તરીકે વીરતા, શસ્ત્રવિદ્યા અને રાજકીય બાબતો વચ્ચે વિતી રહ્યું હતું. ક્ષત્રિય સ્વભાવ હોવાના કારણે તેમનામાં તેજ અને સ્વાભિમાન પણ હતું, પરંતુ પૂર્વજન્મના કોઈ પુણ્યભાવ અને સત્સંસ્કારને લીધે તેમના અંતરમાં એક પ્રકારની આંતરિક વિરક્તિ પણ છુપાયેલી હતી.

જ્યારે શ્રીઆચાર્યજી મહાપ્રભુજી પોતાની પૃથ્વી પરિક્રમા દરમિયાન ત્યાંથી પસાર થઈ રહ્યા હતા, ત્યારે રામદાસજી તેમના દિવ્ય દર્શન કરવા પહોંચ્યા. શ્રીમહાપ્રભુજીના દિવ્ય મુખારવિંદથી નિતરતી કૃષ્ણકથા અને અવિચળ આશ્રયનો ઉપદેશ સાંભળતા જ રામદાસજીનું હૃદયદ્રવિત થઈ ગયું. તેમનો લૌકિક શૂરવીરતાનો અહંકાર ક્ષણવારમાં ગળી ગયો. તેમને સમજાયું કે આ સંસારનું સાચું પરાક્રમ તો મનને જીતીને ભગવાનના ચરણોમાં અર્પિત કરી દેવામાં જ છે.

તેમણે તુરંત જ પોતાના શસ્ત્રો બાજુ પર મૂકી શ્રીમહાપ્રભુજીના ચરણોમાં સાષ્ટાંગ પ્રણામ કર્યા અને શરણાગતિ સ્વીકારીને નામનિવેદન તથા બ્રહ્મસંબંધ પ્રાપ્ત કર્યો. દીક્ષા લીધા બાદ રામદાસજીએ ક્ષત્રિય અહંકારનો સંપૂર્ણ ત્યાગ કરીને પોતાને પ્રભુના દાસના પણ દાસ માન્યા. તેઓ શ્રીઆચાર્યજીની સાથે રહીને સેવામાં લીન થઈ ગયા.

એકવાર માર્ગમાં કેટલાક અસામાજિક તત્વો અને ભયંકર વિઘ્નો આવ્યા, પરંતુ રામદાસજીએ શ્રીજીના અનન્ય આશ્રયના બળે જરાય ભય પામ્યા વગર તે તમામ પરિસ્થિતિઓ શાંત કરી. તેમની અચળ ગુરુભક્તિ અને ભગવદ્-વિશ્વાસ જોઈ શ્રીમહાપ્રભુજી તેમના પર અતિશય પ્રસન્ન થયા. રામદાસજીએ પોતાનું શેષ આયુષ્ય સંપૂર્ણપણે ભગવદ્-સેવા અને સત્સંગમાં જ વિતાવ્યું.''',
    saar:
        'દુનિયાની ગમે તેવી શક્તિ કે શૂરવીરતા હોય, પણ ભગવાનના આશ્રય વિના સાચી શાંતિ મળતી નથી. જ્યારે જીવ પ્રભુચરણમાં પોતાનો અહંકાર સમર્પિત કરી દે છે, ત્યારે પ્રભુ તેને સર્વ ભયોમાંથી મુક્ત કરી દિવ્ય અભય પદ આપે છે.',
  ),
