    arth:
        'આ સંસારમાં કે પરલોકમાં શ્રીહરિની ભક્તિ જ સર્વશ્રેષ્ઠ છે, તેમાં સહેજ પણ સંશય નથી.',
    vartaContent:
        '''શ્રી ગજધર ક્ષત્રિય ઉજ્જૈન નગરીના વતની હતા. તેઓ કાયદા અને શાસનકાજમાં કુશળ, અત્યંત ધનવાન અને પ્રભાવશાળી વ્યક્તિ હતા. લૌકિક દ્રષ્ટિએ તેમની પાસે તમામ પ્રકારના વૈભવ અને સુખ-સાધનો ઉપલબ્ધ હતા, પરંતુ તેમના મનમાં નિત્ય એક આંતરિક ખાલીપો અને અશાંતિનો અનુભવ થતો હતો. તેમને લાગતું હતું કે આ જગતનો વૈભવ ક્ષણભંગુર છે અને તેનાથી આત્માને સાચો આનંદ મળી શકતો નથી.

જ્યારે શ્રીઆચાર્યજી મહાપ્રભુજી પોતાની પૃથ્વી પરિક્રમા દરમિયાન ઉજ્જૈન પધાર્યા અને ક્ષિપ્રા નદીના કિનારે વિરાજમાન થઈને શ્રીમદ્ ભાગવતજીની કથા તથા સુબોધિનીજીનું પારાયણ શરૂ કર્યું, ત્યારે ગજધરજી પણ ત્યાં કથા શ્રવણ કરવા આવ્યા. શ્રીમહાપ્રભુજીના તેજોમય સ્વરૂપ અને તેમના મુખારવિંદમાંથી ઝરતી ભાગવતલીલાની અમૃતધારા સાંભળીને ગજધરજીનું ચિત્ત તુરંત જ ભક્તિરંગમાં રંગાઈ ગયું. તેમના મનનો મોહ-માયાનો પડદો હટી ગયો.

તેમણે શ્રીમહાપ્રભુજીના ચરણોમાં સાષ્ટાંગ પ્રણામ કરી શરણાગતિ સ્વીકારી અને બ્રહ્મસંબંધ પ્રાપ્ત કર્યો. દીક્ષા લીધા બાદ ગજધરજીએ પોતાના લૌકિક અહંકાર અને પદના મદનો ત્યાગ કર્યો. તેમણે પોતાના ઘરમાં શ્રીઆચાર્યજીની આજ્ઞાનુસાર શ્રીઠાકોરજીનું સ્વરૂપ પધરાવી સેવા-અર્ચનાનો પ્રારંભ કર્યો. તેઓ પોતાની સમૃદ્ધિનો ઉપયોગ ભગવદ્-સેવા અને સત્સંગ માટે જ કરવા લાગ્યા.

ગજધરજી નિત્ય વૈષ્ણવોને પોતાના ઘરે આમંત્રણ આપીને તેમની સેવા કરતા અને તેમની સાથે ભગવદ્-ચર્ચામાં લીન રહેતા. તેઓ સદા માનતા કે પ્રભુસેવા આગળ આ સંસારનું મોટામાં મોટું પદ પણ તુચ્છ છે. તેમની આવી અનન્ય અને નિષ્કામ ભક્તિ જોઈને શ્રીમહાપ્રભુજી તેમના પર અત્યંત પ્રસન્ન રહ્યા.''',
    saar:
        'સંસારની ધન-સંપત્તિ, રાજકીય પદ કે ભૌતિક વૈભવ જીવને સાચું સુખ આપી શકતા નથી. શ્રીકૃષ્ણના ચરણોમાં નિષ્કામ પ્રેમ અને અવિચળ ભક્તિ જ જીવનું પરમ કલ્યાણ કરે છે.',
  ),
  VartaModel(
    id: '9',
    number: '૦૯',
    titleGujarati: 'શ્રી હરિદાસ વૈષ્ણવની વાર્તા',
    titleBraj: 'હરિદાસ વૈષ્ણવ કી વાર્તા',
    shloka: 'नामस्मरणमात्रेण पापौघं नाशयेत् हरिः ॥ ९ ॥',
    arth:
        'શ્રીહરિના નામસ્મરણ માત્રથી જીવના તમામ પાપરાશિ અને દોષો ક્ષણવારમાં નાશ પામે છે.',
    vartaContent:
        '''શ્રી હરિદાસ વૈષ્ણવ શ્રીમહાપ્રભુજીના અતિશય કૃપાપાત્ર અને અનન્ય દાસ હતા. તેઓ સ્વભાવે અત્યંત સરળ, નમ્ર અને અહંકારરહિત હતા. તેમનો નિત્ય નિયમ હતો કે વાણીથી સદા શ્રીજીનું નામ સ્મરણ કરવું અને ચિત્તમાં શ્રીઆચાર્યજીના ચરણારવિંદનું ધ્યાન રાખવું.

જ્યારે તેઓ શ્રીમહાપ્રભુજીના શરણમાં આવ્યા, ત્યારે શ્રીઆચાર્યજીએ તેમને બ્રહ્મસંબંધ મંત્ર આપીને નામાશ્રયનો મહિમા સમજાવ્યો. શ્રી હરિદાસજીએ આ ઉપદેશને પોતાના હૃદયકમળમાં ઉતારી લીધો. તેઓ નિત્ય શ્રીકૃષ્ણના નામ કીર્તનમાં એવા લીન રહેતા કે તેમને લૌકિક સંસારનું સહેજ પણ ભાન ન રહેતું.

એક સમયની વાત છે કે, અજાણતાં તેમનાથી લૌકિક વ્યવહારમાં એક ભૂલ થઈ ગઈ, જેનાથી તેમના મનમાં અત્યંત પશ્ચાતાપ થયો. તેઓ ભયભીત થઈને શ્રીમહાપ્રભુજીના ચરણોમાં દોડી ગયા અને સાષ્ટાંગ પ્રણામ કરી અશ્રુભીની આંખોથી પોતાની ભૂલ સ્વીકારી. શ્રીમહાપ્રભુજીએ તેમની નિષ્કપટતા અને પશ્ચાતાપ જોઈને અત્યંત દયાર્દ્ર થઈને તેમને અભય આપ્યું અને કહ્યું કે, "જ્યારે જીવ અનન્ય ભાવથી શ્રીહરિના નામનો આશ્રય લે છે, ત્યારે પ્રભુ તેના સર્વ દોષો દૂર કરી તેનો સ્વીકાર કરે છે."

ત્યારબાદ હરિદાસજીએ પોતાના જીવનની પ્રત્યેક ક્ષણ શ્રીજીના નામજપ, ભગવદ્-ગુણગાન અને સત્સંગમાં જ સમર્પિત કરી દીધી. તેઓ જ્યાં પણ જતા ત્યાં ભગવદ્-નામનો એવો પ્રભાવ જાગ્રત કરતા કે વિમુખ જીવો પણ ભક્તિમાર્ગે વળી જતા. હરિદાસજીએ આખું જીવન અનન્ય નામાશ્રયનું દિવ્ય ઉદાહરણ બનીને વિતાવ્યું.''',
    saar:
        'માનવજીવથી અજાણતાં દોષ થઈ જાય તો પણ જો તે નિષ્કપટ હૃદયે પશ્ચાતાપ કરી શ્રીહરિના નામનો અવિચળ આશ્રય લે, તો પ્રભુ તેના સર્વ દોષો નષ્ટ કરીને તેને પોતાના દિવ્ય ચરણોમાં સ્થાન આપે છે.',
  ),
  VartaModel(
    id: '10',
    number: '૧૦',
    titleGujarati: 'શ્રી પુરુષોત્તમદાસ કાયસ્થની વાર્તા',
    titleBraj: 'પુરુષોત્તમદાસ કાયસ્થ કી વાર્તા',
    shloka: 'सेवा साधकभावेन करणीया सदा नृभिः ॥ १० ॥',
    arth:
        'મનુષ્યે નિત્ય સાધક ભાવથી અને નમ્ર ચિત્તે સંસારના કુરુક્ષેત્ર વચ્ચે પણ અનન્ય નિષ્ઠાપૂર્વક શ્રીઠાકોરજીની સેવા-સ્મરણ કરવું.',
    vartaContent:
        '''શ્રી પુરુષોત્તમદાસજી કાયસ્થ જ્ઞાતિના હતા અને વ્યાવહારિક કામકાજ તથા રાજકીય ચોપડાઓ સંભાળવાનું કારકુની કાર્ય કરતા હતા. સંસારના દરેક વ્યાવહારિક અને સરકારી કામકાજ વચ્ચે રહેવા છતાં તેમના મનમાં સદા ભગવદ્-પ્રાપ્તિની અદમ્ય તીવ્રતા રહેતી હતી.

જ્યારે શ્રીઆચાર્યજી મહાપ્રભુજી પૃથ્વી પરિક્રમા દરમિયાન ત્યાં પધાર્યા, ત્યારે પુરુષોત્તમદાસજી તેમના દિવ્ય દર્શન કરવા પહોંચ્યા. શ્રીમહાપ્રભુજીના તેજોમય સ્વરૂપ અને સુબોધિનીજીના અમૃતવચનો સાંભળીને તેમનું ચિત્ત તુરંત પ્રભુચરણોમાં પરોવાઈ ગયું. તેમણે શ્રીઆચાર્યજીના ચરણારવિંદમાં શરણાગતિ સ્વીકારી, સાષ્ટાંગ પ્રણામ કરી બ્રહ્મસંબંધ પ્રાપ્ત કર્યો.

બ્રહ્મસંબંધ લીધા બાદ પુરુષોત્તમદાસજીએ પોતાના ઘરમાં શ્રીઠાકોરજીનું સ્વરૂપ પધરાવ્યું. તેઓ સવારે વહેલા જાગીને શ્રીજીની સેવા પૂરા ભાવ, પ્રેમ અને સાવધાની સાથે અર્પિત કરતા. ત્યારબાદ જ પોતાના લૌકિક વ્યાપાર-કામકાજ માટે નીકળતા. લૌકિક કામકાજ કરતી વખતે પણ તેમનું ચિત્ત ઘરમાં વિરાજતા પોતાના શ્રીઠાકોરજીના શ્રંગાર, ભોગ અને મુખારવિંદના ધ્યાનમાં જ લીન રહેતું.

તેઓ પોતાના કમાયેલા ધનનો સદુપયોગ નિત્ય પધારેલા વૈષ્ણવોની સેવામાં અને શ્રીજીની સામગ્રીમાં જ કરતા. તેમના ઘરમાં નિત્ય મનોરથ અને ભગવદ્-કથા સત્સંગનો ઉત્સવ જેવો માહોલ રહેતો. પુરુષોત્તમદાસજી ક્યારેય પણ લૌકિક ઝંઝટો કે અડચણોને પોતાના સેવાભાવ વચ્ચે આવવા દેતા નહીં. તેમની આવી નિષ્કામ અને તન્મય સેવા જોઈને શ્રીમહાપ્રભુજી તેમના પર અત્યંત પ્રસન્ન રહ્યા.''',
    saar:
        'ગૃહસ્થાશ્રમ કે લૌકિક કામકાજ ભક્તિમાં ક્યારેય બાધક બનતા નથી. જો મનુષ્ય સાધક ભાવ રાખીને પોતાની તમામ ફરજો બજાવતા બજાવતા ચિત્ત શ્રીહરિના ચરણોમાં રાખે, તો તે સંસારમાં રહીને પણ ભગવદ્-કૃપાનો અધિકારી બને છે.',
  ),
