    number: '૧૧',
    titleGujarati: 'શ્રી કુંભનદાસજી ક્ષત્રિયની વાર્તા',
    titleBraj: 'કુંભનદાસજી ક્ષત્રિય કી વાર્તા',
    shloka: 'सन्तोष एव पुरुषस्य परं निधानम् ॥ ११ ॥',
    arth:
        'સંતોષ જ મનુષ્યનું સૌથી મોટું ધન છે. ભગવદ્-સેવામાં લીન રહેતા જીવે ક્યારેય રાજકીય વૈભવ કે લૌકિક સંપત્તિનો મોહ ન રાખવો જોઈએ.',
    vartaContent:
        '''શ્રી કુંભનદાસજી ક્ષત્રિય જ્ઞાતિના હતા અને વ્રજભૂમિના જામુનાવતા (જમુનાવત) ગામમાં રહેતા હતા. તેઓ અષ્ટછાપના પ્રથમ દિવ્ય કીર્તનકાર કવિ હતા. લૌકિક દ્રષ્ટિએ કુંભનદાસજી અત્યંત નિર્ધન હતા; તેઓ પોતાની જમીનમાં ખેતી કરીને ખેતીકામથી જ પોતાના કુટુંબનું ભરણપોષણ કરતા હતા. પરંતુ અલૌકિક દ્રષ્ટિએ તેઓ અત્યંત સમૃદ્ધ હતા, કારણ કે શ્રીઠાકોરજી (શ્રીનાથજી) પોતે તેમની સાથે સાક્ષાત વાર્તાલાપ કરતા અને તેમની લીલાઓમાં રસ લેતા હતા.

જ્યારે શ્રીઆચાર્યજી મહાપ્રભુજી ગોકુલ તથા ગિરિરાજજીની પરિક્રમા કરી રહ્યા હતા, ત્યારે કુંભનદાસજી તેમના શરણમાં આવ્યા. શ્રીમહાપ્રભુજીના દિવ્ય સ્વરૂપના દર્શન કરતાં જ કુંભનદાસજીના હૃદયમાં ભક્તિનો ઉદ્રેક થયો. તેમણે શ્રીઆચાર્યજી પાસે બ્રહ્મસંબંધ દીક્ષા ગ્રહણ કરી. દીક્ષા લીધા બાદ કુંભનદાસજીએ શ્રીનાથજીના ચરણોમાં કીર્તન સેવા કરવાનો પ્રારંભ કર્યો. તેમના પદો અને કીર્તનોમાં ગોપીજનોનો અનન્ય વિપ્રયોગ અને સાક્ષાત ભગવદ્-લીલાનો પરમ આનંદ પ્રગટ થતો હતો.

કુંભનદાસજીના અનન્ય ભક્તિભાવ અને મધુર કીર્તનની ખ્યાતિ ચારેય તરફ ફેલાઈ ગઈ. જ્યારે દિલ્હીના સમ્રાટ અકબરને કુંભનદાસજીના ભક્તિભાવ વિશે ખબર પડી, ત્યારે તેણે તેમને પોતાના દરબારમાં કીર્તન સંભળાવવા માટે ફતેહપુર સીકરી આમંત્રણ મોકલ્યું. પહેલા તો કુંભનદાસજીએ જવાની ના પાડી, પણ રાજાની આજ્ઞા હોવાથી ચાલતા ફતેહપુર સીકરી ગયા. દરબારમાં સમ્રાટ અકબરે તેમને કંઈક ગાઈ સંભળાવવા વિનંતી કરી.

કુંભનદાસજીએ રાજાને ખુશ કરવાને બદલે પોતાના ઈષ્ટદેવ શ્રીનાથજીના ચરણોનું કીર્તન ગાતાં પ્રસિદ્ધ પદ ગાયું:

"સંતન કો કહા સીકરી સોં કામ? અાવત જાત પનિહાં ટૂટી, બિસરી ગયો હરિનામ..."

(અર્થાત્: સંતોને સીકરી જેવા રાજદરબાર સાથે શું કામ હોય? અહીં આવતા-જતાં મારી પગરખાં તૂટી ગયાં અને ભગવાનનું દિવ્ય નામસ્મરણ ભુલાઈ ગયું.)

અકબરે કુંભનદાસજીની આવી અચળ નિષ્ઠા અને નિર્ભયતા જોઈને તેમને અપાર ધન-સંપત્તિ અને ઈનામ આપવા માંગ્યા, પણ કુંભનદાસજીએ કશું પણ લેવાનો ઇનકાર કર્યો અને માત્ર એટલું જ માગ્યું કે "મહારાજ! આપ મને ફરી ક્યારેય અહીં ન બોલાવશો અને મારી ભગવદ્-સેવામાં વિઘ્ન ન પાડશો." કુંભનદાસજીએ પોતાનું સંપૂર્ણ આયુષ્ય શ્રીજીના કીર્તન અને અનન્ય આશ્રયમાં જ વિતાવ્યું.''',
    saar:
        'સાચો ભક્ત ક્યારેય રાજકીય વૈભવ, ધન કે લૌકિક પ્રશંસાની લાલચ રાખતો નથી. તેના માટે તો ભગવાનના ચરણોની નિત્ય સેવા અને નામકીર્તન જ આ જગતનું સર્વોચ્ચ ધન છે.',
  ),
  VartaModel(
    id: '12',
    number: '૧૨',
    titleGujarati: 'શ્રી સૂરદાસજીની વાર્તા',
    titleBraj: 'સૂરદાસજી કી વાર્તા',
    shloka: 'पश्यन्ति ज्ञानचक्षुषा भावं भक्तिरसं परम् ॥ १२ ॥',
    arth:
        'ચર્મચક્ષુ (બાહ્ય આંખો) ન હોવા છતાં ભક્તો જ્ઞાનચક્ષુ અને ભક્તિભાવ વડે પ્રભુની અલૌકિક લીલાઓ અને રૂપના સાક્ષાત દર્શન કરે છે.',
    vartaContent:
        '''શ્રી સૂરદાસજી અષ્ટછાપ કવિઓમાં શિરોમણી અને પુષ્ટિમાર્ગના મહાન ભક્ત-કવિ હતા. તેઓ જન્માંધ (અથવા બાલ્યાવસ્થાથી દ્રષ્ટિહીન) હતા, પરંતુ ભગવાન તરફથી તેમને પરમ દિવ્ય દ્રષ્ટિ પ્રાપ્ત થઈ હતી. તેઓ સીહી નામના ગામમાં જન્મેલા અને બાદમાં ગોઘાટ (આગ્રા અને મથુરા વચ્ચે) આવીને રહેતા હતા. ત્યાં તેઓ પોતાની વૈરાગ્ય પૂર્ણ રચનાઓ અને હરિ-કીર્તન ગાતા હતા.

જ્યારે શ્રીઆચાર્યજી મહાપ્રભુજી પોતાની પૃથ્વી પરિક્રમા દરમિયાન ગોઘાટ પધાર્યા, ત્યારે સૂરદાસજી તેમના દિવ્ય દર્શન માટે આવ્યા. સૂરદાસજીએ શ્રીમહાપ્રભુજી સમક્ષ દીનતા ભરેલું પદ "મો સમ કો કુટિલ ખલ કામી..." ગાયું. શ્રીમહાપ્રભુજીએ તેમને અટકાવીને કહ્યું, "સૂર હોકે એસો ઘેઘિયાત કાહે કો હો? કછૂ ભગવદ્-લીલા વર્ણન કરો." (અર્થાત્: તમે 'સૂર' (સૂર્ય/શૂરવીર) થઈને આ રીતે દીનતા કેમ રડો છો? શ્રીકૃષ્ણની દિવ્ય લીલાઓનું વર્ણન કરો.)

ત્યારબાદ શ્રીમહાપ્રભુજીએ સૂરદાસજીને બ્રહ્મસંબંધ આપીને શ્રીમદ્ ભાગવતજીના દશમ સ્કંધની ગૂઢ લીલાઓનો દિવ્ય પ્રકાશ તેમના હૃદયમાં જાગ્રત કર્યો. દીક્ષા પ્રાપ્ત કરતા જ સૂરદાસજીના અંતરચક્ષુ ખુલી ગયા અને તેમને શ્રીનાથજીના બાલસ્વરૂપ અને રાસલીલાના સાક્ષાત દર્શન થવા લાગ્યા.

શ્રીમહાપ્રભુજી સૂરદાસજીને શ્રીનાથજીની કીર્તન સેવામાં શ્રીનાથદ્વારા (ગિરિરાજજી) લઈ આવ્યા. સૂરદાસજી રોજ શ્રીજીના શ્રંગાર અને ભાવ મુજબ અલૌકિક પદોની રચના કરીને કીર્તન કરતા. એકવાર શ્રીનાથજીને એવો શ્રંગાર ધરાવવામાં આવ્યો કે માત્ર મોતીની માળા જ હતી અને વસ્ત્ર નહોતા. કોઈએ પરીક્ષા લેવા સૂરદાસજીને પૂછ્યું કે "આજે શ્રીજીએ કેવા વસ્ત્ર ધારણ કર્યા છે?" ત્યારે નેત્રહીન સૂરદાસજીએ સાક્ષાત દર્શન કરીને પદ ગાયું:

"હરિ જુ કો દેખિ સબ ગાત ઉઘારો..." (અર્થાત્: આજે પ્રભુના અંગ પર કોઈ વસ્ત્ર નથી, માત્ર આભૂષણ જ શોભી રહ્યા છે.) આ સાંભળી સર્વ વૈષ્ણવો ચકિત થઈ ગયા. સૂરદાસજીએ 'સૂરસાગર' સહિત લાખો દિવ્ય પદોની રચના કરીને પોતાનું આખું જીવન શ્રીજીના ચરણોમાં સમર્પિત કર્યું.''',
    saar:
        'બાહ્ય આંખો કરતાં હૃદયની ભક્તિભાવ રૂપી દ્રષ્ટિ શ્રેષ્ઠ છે. ગુરુકૃપાથી જ્યારે જીવના અંતરચક્ષુ ખુલે છે, ત્યારે તેને પ્રભુની સચ્ચિદાનંદ લીલાના અખંડ દર્શન થાય છે.',
  ),

  VartaModel(
