    titleBraj: 'પરમાનંદદાસજી કી વાર્તા',
    shloka: 'आनन्दो परमानन्दः श्रीकृष्णे भक्तिरसेन च ॥ १३ ॥',
    arth:
        'શ્રીકૃષ્ણની અનન્ય ભક્તિરસના પ્રભાવથી જ જીવને અખંડ અને પરમ આનંદની પ્રાપ્તિ થાય છે.',
    vartaContent:
        '''શ્રી પરમાનંદદાસજી અષ્ટછાપ કવિઓમાં અગ્રગણ્ય અને દિવ્ય રસિક મહાત્મા હતા. તેમનો જન્મ કનૌજ (ઉત્તર પ્રદેશ) માં થયો હતો. તેઓ બાલ્યાવસ્થાથી જ સ્વભાવે અત્યંત વૈરાગ્યવાન, નમ્ર અને ભગવદ્-વિપ્રયોગથી વ્યાકુળ રહેતા હતા. તેઓ કનૌજ છોડીને રેણુકાક્ષેત્ર (રેણુકા ઘાટ) ખાતે આવીને વિરાજ્યા હતા અને ત્યાં રહીને ભગવાનના વિરહના પદો બનાવીને ગાયા કરતા હતા.

જ્યારે શ્રીઆચાર્યજી મહાપ્રભુજી પોતાની પૃથ્વી પરિક્રમા દરમિયાન રેણુકાક્ષેત્ર પધાર્યા, ત્યારે પરમાનંદદાસજી તેમના દિવ્ય દર્શન કરવા માટે આવ્યા. તેમણે શ્રીમહાપ્રભુજી સમક્ષ અત્યંત વ્યાકુળતા ભરેલું વિરહનું પદ ગાયું:

"હરિ કો સંગ જુ કૌ દિન માધો..."

શ્રીમહાપ્રભુજીએ તેમનું પદ સાંભળીને અત્યંત કૃપાદ્રષ્ટિ કરી અને કહ્યું કે, "પરમાનંદ! આ વિરહાવસ્થા છોડીને શ્રીકૃષ્ણની બાળલીલા અને દિવ્ય આનંદનું વર્ણન કરો." ત્યારબાદ શ્રીમહાપ્રભુજીએ તેમને બ્રહ્મસંબંધ મંત્ર આપીને પુષ્ટિમાર્ગીય દીક્ષા પ્રદાન કરી અને શ્રીમદ્ ભાગવતના દશમ સ્કંધની કથા સમજી ભગવદ્-લીલાનો પ્રકાશ આપ્યો.

દીક્ષા લીધા બાદ પરમાનંદદાસજીના હૃદયમાં પરમાનંદનો સાક્ષાત ઉદય થયો. શ્રીઆચાર્યજી તેમને ગોકુલ અને ગિરિરાજજી લઈ આવ્યા અને શ્રીનાથજીના કીર્તન સેવાની આજ્ઞા કરી. પરમાનંદદાસજી રોજ શ્રીજીના શ્રંગાર અને લીલા અનુસાર અલૌકિક પદોની રચના કરવા લાગ્યા. તેમના રચાયેલા પદો 'પરમાનંદ સાગર' નામે પ્રસિદ્ધ થયા, જેમાં શ્રીકૃષ્ણની બાલલીલા, વાત્સલ્ય ભાવ અને રાસલીલાનો અદભુત રસ છલકાય છે.

એકવાર શ્રીમહાપ્રભુજીના સુપુત્ર શ્રીગુંસાઈજી (શ્રીવિઠ્ઠલનાથજી) એ પરમાનંદદાસજીને શ્રીજીના શ્રંગારનું કીર્તન ગાવા કહ્યું. પરમાનંદદાસજીએ પદ ગાયું અને લીલામાં એવા તલ્લીન થઈ ગયા કે તેમને દેહનું સહેજ પણ ભાન ન રહ્યું. પરમાનંદદાસજીએ પોતાનું આખું જીવન સુરભિ કુંડ પાસે રહીને શ્રીજીના અખંડ સ્વરૂપાનંદ અને કીર્તનમાં જ સમર્પિત કર્યું.''',
    saar:
        'સંસારના ક્ષણભંગુર સુખોમાં પરમાનંદ નથી. સાચો અને અખંડ આનંદ તો માત્ર ગુરુકૃપા દ્વારા શ્રીકૃષ્ણની ચરણસેવા અને લીલા-સંકીર્તનમાં જ પ્રાપ્ત થાય છે.',
  ),

