    vartaContent:
        '''શ્રી ચતુર્ભુજદાસજી અષ્ટછાપ કવિઓમાંના એક મહાન કીર્તનકાર હતા. તેઓ શ્રીમહાપ્રભુજીના પરમ કૃપાપાત્ર સેવક શ્રી કુંભનદાસજીના સાતમા અને સૌથી નાના પુત્ર હતા. તેમનો જન્મ વ્રજભૂમિના જામુનાવતા ગામમાં થયો હતો. નાનપણથી જ તેમના ઘરમાં ભગવદ્-કથા, કીર્તન અને ગુરુસેવાનું દિવ્ય વાતાવરણ હતું.

જ્યારે શ્રીઆચાર્યજી મહાપ્રભુજીના દ્વિતીય આત્મજ શ્રીગુંસાઈજી (શ્રીવિઠ્ઠલનાથજી) વ્રજમાં લીલાઓ પ્રગટ કરી રહ્યા હતા, ત્યારે ચતુર્ભુજદાસજીએ શ્રીગુંસાઈજી પાસે બ્રહ્મસંબંધ પ્રાપ્ત કર્યો. શ્રીગુંસાઈજીની કૃપાદ્રષ્ટિ થતાં જ ચતુર્ભુજદાસજીના હૃદયમાં શ્રીનાથજીની બાલલીલા અને નિત્યલીલાનો પ્રકાશ થયો. તેઓ પોતાના પિતા કુંભનદાસજીની જેમ જ શ્રીજીના ચરણોમાં અદભુત પદોની રચના કરીને કીર્તન સેવા કરવા લાગ્યા.

ચતુર્ભુજદાસજીનો ભગવદ્-ભાવ એવો દિવ્ય હતો કે એકવાર જ્યારે તેઓ ગિરિરાજજી પર કીર્તન ગાઈ રહ્યા હતા, ત્યારે સાક્ષાત શ્રીજી તેમની સામે પ્રગટ થઈને રમવા લાગ્યા. તેઓ રાસલીલા અને શ્રીજીના જલવિહારના પદો ગાવામાં અતિશય નિપુણ હતા. તેમણે 'દ્વાદશ યશ' અને 'ચતુર્ભુજ કીર્તન સંગ્રહ' નામના ગ્રંથોની રચના કરી, જેમાં રાધા-કૃષ્ણના નિત્ય સ્વરૂપનું વર્ણન છે.

એકવાર કોઈ વિમુખ જીવે ચતુર્ભુજદાસજીની પરીક્ષા લેવા માટે લૌકિક લોભ આપ્યો, પરંતુ પિતાના સંસ્કારો અને ગુરુશ્રીગુંસાઈજીના આશ્રયના બળે તેમણે તે મોહનો ક્ષણવારમાં ત્યાગ કર્યો. ચતુર્ભુજદાસજીએ પોતાનું સંપૂર્ણ જીવન ગોવર્ધન પર્વતની તળેટીમાં રહી શ્રીનાથજીના કીર્તન અને ચરણસેવામાં જ સમર્પિત કર્યું.''',
    saar:
        'સંસ્કારી પરંપરા અને ગુરુકૃપાથી પ્રાપ્ત થયેલી ભક્તિ જીવને ક્યારેય ભટકવા દેતી નથી. શ્રીકૃષ્ણના ચરણોમાં અનન્ય પ્રીતિ રાખીને ગાવામાં આવતું એક-એક કીર્તન જીવના અજ્ઞાનને હરી લે છે.',
