    vartaContent:
        '''શ્રી કૃષ્ણદાસજી (કૃષ્ણદાસ અધિકારી) અષ્ટછાપ કવિઓમાંના એક દિવ્ય રસિક અને પ્રબંધક હતા. તેમનો જન્મ ગુજરાતના ખેડા જિલ્લાના ચરોતર વિસ્તારના આસોજ (અથવા પાટણ) ગામમાં એક ક્ષત્રિય કણબી પરિવારમાં થયો હતો. તેઓ બાલ્યાવસ્થાથી જ અત્યંત બુદ્ધિશાળી, વ્યવહારકુશળ અને અતિશય તેજસ્વી હતા.

જ્યારે શ્રીઆચાર્યજી મહાપ્રભુજી પોતાની પૃથ્વી પરિક્રમા દરમિયાન ગુજરાત પધાર્યા, ત્યારે કૃષ્ણદાસજી તેમના દર્શને આવ્યા. શ્રીમહાપ્રભુજીના અલૌકિક સ્વરૂપના દર્શનથી તેમનું હૃદય પીગળી ગયું અને તેમણે તુરંત શ્રીઆચાર્યજીના ચરણોમાં શરણાગતિ સ્વીકારી બ્રહ્મસંબંધ પ્રાપ્ત કર્યો. શ્રીમહાપ્રભુજીએ કૃષ્ણદાસજીની અદભુત કાર્યક્ષમતા અને બુદ્ધિમત્તા જોઈને તેમને શ્રીનાથજી મંદિર (શ્રીનાથદ્વારા/ગોવર્ધન) ના 'અધિકારી' (મુખ્ય પ્રબંધક) નો હોદ્દો સોંપ્યો.

કૃષ્ણદાસજીએ શ્રીજી મંદિરની તમામ વ્યવસ્થા, રસોઈ, ભંડાર અને બાંધકામ અત્યંત કુશળતાથી સંભાળ્યા. પરંતુ મોટો હોદ્દો હોવાના કારણે સમય જતાં તેમના મનમાં થોડો અહંકાર પ્રવેશી ગયો. આ અહંકારના કારણે એકવાર તેમણે શ્રીમહાપ્રભુજીના દ્વિતીય આત્મજ શ્રીગુંસાઈજી (શ્રીવિઠ્ઠલનાથજી) સાથે પણ લૌકિક મર્યાદા ચૂકવાનો પ્રયત્ન કર્યો. પરંતુ શ્રીગુંસાઈજીની અલૌકિક કૃપા અને ભગવદ્-ઈચ્છાથી કૃષ્ણદાસજીને પોતાની ભૂલનો તીવ્ર પશ્ચાતાપ થયો.

તેમણે પોતાના અહંકારનો સંપૂર્ણ ત્યાગ કર્યો અને પોતાના દોષની ક્ષમા માગી. ત્યારબાદ કૃષ્ણદાસજીનું હૃદય સંપૂર્ણ નિર્મળ થઈ ગયું. તેમણે શ્રીનાથજી અને શ્રીજીના સ્વરૂપની પ્રીતિમાં અલૌકિક પદોની રચના કરી. તેમની અનન્ય ભક્તિ અને કીર્તનો સાંભળીને શ્રીનાથજી પોતે સાક્ષાત પ્રસન્ન થતા હતા. કૃષ્ણદાસજીએ પોતાનું આખું જીવન શ્રીજીના ચરણોમાં જ સમર્પિત કરી દીધું.''',
    saar:
        'ભગવદ્-સેવામાં કે સંસ્થાકીય હોદ્દામાં અહંકાર અને સ્વાર્થ મોટામાં મોટો બાધક છે. અહંકાર છોડીને નમ્ર ચિત્તે ગુરુ અને ભગવાનની સેવા કરવાથી જ સાચો ભક્તિરસ અને ભગવદ્-કૃપા પ્રાપ્ત થાય છે.',
  ),

