        'દિવ્ય સંગીત અને શ્રીકૃષ્ણની લીલા-કીર્તન દ્વારા ભક્ત પોતાના તથા અન્ય જીવોના મનને સંસારમાંથી હરીને ભગવદ્-ચરણમાં પ્રોય છે.',
    vartaContent:
        '''શ્રી ગોવિંદસ્વામી અષ્ટછાપ કવિઓમાંના એક પરમ રસિક અને મહાન સંગીતકાર ભક્ત હતા. તેમનો જન્મ રાજસ્થાનના અંંતરી ગામમાં સાનોઢિયા બ્રાહ્મણ કુળમાં થયો હતો. તેઓ બાલ્યાવસ્થાથી જ સ્વભાવે નિર્મોહી, વિરક્ત અને સંગીત વિદ્યામાં અત્યંત નિપુણ હતા. તેઓ ગૃહત્યાગ કરીને મહાવન (ગોકુલ) માં આયીને રહેવા લાગ્યા હતા અને ત્યાં રહીને ભગવાનના કીર્તન ગાયા કરતા હતા.

જ્યારે શ્રીમહાપ્રભુજીના દ્વિતીય આત્મજ શ્રીગુંસાઈજી (શ્રીવિઠ્ઠલનાથજી) વ્રજમાં લીલાઓ પ્રગટ કરી રહ્યા હતા, ત્યારે ગોવિંદસ્વામી તેમના અલૌકિક સ્વરૂપના દર્શન કરી અતિશય આકર્ષાયા. તેમણે શ્રીગુંસાઈજીના ચરણોમાં શરણાગતિ સ્વીકારીને બ્રહ્મસંબંધ પ્રાપ્ત કર્યો. શ્રીગુંસાઈજીની કૃપાથી તેમના હૃદયમાં શ્રીનાથજીની લીલાઓનો પ્રકાશ થયો અને તેમણે શ્રીજીના કીર્તન સેવાનો પ્રારંભ કર્યો.

ગોવિંદસ્વામી સંગીતના એવા ઉત્કાંડ વિદ્વત્તા ધરાવતા હતા કે દિલ્હીના સમ્રાટ અકબરના દરબારી સંગીતસમ્રાટ તાનસેન પણ ગુપ્ત વેશ ધારણ કરીને ગોવિંદસ્વામીના પદો અને રાગ-રાગિણીઓ સાંભળવા વ્રજમાં કદંબખંડી (ગોવિંદકુંડ) ખાતે આવતા હતા. તાનસેને ગોવિંદસ્વામી પાસેથી સંગીતના અનેક ગૂઢ રાગોનું જ્ઞાન મેળવ્યું હતું.

ગોવિંદસ્વામીનો શ્રીજી પ્રત્યેનો ભાવ અતિશય બાળભાવ અને સખ્યભાવનો હતો. તેઓ શ્રીનાથજી સાથે સખી અને બાલસખા રૂપે રમતા અને કીર્તન સંભળાવતા. એકવાર તેઓ રાસલીલા અને શ્રંગારના પદો ગાઈ રહ્યા હતા ત્યારે શ્રીજી પોતે પ્રગટ થઈને તેમની સાથે વ્રજલીલા રમ્યા હતા. ગોવિંદસ્વામીએ પોતાનું સમગ્ર આયુષ્ય ગોવર્ધન પર્વત પર કદંબખંડી પાસે રહીને શ્રીજીના અખંડ કીર્તન અને સ્વરૂપાનંદમાં જ વ્યતીત કર્યું.''',
    saar:
        'કળા, વિદ્યા કે સંગીત જ્યારે ભગવાનના ચરણોમાં સમર્પિત થાય છે, ત્યારે તે કેવળ મનોરંજન ન રહેતા સાક્ષાત ભગવદ્-પ્રાપ્તિનું સાધન બની જાય છે.',
  ),

  VartaModel(
    id: '17',
    number: '૧૭',
    titleGujarati: 'શ્રી છીતસ્વામીની વાર્તા',
    titleBraj: 'છીતસ્વામી કી વાર્તા',
    shloka: 'कपटं च परित्यज्य भजेत् श्रीवल्लभं प्रभुम् ॥ १७ ॥',
    arth:
        'કપટ, અહંકાર અને મનની ચાતુરીનો સંપૂર્ણ ત્યાગ કરીને શ્રીવલ્લભ પ્રભુના ચરણારવિંદમાં શરણાગતિ સ્વીકારવી.',
    vartaContent:
        '''શ્રી છીતસ્વામી અષ્ટછાપ કવિઓમાંના એક મહાન રસિક ભક્ત હતા. તેઓ મથુરાના ચૌબે (ચાતુર્વેદી બ્રાહ્મણ) પરિવારના હતા. પ્રારંભિક જીવનમાં તેઓ અત્યંત અહંકારી, ચતુર અને વિદ્રૂપ સ્વભાવના હતા. તેઓ પોતાના પાંડિત્ય અને વંશના અહંકારમાં લીન રહીને સાધુ-સંતો અને વૈષ્ણવોની મજાક ઉડાવતા તથા તેમની પરીક્ષા લેવાના કપટ પૂર્ણ પ્રયાસો કરતા હતા.

એકવાર તેમણે શ્રીઆચાર્યજી મહાપ્રભુજીના દ્વિતીય આત્મજ શ્રીગુંસાઈજી (શ્રીવિઠ્ઠલનાથજી) ની પરીક્ષા લેવાનું વિચાર્યું. છીતસ્વામીએ એક ખોટો (તાંબાનો) ખોટો રૂપિયો બનાવડાવ્યો અને નાળિયેર લઈને શ્રીગુંસાઈજીની પરીક્ષા લેવા તેમના દરબારમાં પહોંચ્યા. તેમણે શ્રીગુંસાઈજીને પ્રણામ કરીને તે ખોટો રૂપિયો અને નાળિયેર ભેટ તરીકે ચરણોમાં મૂક્યા.

અંતર્યામી શ્રીગુંસાઈજી તેમની મનોવૃત્તિ સમજી ગયા. શ્રીગુંસાઈજીએ સહેજ હસીને તે તાંબાના ખોટા રૂપિયાને હાથમાં લીધો, તો ક્ષણવારમાં જ શ્રીગુંસાઈજીના અલૌકિક સ્પર્શથી તે ખોટો રૂપિયો શુદ્ધ સોનાનો બની ગયો! આ અદભુત અને ચમત્કારિક દિવ્ય દર્શન કરીને છીતસ્વામી સ્તબ્ધ થઈ ગયા. તેમનો તમામ અહંકાર અને કપટ ક્ષણભરમાં ઓગળી ગયા. તેમને પશ્ચાતાપ થયો કે તેઓ સાક્ષાત પરબ્રહ્મની પરીક્ષા લઈ રહ્યા હતા.

છીતસ્વામી તુરંત જ શ્રીગુંસાઈજીના ચરણોમાં સાષ્ટાંગ પ્રણામ કરી અશ્રુભીની આંખોથી ક્ષમા માંગવા લાગ્યા. શ્રીગુંસાઈજીએ અત્યંત કૃપા કરીને તેમને અભય આપ્યું અને બ્રહ્મસંબંધ મંત્ર આપ્યો. દીક્ષા લીધા પછી છીતસ્વામી સંપૂર્ણ બદલાઈ ગયા. તેમણે પોતાના અહંકારનો ત્યાગ કરીને શ્રીનાથજીની કીર્તન સેવામાં પોતાનું જીવન સમર્પિત કર્યું.

તેમણે શ્રીગુંસાઈજી અને શ્રીજીના સ્વરૂપની પ્રીતિમાં પ્રસિદ્ધ પદ રચ્યું:

"હે અહો શ્રીવિઠ્ઠલ ગિરિધર રાય..."

છીતસ્વામીએ પોતાનું આખું જીવન પૂછરીના લોટા (ગિરિરાજજી) પાસે રહીને શ્રીજીના અખંડ ગુણગાનમાં વિતાવ્યું.''',
    saar:
        'કપટ કે અહંકારથી પ્રભુ કે ગુરુની પરીક્ષા કરી શકાતી નથી. જ્યારે જીવ પોતાના મનની ચાતુરી છોડીને નિષ્કપટ ભાવે શરણે આવે છે, ત્યારે જ તેને ભક્તિ અને કૃપાનો દિવ્ય અનુભવ થાય છે.',
  ),

  VartaModel(
    id: '18',
    number: '૧૮',
    titleGujarati: 'શ્રી નંદદાસજીની વાર્તા',
    titleBraj: 'નંદદાસજી કી વાર્તા',
    shloka: 'काव्येन भक्ती रसेन च श्रीकृष्णे मन अर्पणम् ॥ १८ ॥',
    arth:
        'પોતાના દિવ્ય કાવ્ય અને ભક્તિરસ દ્વારા મનને સંસારમાંથી હટાવીને સંપૂર્ણપણે શ્રીકૃષ્ણના ચરણારવિંદમાં અર્પિત કરવું.',
    vartaContent:
        '''શ્રી નંદદાસજી અષ્ટછાપ કવિઓમાંના એક અગ્રગણ્ય અને પરમ વિદ્વાન કવિ-ભક્ત હતા. તેઓ ઉત્તર પ્રદેશના રામપુર (શૂકરક્ષેત્ર/રામઘાટ) ના સનાઢ્ય બ્રાહ્મણ હતા અને પ્રસિદ્ધ કવિ તુલસીદાસજીના ભાઈ (અથવા સમકાલીન ગુરુભાઈ) માનવામાં આવે છે. નંદદાસજી પ્રારંભથી જ અત્યંત ચતુર, સંસ્કૃત અને ભાષા કાવ્યમાં પ્રવીણ હતા.

શરૂઆતમાં નંદદાસજીનું ચિત્ત એક લૌકિક સ્ત્રી પ્રત્યે આકર્ષાયેલું હતું અને તેઓ તેના મોહમાં વ્યાકુળ રહેતા હતા. પરંતુ તે જ સમયે શ્રીઆચાર્યજી મહાપ્રભુજીના દ્વિતીય આત્મજ શ્રીગુંસાઈજી (શ્રીવિઠ્ઠલનાથજી) એ તેમના પર દિવ્ય કૃપાદ્રષ્ટિ કરી. શ્રીગુંસાઈજીના અલૌકિક સ્વરૂપના દર્શન થતાં જ નંદદાસજીનો લૌકિક મોહ ક્ષણવારમાં દૂર થઈ ગયો અને તેમનું ચિત્ત પરબ્રહ્મ શ્રીકૃષ્ણની બાલલીલા અને રાસલીલા તરફ વળી ગયું.

નંદદાસજીએ શ્રીગુંસાઈજી પાસે બ્રહ્મસંબંધ પ્રાપ્ત કર્યો. દીક્ષા લીધા બાદ તેમણે પોતાની વિદ્વાન શક્તિ અને કાવ્યકળાને સંપૂર્ણપણે શ્રીજીની સેવામાં સમર્પિત કરી દીધી. તેમણે 'રાસપંચાધ્યાયી', 'ભંવરગીત', 'રૂપમંજરી' અને 'રસમંજરી' જેવા અદભુત સંસ્કૃત તથા વ્રજભાષાના દિવ્ય ગ્રંથોની રચના કરી. કાવ્યજગતમાં તેમની ઉપમાઓ અને રાસલીલાના વર્ણન માટે કહેવત પ્રસિદ્ધ થઈ:

"ઓર સબ કવિ ગઢિયા, નંદદાસ જડ઼િયા..."

(અર્થાત્: અન્ય કવિઓ માત્ર ઘડે છે, પરંતુ નંદદાસજી કાવ્યમાં રત્નો જડે છે.)

નંદદાસજી નિત્ય માનસી સેવા અને શ્રીનાથજીના કીર્તનમાં લીન રહેતા. તેમણે પોતાનું આખું જીવન ગિરિરાજજીની તળેટીમાં (માનસી ગંગા પાસે) રહીને શ્રીજીના સ્વરૂપાનંદ અને કીર્તનમાં જ વિતાવ્યું.''',
    saar:
        'માનવ મનનું લૌકિક આકર્ષણ કે મોહ જ્યારે ગુરુકૃપાથી અલૌકિક ભગવદ્-પ્રેમમાં પરિણમે છે, ત્યારે જીવનું અહંકારયુક્ત જીવન પરમ કલ્યાણ અને ભક્તિરસનો દિવ્ય સ્ત્રોત બની જાય છે.',
