    titleBraj: 'નારાયણદાસ કાયસ્થ કી વાર્તા',
    shloka: 'निष्कपट भावयुक्तस्य श्रीकृष्णे विमला मतिः ॥ १९ ॥',
    arth:
        'જે જીવનું હૃદય નિષ્કપટ હોય છે, તેની બુદ્ધિ અને મતિ સાક્ષાત પરબ્રહ્મ શ્રીકૃષ્ણના ચરણોમાં નિર્મળ થઈને સ્થિર થાય છે.',
    vartaContent:
        '''શ્રી નારાયણદાસજી કાયસ્થ જ્ઞાતિના હતા અને વહિવટી તથા રાજકીય કાર્ય સાથે જોડાયેલા એક હોશિયાર વ્યક્તિ હતા. સંસારના દરેક વ્યાવહારિક અને રાજકીય કાવતરાંઓ વચ્ચે રહેવા છતાં તેમના અંતરમાં સહજ નિષ્કપટતા, નમ્રતા અને ભગવદ્-વિપ્રયોગની તીવ્ર લાગણી હતી.

જ્યારે શ્રીઆચાર્યજી મહાપ્રભુજી પૃથ્વી પરિક્રમા દરમિયાન ત્યાં પધાર્યા, ત્યારે નારાયણદાસજી તેમના દિવ્ય દર્શને આવ્યા. શ્રીમહાપ્રભુજીના મુખારવિંદમાંથી ઝરતી કથા અને પુષ્ટિમાર્ગનો સિદ્ધાંત સાંભળતાં જ નારાયણદાસજીનું હૃદયદ્રવિત થઈ ગયું. તેમણે તુરંત શ્રીમહાપ્રભુજીના ચરણોમાં સાષ્ટાંગ પ્રણામ કર્યા અને બ્રહ્મસંબંધ પ્રાપ્ત કર્યો.

દીક્ષા લીધા બાદ નારાયણદાસજીએ પોતાના લૌકિક પદ કે ચાતુરીનો કોઈ અહંકાર ન રાખ્યો. તેમણે પોતાના ઘરમાં શ્રીઆચાર્યજીની આજ્ઞાનુસાર શ્રીઠાકોરજીની સેવા પધરાવી. તેઓ રાજકીય નોકરી-ધંધો માત્ર ફરજ ખાતર કરતા, પરંતુ તેમનું ચિત્ત સદા ઘરમાં વિરાજતા પોતાના શ્રીજીના ધ્યાનમાં જ લીન રહેતું.

એકવાર રાજાના દરબારમાં કેટલાક ઈર્ષાળુ લોકોએ નારાયણદાસજી વિરુદ્ધ ખોટો આરોપ લગાવ્યો અને તેમને કઠિન પરિસ્થિતિમાં મૂકવાનો પ્રયત્ન કર્યો. પરંતુ નારાયણદાસજીએ સહેજ પણ ચિંતા કર્યા વગર માત્ર શ્રીજીના અનન્ય આશ્રયનો સહારો લીધો. શ્રીઠાકોરજીએ તેમની નિષ્કપટ ભક્તિ જોઈને રાજાના મનમાં સત્ય પ્રગટ કર્યું, જેથી રાજાએ નારાયણદાસજીનો ન્યાય કરીને ઈર્ષાળુઓને શિક્ષા કરી અને નારાયણદાસજીનો સત્કાર કર્યો.

નારાયણદાસજીએ આખું જીવન લૌકિક અડચણો વચ્ચે પણ શ્રીહરિના નામસ્મરણ અને ગુરુભક્તિનો ત્યાગ ન કર્યો અને અનન્ય સેવા ભાવમાં જ પોતાનું આયુષ્ય વિતાવ્યું.''',
    saar:
