        'સર્વ ભાવથી અને અહંકારરહિત થઈને શ્રીવલ્લભના ચરણકમળનો અવિચળ આશ્રય સ્વીકારવો.',
    vartaContent:
        '''શ્રી તુલસીદાસજી કાયસ્થ જ્ઞાતિના હતા અને તેઓ પણ સરકારી તથા વ્યાવહારિક દફતર સંભાળવાના કારકુની કાર્યમાં સંકળાયેલા હતા. તેઓ સ્વભાવે અત્યંત શાંત, ગંભીર અને સદા ભગવદ્-મહિમાનું ચિંતન કરનારા હતા.

જ્યારે શ્રીઆચાર્યજી મહાપ્રભુજી પોતાની ભારત પરિક્રમા દરમિયાન ત્યાં પધાર્યા, ત્યારે તુલસીદાસજી તેમના દર્શને આવ્યા. શ્રીમહાપ્રભુજીના તેજોમય સ્વરૂપ અને સુબોધિનીજીના અમૃતવચનો સાંભળીને તેમનું ચિત્ત તુરંત પ્રભુચરણોમાં ચોંટી ગયું. તેમણે શ્રીઆચાર્યજીના ચરણોમાં સાષ્ટાંગ પ્રણામ કર્યા અને બ્રહ્મસંબંધ પ્રાપ્ત કર્યો.

બ્રહ્મસંબંધ લીધા બાદ તુલસીદાસજીએ પોતાના ઘરમાં શ્રીઆચાર્યજીની આજ્ઞાનુસાર શ્રીઠાકોરજી પધરાવ્યા. તેઓ નિત્ય સવારે વહેલા જાગીને અત્યંત સાવધાની અને પ્રીતિપૂર્વક શ્રીજીની સેવા અર્પિત કરતા અને ત્યારબાદ જ પોતાના વ્યાવહારિક કામકાજ માટે નીકળતા. નોકરી અને કામકાજના સમયે પણ તેમનું મન ઘરમાં વિરાજતા પોતાના ઈષ્ટદેવ શ્રીઠાકોરજીના મુખારવિંદના ધ્યાનમાં જ લીન રહેતું.

એકવાર તેમના વ્યાવહારિક કામકાજમાં એક મોટું સંકટ આવ્યું અને લૌકિક દ્રષ્ટિએ મોટું નુકસાન થાય તેવી પરિસ્થિતિ સર્જાઈ. પરંતુ તુલસીદાસજીએ સહેજ પણ ગભરાયા વિના તમામ ભાર પોતાના શ્રીજી પર છોડી દીધો. તેમની અનન્ય ભક્તિ અને અવિચળ આશ્રય જોઈને શ્રીજીએ સાક્ષાત તેમના સંકટને દૂર કર્યું અને તેમનું કાર્ય પૂરું કરાવ્યું. તુલસીદાસજીએ આખું જીવન અનન્ય આશ્રય અને ગુરુભક્તિમાં જ વિતાવ્યું.''',
    saar:
        'સંસારના કોઈ પણ કામકાજ કે સંકટ વચ્ચે પણ જો જીવનો ભગવાન પરનો વિશ્વાસ અને ગુરુઆશ્રય અચળ રહે, તો ભગવાન સાક્ષાત પોતાના ભક્તની રક્ષા કરે છે.',
