જ્યારે શ્રીઆચાર્યજી મહાપ્રભુજી પોતાની પૃથ્વી પરિક્રમા દરમિયાન ત્યાંથી પસાર થઈ રહ્યા હતા, ત્યારે ગોપાલદાસજી તેમના દિવ્ય દર્શને આવ્યા. શ્રીમહાપ્રભુજીના મુખારવિંદમાંથી ઝરતા વાણી-અમૃત સાંભળીને તેમનું મન ભક્તિભાવમાં ભીંજાઈ ગયું. તેમણે તુરંત શ્રીઆચાર્યજીના ચરણોમાં સાષ્ટાંગ પ્રણામ કર્યા અને શરણાગતિ સ્વીકારીને બ્રહ્મસંબંધ પ્રાપ્ત કર્યો.

બ્રહ્મસંબંધ લીધા બાદ ગોપાલદાસજીએ પોતાના ઘરમાં શ્રીઆચાર્યજીની આજ્ઞા મુજબ શ્રીઠાકોરજીની સેવા પધરાવી. તેઓ રોજ સવારે વહેલા જાગીને પૂર્ણ ભાવ અને પવિત્રતાથી શ્રીજીની સેવા અર્પિત કરતા. પોતાના લૌકિક કામકાજ દરમિયાન પણ તેમનું ચિત્ત સદા શ્રીજીના ચરણારવિંદના ધ્યાનમાં જ પરોવાયેલું રહેતું.

એકવાર તેમના વ્યાવહારિક અને સરકારી હિસાબોમાં એક મોટી ભૂલ ઊભી થઈ, જેનાથી તેમના પર મોટું સંકટ અને લૌકિક બદનામી આવે તેમ હતું. પરંતુ ગોપાલદાસજીએ સહેજ પણ અધીરા થયા વિના પોતાના ઈષ્ટદેવ શ્રીજી અને ગુરુશ્રીમહાપ્રભુજીના ચરણોનું સ્મરણ કર્યું. તેમની નિષ્કપટ ગુરુભક્તિ જોઈને શ્રીજીએ એવી અલૌકિક કૃપા કરી કે તે હિસાબની ભૂલ આપોઆપ ઉકેલાઈ ગઈ અને તેમનો ન્યાય થયો. ગોપાલદાસજીએ સમગ્ર આયુષ્ય અનન્ય આશ્રય અને પ્રભુસેવામાં જ વ્યતીત કર્યું.''',
    saar:
        'જીવ જ્યારે પોતાના અહંકારનો ત્યાગ કરીને નિષ્કપટ ભાવે શ્રીગુરુદેવ અને ભગવાનના ચરણોનો આશ્રય લે છે, ત્યારે શ્રીગુરુદેવ પોતે તેના દરેક સંકટોનું નિવારણ કરીને તેનું રક્ષણ કરે છે.',
