    titleGujarati: 'શ્રી દામોદરદાસ હરસાનીની વાર્તા',
    titleBraj: 'દામોદરદાસ હરસાની કી વાર્તા',
    shloka: 'गुरुसेवा परं सत्यं सर्वशास्त्रेषु निश्चितम् ॥ २२ ॥',
    arth:
        'સર્વ શાસ્ત્રોનો નિશ્ચિત સિદ્ધાંત છે કે શ્રીગુરુદેવની નિષ્કામ અને અનન્ય સેવા જ પરમ સત્ય તથા ભગવદ્-પ્રાપ્તિનો શ્રેષ્ઠ માર્ગ છે.',
    vartaContent:
        '''શ્રી દામોદરદાસ હરસાનીજી શ્રીઆચાર્યજી મહાપ્રભુજીના સર્વોચ્ચ અને પ્રથમ ક્રમના મુખ્ય સેવક હતા. તેઓ મૂળ કનોજ (ઉત્તર પ્રદેશ) ના બ્રાહ્મણ હતા. તેમને શ્રીમહાપ્રભુજીના 'અંતરંગ સેવક' અને 'પ્રથમ સાથી' માનવામાં આવે છે. તેઓ સ્વભાવે જ્ઞાની, અત્યંત વિવેકી અને ગુરુચરણોમાં સંપૂર્ણપણે સમર્પિત હતા.

જ્યારે શ્રીઆચાર્યજી મહાપ્રભુજીએ પૃથ્વી પરિક્રમાનો પ્રારંભ કર્યો, ત્યારે દામોદરદાસજી (જેમને વલ્લભીય સંપ્રદાયમાં પ્રેમથી 'દામલાજી' કહેવામાં આવે છે) સૌથી પહેલાં શ્રીમહાપ્રભુજીના શરણમાં આવ્યા. તેમણે સૌથી પ્રથમ બ્રહ્મસંબંધ દીક્ષા ગ્રહણ કરી. શ્રીમહાપ્રભુજી જ્યાં પણ જતા, દામોદરદાસજી તેમની સાથે છાયાની જેમ રહેતા અને શ્રીજીની તથા શ્રીઆચાર્યજીની અનન્ય સેવા કરતા.

દામોદરદાસજીનો સિદ્ધાંત અને ગુરુનિષ્ઠા અજોડ હતા. તેઓ સદા માનતા કે "શ્રીઆચાર્યજી મહાપ્રભુજીના ચરણારવિંદનો આશ્રય એ જ મારા માટે સાક્ષાત પુરુષોત્તમ પ્રાપ્ત કરવા સમાન છે." તેમણે ક્યારેય પણ શ્રીઆચાર્યજીની આજ્ઞાનું અનાદર કર્યું નહોતું.

એકવાર કોઈ જ્ઞાની વ્યક્તિએ દામોદરદાસજીને મોક્ષ કે શાસ્ત્રચર્ચા વિશે પૂછ્યું, ત્યારે દામોદરદાસજીએ કહ્યું કે, "અમારો મોક્ષ કે કલ્યાણ તો શ્રીવલ્લભના ચરણોની સેવામાં જ છે. તેનાથી પર અમારે કશું જ જોઈતું નથી." શ્રીમહાપ્રભુજી પણ દામોદરદાસજી પર અતિશય પ્રસન્ન રહેતા અને સંપ્રદાયના ગૂઢ સિદ્ધાંતોની ચર્ચા નિત્ય તેમની સાથે કરતા. દામોદરદાસજીએ પોતાનું સંપૂર્ણ આયુષ્ય શ્રીમહાપ્રભુજીની નિત્ય સેવા અને સંપ્રદાયના પ્રચાર-પ્રસારમાં જ સમર્પિત કર્યું.''',
    saar:
        'શ્રીગુરુદેવના ચરણોમાં અનન્ય નિષ્ઠા અને સમર્પણ જ જીવ માટે ઉત્તમ ભક્તિનું સ્વરૂપ છે. ગુરુની સેવા અને આજ્ઞાપાલનથી જ પરબ્રહ્મની કૃપા સહજ રીતે પ્રાપ્ત થાય છે.',
  ),

