    vartaContent:
        '''શ્રી દામોદરદાસજી સંભલ (ઉત્તર પ્રદેશ) નગરના વતની હતા. તેઓ વ્યવસાયે એક અત્યંત પ્રતિષ્ઠિત અને સફળ વ્યાપારી હતા. લૌકિક રીતે તેમનો મોટો વેપાર અને પરિવાર હતો, પરંતુ તેમના હૃદયમાં પૂર્વજન્મના સંસ્કારોને કારણે ભગવદ્-પ્રાપ્તિની અદમ્ય તીવ્રતા રહેતી હતી.

જ્યારે શ્રીઆચાર્યજી મહાપ્રભુજી પોતાની પૃથ્વી પરિક્રમા દરમિયાન સંભલ નગર પધાર્યા, ત્યારે દામોદરદાસજી તેમના દિવ્ય દર્શને આવ્યા. શ્રીમહાપ્રભુજીના તેજોમય સ્વરૂપ અને સુબોધિનીજીની કથા સાંભળીને તેમનું મન ભક્તિરંગમાં રંગાઈ ગયું. તેમણે શ્રીઆચાર્યજીના ચરણોમાં સાષ્ટાંગ પ્રણામ કરીને શરણાગતિ સ્વીકારી અને બ્રહ્મસંબંધ પ્રાપ્ત કર્યો.

દીક્ષા લીધા બાદ દામોદરદાસજીએ પોતાના ઘરમાં શ્રીઆચાર્યજીની આજ્ઞાનુસાર શ્રીઠાકોરજી પધરાવ્યા. તેઓ નિત્ય સવારે વહેલા જાગીને પૂર્ણ ભાવ અને સાવધાનીપૂર્વક શ્રીજીની સેવા અર્પિત કરતા અને ત્યારબાદ જ પોતાના વ્યાપાર-ધંધા માટે નીકળતા. વેપાર કરતી વખતે પણ તેમનું ધ્યાન સદા શ્રીજીના ચરણોમાં રહેતું.

એકવાર તેમના વેપારમાં મોટો આર્થિક ઉતાર-ચડાવ આવ્યો અને લૌકિક રીતે ભારે નુકસાન થવાની સ્થિતિ ઊભી થઈ. પરંતુ દામોદરદાસજીએ સહેજ પણ વિચલિત થયા વિના તમામ ભાર પોતાના શ્રીજી પર છોડી દીધો અને સેવા-સ્મરણ ચાલુ રાખ્યું. તેમની આવી અવિચળ નિષ્ઠા જોઈને શ્રીજીએ તેમની સર્વ મુશ્કેલીઓ દૂર કરી. દામોદરદાસજીએ પોતાનું આખું જીવન અનન્ય આશ્રય, ભગવદ્-સેવા અને સાધુ-વૈષ્ણવોની સેવામાં જ સમર્પિત કર્યું.''',
    saar:
        'ગૃહસ્થાશ્રમ કે લૌકિક વ્યાપાર ભક્તિમાર્ગમાં ક્યારેય બાધક બનતા નથી. જો મનુષ્ય સંસારમાં રહીને પણ પોતાનું ચિત્ત ભગવાન અને ગુરુચરણોમાં અર્પિત રાખે, તો તે પરમ કૃપાનો અધિકારી બને છે.',
  ),

  VartaModel(
