    titleBraj: 'રામદાસ મેડતાવાળા કી વાર્તા',
    shloka: 'सर्व त्यागेन लभ्येत भक्तिः श्रीवल्लभे दृढा ॥ २४ ॥',
    arth:
        'લૌકિક મોહ અને અહંકારનો સંપૂર્ણ ત્યાગ કરવાથી જ શ્રીવલ્લભના ચરણોમાં અવિચળ અને દ્રઢ ભક્તિ પ્રાપ્ત થાય છે.',
    vartaContent:
        '''શ્રી રામદાસજી રાજસ્થાનના મેડતા (મેડતા રોડ/નાગોર) નગરના ક્ષત્રિય હતા. તેઓ પ્રારંભિક જીવનમાં વીરતા, રાજકીય બાબતો અને લૌકિક વૈભવ વચ્ચે વિતાવતા હતા. પરંતુ પૂર્વજન્મના સત્સંસ્કારોને કારણે તેમના અંતરમાં સદા ભગવદ્-વિપ્રયોગ અને આંતરિક વિરક્તિનો દિવ્ય ભાવ રહેતો હતો.

જ્યારે શ્રીઆચાર્યજી મહાપ્રભુજી પોતાની પૃથ્વી પરિક્રમા દરમિયાન ત્યાંથી પસાર થઈ રહ્યા હતા, ત્યારે રામદાસજી તેમના અલૌકિક દર્શન માટે આવ્યા. શ્રીમહાપ્રભુજીના દિવ્ય મુખારવિંદમાંથી નીકળતા સુબોધિનીજીના અમૃતવચનો અને કૃષ્ણકથા સાંભળીને રામદાસજીનું હૃદય દ્રવી ઉઠ્યું. તેમણે તુરંત શ્રીઆચાર્યજીના ચરણોમાં સાષ્ટાંગ પ્રણામ કર્યા અને શરણાગતિ સ્વીકારીને બ્રહ્મસંબંધ પ્રાપ્ત કર્યો.

દીક્ષા લીધા બાદ રામદાસજીએ પોતાના રાજકીય વૈભવ, પદ અને અહંકારનો સંપૂર્ણ ત્યાગ કર્યો. તેમણે પોતાનું ઘર અને લૌકિક સગાસંબંધીઓ છોડીને ગોકુલ તથા વ્રજભૂમિમાં આવીને નિવાસ કર્યો. તેઓ શ્રીઆચાર્યજીની આજ્ઞાનુસાર શ્રીજીની નિત્ય સેવા અને કીર્તનમાં લીન થઈ ગયા.

રામદાસજીનો ભગવદ્-આશ્રય એવો અનન્ય હતો કે સંસારનું કોઈ પણ સુખ કે દુઃખ તેમને વિચલિત કરી શકતું નહોતું. તેઓ રોજ શ્રીજીના દર્શન કરતા અને સાધુ-વૈષ્ણવોની નિષ્કામ સેવા કરતા. તેમની આવી વિરક્ત અને સમર્પિત ભક્તિ જોઈને શ્રીમહાપ્રભુજી તેમના પર અત્યંત પ્રસન્ન રહ્યા. રામદાસજીએ પોતાનું આખું જીવન વ્રજધામમાં રહીને ભગવદ્-સ્મરણ અને શરણાગતિમાં જ વિતાવ્યું.''',
    saar:
        'લૌકિક આસક્તિ, પદ કે વૈભવનો ત્યાગ કર્યા વિના ભગવાનના ચરણોમાં સાચો પ્રેમ પ્રગટ થતો નથી. જ્યારે જીવ સર્વસ્વ પ્રભુને અર્પણ કરે છે, ત્યારે તેને સાચો ભક્તિરસ પ્રાપ્ત થાય છે.',
  ),

  VartaModel(
