    vartaContent:
        '''શ્રી ભગવાનદાસજી ચૌહાણ વંશના એક પરાક્રમી ક્ષત્રિય હતા. તેઓ શાસ્ત્ર અને શસ્ત્ર બંને વિદ્યામાં અત્યંત પ્રવીણ હતા. પોતાના વંશગત સ્વભાવ અને વીરતાના કારણે તેમનામાં રાજકીય તેજ હતો, પરંતુ પૂર્વજન્મના કોઈ પુણ્ય પ્રભાવથી તેમના અંતરમાં વિરક્તિ અને ભગવદ્-પ્રાપ્તિની અદમ્ય તીવ્ર ઈચ્છા પણ રહેતી હતી.

જ્યારે શ્રીઆચાર્યજી મહાપ્રભુજી પોતાની પૃથ્વી પરિક્રમા દરમિયાન ત્યાં પધાર્યા, ત્યારે ભગવાનદાસજી તેમના દિવ્ય દર્શને આવ્યા. શ્રીમહાપ્રભુજીના મુખારવિંદમાંથી ઝરતી ભાગવત કથા અને સુબોધિનીજીનો અમૃત ઉપદેશ સાંભળતા જ તેમનું હૃદય દ્રવી ઉઠ્યું. તેમને ભાન થયું કે આ સંસારની ક્ષણભંગુર શૂરવીરતા કરતાં ભગવાનના ચરણોની દાસતા જ પરમ સત્ય છે.

તેમણે તુરંત જ શ્રીઆચાર્યજીના ચરણોમાં સાષ્ટાંગ પ્રણામ કરી શરણાગતિ સ્વીકારી અને બ્રહ્મસંબંધ પ્રાપ્ત કર્યો. દીક્ષા લીધા પછી તેમણે ક્ષત્રિય અહંકારનો ત્યાગ કર્યો અને પોતાના ઘરમાં શ્રીજીનું દિવ્ય સ્વરૂપ પધરાવી સેવા-અર્ચનામાં તલ્લીન થઈ ગયા.

એકવાર માર્ગમાં તેમના પર કેટલાક વિરોધીઓ અને અસામાજિક તત્વો દ્વારા આક્રમણ કરવાનો પ્રયાસ થયો, પરંતુ ભગવાનદાસજીએ પોતાના શસ્ત્રોથી લડવાને બદલે માત્ર શ્રીજીના અભય આશ્રયનો સહારો લીધો. શ્રીજીએ સાક્ષાત તેમની રક્ષા કરી અને વિરોધીઓનું મન પરિવર્તિત કરી દીધું. ભગવાનદાસજીએ પોતાનું શેષ સંપૂર્ણ જીવન નિત્ય પ્રભુસેવા અને સત્સંગમાં જ વિતાવ્યું.''',
    saar:
        'માનવ ગમે તેટલો બળવાન કે પ્રભાવશાળી હોય, પણ સાચું બળ અને અભય પદ માત્ર ભગવાનના ચરણોમાં સર્વસ્વ સમર્પણ કરવાથી જ મળે છે.',
  ),

  VartaModel(
