    vartaContent:
        '''શ્રી પદમનાભદાસજી કનૌજ ક્ષેત્રના બાંદોરા ગામના નિવાસી ઉત્તમોત્તમ બ્રાહ્મણ હતા. તેઓ પૂર્વજન્મના મહાન સંસ્કારી અને બાલ્યાવસ્થાથી જ અનન્ય ભક્તિભાવ ધરાવનારા જીવ હતા. તેમના અંતરમાં શ્રીકૃષ્ણની ચરણસેવા અને લીલાસ્મરણ પ્રત્યે અપાર પ્રીતિ હતી.

જ્યારે શ્રીઆચાર્યજી મહાપ્રભુજી પોતાની પૃથ્વી પરિક્રમા દરમિયાન બાંદોરા ગામમાં પધાર્યા, ત્યારે પદમનાભદાસજી સાક્ષાત પરબ્રહ્મ સમાન શ્રીમહાપ્રભુજીના દિવ્ય દર્શન કરીને અતિશય ભાવવિભોર થઈ ગયા. તેમણે શ્રીઆચાર્યજીના ચરણોમાં સાષ્ટાંગ પ્રણામ કરી દીનતાપૂર્વક પ્રાર્થના કરી. શ્રીમહાપ્રભુજીએ તેમના પર અત્યંત કૃપા કરીને તેમને બ્રહ્મસંબંધ આપ્યો અને ભગવદ્-સેવા પ્રદાન કરી.

દીક્ષા લીધા બાદ પદમનાભદાસજીએ પોતાના ઘરમાં શ્રીઆચાર્યજીની આજ્ઞા અનુસાર શ્રીજીનું સ્વરૂપ પધરાવ્યું. તેઓ રોજ અત્યંત પવિત્રતા, સાવધાની અને પ્રેમપૂર્વક શ્રીજીની સેવા અર્પિત કરતા. તેમની ભક્તિ અને કીર્તનસેવાથી સાક્ષાત શ્રીજી અતિશય પ્રસન્ન રહેતા હતા. પદમનાભદાસજી ક્યારેય શ્રીઆચાર્યજીની આજ્ઞા બહાર એક ક્ષણ પણ વર્તતા નહોતા.

એકવાર માર્ગમાં કેટલાંક શાસ્ત્રાર્થી વિદ્વજનોએ પદમનાભદાસજી સાથે માર્ગ અને સિદ્ધાંત વિશે ચર્ચા કરવાનો પ્રયાસ કર્યો. પરંતુ પદમનાભદાસજીએ કહ્યું કે, "શ્રીમહાપ્રભુજીએ જે માર્ગ દર્શાવ્યો છે તે જ સર્વશાસ્ત્રોનું નિષ્કર્ષ છે. ગુરુઆજ્ઞા સિવાય અમારે મન અન્ય કોઈ તર્ક કે વિચાર આશ્રયણીય નથી." તેમની આ અવિચળ અને દ્રઢ ગુરુનિષ્ઠા જોઈને સર્વજનો આશ્ચર્યચકિત થઈ ગયા. પદમનાભદાસજીએ આખું જીવન અનન્ય આશ્રય અને શ્રીજીની નિત્ય સેવામાં જ વિતાવ્યું.''',
    saar:
        'શ્રીગુરુદેવના વચનોમાં અનન્ય અને નિષ્કપટ વિશ્વાસ જ સાચી ભક્તિનું લક્ષણ છે. ગુરુઆજ્ઞાનું અક્ષરશઃ પાલન કરવાથી ભગવાન સહજ રીતે સુલભ બને છે.',
  ),

