    vartaContent:
        '''શ્રી નારાયણદાસજી ભાટ જ્ઞાતિના હતા. તેઓ ઉત્તમ વંશાવલીનું વર્ણન કરનારા અને કાવ્ય-સંગીતમાં નિપુણ હતા. ભાટ સમાજના હોવાના કારણે તેમને રાજાઓ અને ધનિકોના દરબારમાં જઈને તેમની પ્રશંસા ગાઈને લૌકિક ધન કમાવવાની ટેવ હતી. પરંતુ તેમના અંતરમાં ભગવદ્-ભાવના સંસ્કારો પણ રહેલા હતા.

જ્યારે શ્રીઆચાર્યજી મહાપ્રભુજી પોતાની ભારત પરિક્રમા દરમિયાન ત્યાં પધાર્યા, ત્યારે નારાયણદાસજી તેમના દર્શને આવ્યા. શ્રીમહાપ્રભુજીના દિવ્ય મુખારવિંદના દર્શન થતાં જ તેમના હૃદયમાં જ્ઞાનનો દિવ્ય પ્રકાશ થયો. તેમણે વિચાર્યું કે "માનવની પ્રશંસા ગાવા કરતાં જે સકળ જગતના નાથ છે તે શ્રીકૃષ્ણની લીલા ગાવી એ જ જીવનની સાચી સાર્થકતા છે."

તેમણે તુરંત શ્રીઆચાર્યજી મહાપ્રભુજીના ચરણોમાં સાષ્ટાંગ પ્રણામ કર્યા અને શરણાગતિ સ્વીકારીને બ્રહ્મસંબંધ પ્રાપ્ત કર્યો. દીક્ષા લીધા બાદ તેમણે લૌકિક રાજાઓ કે ધનિકોની પ્રશંસા કરવાનું સંપૂર્ણપણે બંધ કરી દીધું અને પોતાનું કાવ્ય તથા સંગીત માત્ર શ્રીજીના ચરણોમાં સમર્પિત કરી દીધું.

તેઓ શ્રીનાથજીના દિવ્ય સ્વરૂપ અને બાલલીલાના અલૌકિક પદો બનાવીને ગાવા લાગ્યા. એકવાર કોઈ ધનિક રાજાએ તેમને મોટી ધનરાશિ આપવાની લાલચ આપીને પોતાના વખાણ ગાવડાવવાનો પ્રયત્ન કર્યો, પરંતુ નારાયણદાસજીએ તે ધનનો તિરસ્કાર કરીને કહ્યું કે "મારું મુખ હવે માત્ર શ્રીવલ્લભ અને શ્રીજીના ગુણગાન ગાવા માટે જ છે, લૌકિક જીવોના વખાણ માટે નહીં." તેમની આ અવિચળ ભક્તિ જોઈને શ્રીજી અતિશય પ્રસન્ન થયા. નારાયણદાસજીએ આખું જીવન ભગવદ્-સંકીર્તનમાં જ સમર્પિત કર્યું.''',
    saar:
        'માનવ જીભ અને કળાની વાસ્તવિક સાર્થકતા લૌકિક પ્રશંસામાં નહીં, પરંતુ પ્રભુ અને ગુરુના ગુણગાન ગાવામાં જ રહેલી છે.',
  ),

  VartaModel(
