    shloka: 'सर्वस्वं गुरुवे दद्यात् मनसा कर्मणा गिरा ॥ २८ ॥',
    arth:
        'મન, વચન અને કર્મથી પોતાનું સર્વસ્વ શ્રીગુરુદેવના ચરણોમાં અર્પિત કરીને સેવા કરવી.',
    vartaContent:
        '''શ્રી ગડા જેઠાજી ગુજરાતના વડનગર (અથવા કડી/પાટણ ક્ષેત્ર) ના નિવાસી અતિ ઉત્તમ બ્રાહ્મણ હતા. તેઓ સ્વભાવે અત્યંત સરસ, નમ્ર, વિવેકી અને ભગવદ્-રસના તીવ્ર અંકુર ધરાવનારા આત્મા હતા. નાનપણથી જ તેમનામાં સંસાર પ્રત્યે અનાસક્તિ અને પ્રભુભક્તિના સંસ્કારો દ્રઢ હતા.

જ્યારે શ્રીઆચાર્યજી મહાપ્રભુજી પોતાની પૃથ્વી પરિક્રમા દરમિયાન ગુજરાત પધાર્યા, ત્યારે ગડા જેઠાજી તેમના અલૌકિક સ્વરૂપના દર્શન માટે આવ્યા. શ્રીમહાપ્રભુજીના દિવ્ય મુખારવિંદમાંથી ઝરતી ભાગવત કથા અને પુષ્ટિમાર્ગીય આશ્રયનો સિદ્ધાંત સાંભળીને ગડા જેઠાજીનું હૃદય સંપૂર્ણપણે કૃષ્ણમય બની ગયું. તેમણે તુરંત શ્રીઆચાર્યજીના ચરણોમાં સાષ્ટાંગ પ્રણામ કર્યા અને શરણાગતિ સ્વીકારી બ્રહ્મસંબંધ પ્રાપ્ત કર્યો.

બ્રહ્મસંબંધ લીધા બાદ ગડા જેઠાજીએ પોતાના ઘરમાં શ્રીઆચાર્યજીની આજ્ઞાનુસાર શ્રીજીનું દિવ્ય સ્વરૂપ પધરાવ્યું. તેઓ સદા મન, વચન અને કર્મથી શ્રીજીની સેવા અને સત્સંગમાં તલ્લીન રહેતા. તેમણે પોતાની લૌકિક સંપત્તિ કે સગાસંબંધીઓનો કોઈ મોહ ન રાખ્યો અને જે કંઈ હતું તે સર્વસ્વ શ્રીજી અને ગુરુસેવામાં સમર્પિત કરી દીધું.

એકવાર માર્ગમાં કેટલાક લૌકિક લોકોએ તેમની ભક્તિ અને સરળતાની મજાક ઉડાવવાનો પ્રયાસ કર્યો. પરંતુ ગડા જેઠાજીએ સહેજ પણ ક્રોધ કે તર્ક કર્યા વિના માત્ર શ્રીજીના ચરણારવિંદનો જ આશ્રય લીધો. તેમની આ દ્રઢ ગુરુનિષ્ઠા જોઈને સાક્ષાત શ્રીજીએ તેમની રક્ષા કરી અને વિરોધીઓનું મન પરિવર્તિત કરી દીધું. ગડા જેઠાજીએ પોતાનું શેષ આયુષ્ય નિષ્કામ ભગવદ્-સેવા અને ગુરુભક્તિમાં જ વિતાવ્યું.''',
    saar:
        'માનવ જ્યારે પોતાના મન, વાણી અને કર્મને સંપૂર્ણપણે ગુરુ અને ભગવાનના ચરણોમાં સોંપી દે છે, ત્યારે તેના સર્વ લૌકિક ભય અને અજ્ઞાન આપોઆપ નષ્ટ થઈ જાય છે.',
