    vartaContent:
        '''શ્રી ગંગાબાઈ ક્ષત્રિયાણી જ્ઞાતિએ ક્ષત્રિય હતાં. તેઓ સ્વભાવે અતિશય વિવેકી, પવિત્ર, સેવાભાવી અને પરમ ભગવદ્-ભક્ત હતાં. તેમના અંતરમાં સંસારના લૌકિક સુખો પ્રત્યે સંપૂર્ણ વૈરાગ્ય હતો અને નિત્ય પ્રભુચરણમાં ભક્તિભાવ રહેતો હતો.

જ્યારે શ્રીઆચાર્યજી મહાપ્રભુજી પોતાની પૃથ્વી પરિક્રમા દરમિયાન ત્યાં પધાર્યા, ત્યારે ગંગાબાઈ તેમના અલૌકિક સ્વરૂપના દર્શન માટે આવ્યા. શ્રીમહાપ્રભુજીના દિવ્ય મુખારવિંદમાંથી ઝરતાં વચનો સાંભળીને તેમનું હૃદય સંપૂર્ણપણે ભક્તિરસમાં ડૂબી ગયું. તેમણે શ્રીઆચાર્યજીના ચરણોમાં શરણાગતિ સ્વીકારી અને બ્રહ્મસંબંધ પ્રાપ્ત કર્યો.

દીક્ષા લીધા બાદ ગંગાબાઈએ પોતાના ઘરમાં શ્રીઆચાર્યજીની આજ્ઞાનુસાર શ્રીજીનું દિવ્ય સ્વરૂપ પધરાવ્યું. તેઓ નિત્ય વહેલા જાગીને અત્યંત પવિત્રતા, સાવધાની અને વાત્સલ્ય ભાવથી શ્રીજીની સેવા-અર્ચના અર્પિત કરતાં. ઘરમાં સ્ત્રી તરીકેના તમામ ગૃહસ્થાશ્રમના કાર્યો કરતી વખતે પણ તેમનું ચિત્ત સદા પોતાના શ્રીજીના મુખારવિંદમાં પરોવાયેલું રહેતું.

એકવાર માર્ગમાં અથવા લૌકિક સગાસંબંધીઓ દ્વારા તેમની સેવા અને આશ્રયમાં વિઘ્ન નાખવાનો પ્રયાસ થયો, પરંતુ ગંગાબાઈએ સહેજ પણ ડર્યા વગર માત્ર શ્રીજીના અવિચળ આશ્રયનો ભરોસો રાખ્યો. તેમની અનન્ય નિષ્ઠા જોઈને શ્રીજીએ પોતે તેમની સર્વ અડચણો દૂર કરી. ગંગાબાઈએ પોતાનું સમગ્ર આયુષ્ય શ્રીજીની નિષ્કામ સેવા અને પ્રભુસ્મરણમાં જ વિતાવ્યું.''',
    saar:
