    vartaContent:
        '''શ્રી રુક્મિણીજી ઉત્તમ ક્ષત્રિય કુળના સ્ત્રી હતાં. તેઓ સ્વભાવે અત્યંત સુશીલ, પતિવ્રતા, ગંભીર અને બાલ્યાવસ્થાથી જ ભગવદ્-ભક્તિ પ્રત્યે અદમ્ય પ્રીતિ ધરાવનારાં હતાં. તેમના અંતરમાં સંસારના લૌકિક ભોગ-વિલાસ પ્રત્યે ઉદાસીનતા હતી અને નિત્ય પ્રભુના ચરણોમાં લીન રહેવાનો ભાવ હતો.

જ્યારે શ્રીઆચાર્યજી મહાપ્રભુજી પોતાની ભારત પરિક્રમા દરમિયાન ત્યાં પધાર્યા, ત્યારે રુક્મિણીજી પોતાના પરિવાર સાથે તેમના અલૌકિક દર્શન માટે આવ્યા. શ્રીમહાપ્રભુજીના તેજોમય સ્વરૂપ અને મુખારવિંદમાંથી ઝરતી ભાગવત કથા સાંભળીને તેમનું હૃદય સંપૂર્ણપણે કૃષ્ણમય બની ગયું. તેમણે શ્રીઆચાર્યજીના ચરણોમાં સાષ્ટાંગ પ્રણામ કર્યા અને બ્રહ્મસંબંધ પ્રાપ્ત કર્યો.

દીક્ષા લીધા બાદ રુક્મિણીજીએ પોતાના ઘરમાં શ્રીઆચાર્યજીની આજ્ઞાનુસાર શ્રીજીનું દિવ્ય સ્વરૂપ પધરાવ્યું. તેઓ નિત્ય સવારે વહેલા જાગીને અત્યંત પવિત્રતા, સાવધાની અને વાત્સલ્ય ભાવથી શ્રીજીની સેવા અર્પિત કરતાં. પોતાના પરિવાર અને ગૃહસ્થાશ્રમના તમામ લૌકિક કાર્યો કરતી વખતે પણ તેમનું ચિત્ત સદા પોતાના શ્રીજીના મુખારવિંદના ધ્યાનમાં જ લીન રહેતું.

એકવાર તેમના પરિવારમાં કેટલીક લૌકિક વિષમતાઓ અને અડચણો આવી, પરંતુ રુક્મિણીજીએ સહેજ પણ ગભરાયા વિના પોતાના ઈષ્ટદેવ શ્રીજી અને ગુરુશ્રીમહાપ્રભુજીના અવિચળ આશ્રયનો ભરોસો રાખ્યો. તેમની અનન્ય ભક્તિ જોઈને શ્રીજીએ પોતે સાક્ષાત તેમના સર્વ સંકટો દૂર કર્યા. રુક્મિણીજીએ પોતાનું સમગ્ર આયુષ્ય નિષ્કામ ભગવદ્-સેવા અને પ્રભુચરણના આશ્રયમાં જ વિતાવ્યું.''',
    saar:
        'ગૃહસ્થાશ્રમના કર્તવ્યોનું પાલન કરવાની સાથે સાથે જો જીવનું મન સંપૂર્ણપણે ભગવાન અને ગુરુચરણોમાં સમર્પિત રહે, તો ભગવાન સાક્ષાત તેની સર્વ વિપત્તિઓમાં રક્ષા કરે છે.',
  ),

  VartaModel(
    id: '31',
    number: '૩૧',
    titleGujarati: 'શ્રી વ્યાસદાસજીની વાર્તા',
    titleBraj: 'વ્યાસદાસજી કી વાર્તા',
    shloka: 'शास्त्रज्ञानं तु सफला भवेत् भक्तिसमन्विता ॥ ३१ ॥',
    arth:
        'શાસ્ત્રો અને વેદોનું જ્ઞાન ત્યારે જ અર્થપૂર્ણ અને સાર્થક બને છે જ્યારે તે અનન્ય ભગવદ્-ભક્તિ સાથે જોડાયેલું હોય.',
    vartaContent:
        '''શ્રી વ્યાસદાસજી કનૌજ (ઉત્તર પ્રદેશ) ના ઉત્તમોત્તમ વિદ્વાન બ્રાહ્મણ હતા. તેઓ શાસ્ત્રો, વેદ-વેદાંત અને પુરાણોના પરમ જ્ઞાની હતા. તેઓ પંડિત હોવાના કારણે પ્રારંભિક જીવનમાં માત્ર શાસ્ત્રચર્ચા, તર્ક અને જ્ઞાનમાર્ગમાં જ લીન રહેતા હતા. પરંતુ જ્ઞાન હોવા છતાં તેમના અંતરમાં સાચો ભક્તિરસ અને આંતરિક શાંતિનો અભાવ હતો.

જ્યારે શ્રીઆચાર્યજી મહાપ્રભુજી પોતાની ભારત પરિક્રમા દરમિયાન કનૌજ પધાર્યા, ત્યારે વ્યાસદાસજી શાસ્ત્રાર્થ અને ચર્ચા કરવાના હેતુથી શ્રીમહાપ્રભુજીના દરબારમાં આવ્યા. શ્રીમહાપ્રભુજીના તેજોમય સ્વરૂપ દર્શન અને સુબોધિનીજીની સરળ પણ અત્યંત ગંભીર કથા સાંભળીને વ્યાસદાસજીનો તમામ વિદ્વાન અહંકાર ક્ષણવારમાં ગળી ગયો. તેમને સમજાયું કે શુષ્ક જ્ઞાન કરતાં શ્રીકૃષ્ણની ચરણસેવા અને ભક્તિ જ જીવનનો સાચો સાર છે.

વ્યાસદાસજીએ તુરંત જ શ્રીઆચાર્યજી મહાપ્રભુજીના ચરણોમાં સાષ્ટાંગ પ્રણામ કર્યા, પોતાની અજ્ઞાનતાની ક્ષમા માંગી અને શરણાગતિ સ્વીકારીને બ્રહ્મસંબંધ પ્રાપ્ત કર્યો.

દીક્ષા લીધા બાદ વ્યાસદાસજીએ પોતાના શાસ્ત્રીય પાંડિત્યના અહંકારનો સંપૂર્ણ ત્યાગ કર્યો. તેમણે પોતાની વિદ્યાનો ઉપયોગ માત્ર શ્રીજીની લીલાઓ અને વલ્લભ સંપ્રદાયના સિદ્ધાંતોના ગૂઢ મહિમાને સમજવામાં અને કીર્તનો રચવામાં કર્યો. તેઓ નિત્ય શ્રીજીની સેવામાં પરોવાયેલા રહ્યા અને સાધુ-વૈષ્ણવોની નિષ્કામ ભાવે સેવા કરવા લાગ્યા. વ્યાસદાસજીએ પોતાનું આખું જીવન અનન્ય આશ્રય અને પ્રભુચરણમાં જ વ્યતીત કર્યું.''',
    saar:
        'માત્ર પુસ્તકીય કે શાસ્ત્રીય જ્ઞાનથી ઈશ્વરની પ્રાપ્તિ થતી નથી. જ્ઞાન જ્યારે ગુરુકૃપાથી નમ્રતા અને નિષ્કામ ભક્તિમાં પરિણમે છે, ત્યારે જ જીવને પરમાનંદ પ્રાપ્ત થાય છે.',
  ),

  VartaModel(
    id: '32',
    number: '૩૨',
    titleGujarati: 'શ્રી રામદાસ કાયસ્થની વાર્તા',
    titleBraj: 'રામદાસ કાયસ્થ કી વાર્તા',
    shloka: 'कपटं च परित्यज्य भजेत् श्रीवल्लभं प्रभुम् ॥ ३२ ॥',
    arth:
        'મનની ચાતુરી, લૌકિક અહંકાર અને કપટનો સંપૂર્ણ ત્યાગ કરીને શ્રીવલ્લભ પ્રભુના ચરણારવિંદનો અનન્ય આશ્રય સ્વીકારવો.',
    vartaContent:
        '''શ્રી રામદાસજી કાયસ્થ જ્ઞાતિના હતા. તેઓ ઉત્તમોત્તમ લૌકિક કારકુની અને વહિવટી કાર્યોમાં નિપુણ હતા. વ્યાવહારિક દફતર સંભાળવાના કારણે તેઓ અત્યંત ચતુર, બુદ્ધિમાનો અને વહિવટી બાબતોમાં પ્રવીણ હતા. પરંતુ સંસારના તમામ કાવતરાંઓ વચ્ચે રહેવા છતાં તેમના અંતરમાં દિવ્ય ભગવદ્-ભાવના અંકુર રહેલા હતા.

જ્યારે શ્રીઆચાર્યજી મહાપ્રભુજી પોતાની પૃથ્વી પરિક્રમા દરમિયાન તે ક્ષેત્રમાં પધાર્યા, ત્યારે રામદાસજી તેમના દિવ્ય દર્શને આવ્યા. શ્રીમહાપ્રભુજીના દિવ્ય મુખારવિંદમાંથી ઝરતી કથા અને સુબોધિનીજીનો ઉપદેશ સાંભળીને રામદાસજીનું મન સંપૂર્ણપણે ભક્તિરસમાં ડૂબી ગયું. તેમણે તુરંત શ્રીઆચાર્યજીના ચરણોમાં સાષ્ટાંગ પ્રણામ કર્યા અને શરણાગતિ સ્વીકારીને બ્રહ્મસંબંધ પ્રાપ્ત કર્યો.

બ્રહ્મસંબંધ લીધા બાદ રામદાસજીએ પોતાના પદ અને બુદ્ધિનો કોઈ અહંકાર ન રાખ્યો. તેમણે પોતાના ઘરમાં શ્રીઆચાર્યજીની આજ્ઞાનુસાર શ્રીજીનું સ્વરૂપ પધરાવ્યું. તેઓ નોકરી-ધંધો માત્ર લૌકિક મર્યાદા ખાતર કરતા, પરંતુ તેમનું ચિત્ત સદા ઘરમાં વિરાજતા પોતાના ઈષ્ટદેવ શ્રીજીના ચરણારવિંદમાં જ લીન રહેતું.

એકવાર તેમના વ્યાવહારિક કામકાજમાં કેટલાક વિરોધીઓએ અન્યાય કરીને તેમને મુશ્કેલીમાં મૂકવાનો પ્રયત્ન કર્યો. પરંતુ રામદાસજીએ સહેજ પણ ચિંતા કર્યા વિના માત્ર પોતાના શ્રીજી અને શ્રીઆચાર્યજીના ચરણોનો આશ્રય લીધો. તેમની નિષ્કપટ ગુરુભક્તિ જોઈને શ્રીજીએ સાક્ષાત તેમની રક્ષા કરી અને સર્વ સંકટો ઉકેલી દીધા. રામદાસજીએ આખું જીવન અનન્ય આશ્રય અને પ્રભુસેવામાં જ વિતાવ્યું.''',
    saar:
        'સંસારના વ્યાવહારિક કામકાજ કરતી વખતે પણ જો જીવનું હૃદય નિષ્કપટ હોય અને ગુરુ તથા ભગવાન પર અવિચળ ભરોસો હોય, તો સાક્ષાત પ્રભુ તેના સર્વ સંકટોનું નિવારણ કરે છે.',
  ),

  VartaModel(
    id: '33',
    number: '૩૩',
    titleGujarati: 'શ્રી ભગવંતદાસ કાયસ્થની વાર્તા',
    titleBraj: 'ભગવંતદાસ કાયસ્થ કી વાર્તા',
    shloka: 'निष्कपट भावयुक्तस्य श्रीकृष्णे विमला मतिः ॥ ३३ ॥',
    arth:
        'જે જીવનું હૃદય સંપૂર્ણપણે નિષ્કપટ અને નમ્ર હોય છે, તેની બુદ્ધિ સાક્ષાત શ્રીકૃષ્ણના ચરણોમાં નિર્મળ થઈને સ્થિર થાય છે.',
    vartaContent:
        '''શ્રી ભગવંતદાસજી કાયસ્થ જ્ઞાતિના હતા. તેઓ પણ સરકારી અને વ્યાવહારિક દફતર સંભાળવાના હિસાબી તથા વહિવટી કાર્યોમાં સંકળાયેલા હતા. સંસારના વ્યાવહારિક દાવપેચ વચ્ચે રહેવા છતાં તેમના અંતરમાં સહજ નમ્રતા, દયા અને ભગવદ્-સ્મરણની ગંભીર ભાવના રહેતી હતી.

જ્યારે શ્રીઆચાર્યજી મહાપ્રભુજી પોતાની ભારત પરિક્રમા દરમિયાન ત્યાં પધાર્યા, ત્યારે ભગવંતદાસજી તેમના દિવ્ય દર્શને આવ્યા. શ્રીમહાપ્રભુજીના મુખારવિંદમાંથી ઝરતી કથા અને સુબોધિનીજીનો અમૃત ઉપદેશ સાંભળીને તેમનું મન ભક્તિભાવમાં ડૂબી ગયું. તેમણે તુરંત શ્રીઆચાર્યજીના ચરણોમાં સાષ્ટાંગ પ્રણામ કર્યા અને શરણાગતિ સ્વીકારીને બ્રહ્મસંબંધ પ્રાપ્ત કર્યો.

બ્રહ્મસંબંધ લીધા બાદ ભગવંતદાસજીએ પોતાના ઘરમાં શ્રીઆચાર્યજીની આજ્ઞાનુસાર શ્રીજીનું દિવ્ય સ્વરૂપ પધરાવ્યું. તેઓ સવારે વહેલા જાગીને અત્યંત પવિત્રતા અને સાવધાનીપૂર્વક શ્રીજીની સેવા અર્પિત કરતા. નોકરી અને લૌકિક કામકાજ કરતી વખતે પણ તેમનું ચિત્ત સદા ઘરમાં વિરાજતા પોતાના ઈષ્ટદેવ શ્રીજીના ચરણારવિંદના ધ્યાનમાં જ પરોવાયેલું રહેતું.

એકવાર તેમના વ્યાવહારિક કાર્યોમાં કેટલીક જટિલ મુશ્કેલીઓ ઊભી થઈ, પરંતુ ભગવંતદાસજીએ સહેજ પણ ચિંતા કર્યા વિના તમામ ભાર પોતાના શ્રીજી અને શ્રીઆચાર્યજીના ચરણો પર છોડી દીધો. તેમની અચળ ભક્તિ અને નિષ્કપટ ભાવ જોઈને શ્રીજીએ પોતે સાક્ષાત તેમની સર્વ મુશ્કેલીઓ દૂર કરી. ભગવંતદાસજીએ પોતાનું શેષ આયુષ્ય અનન્ય આશ્રય અને શ્રીજીની નિત્ય સેવામાં જ વિતાવ્યું.''',
    saar:
        'સંસારના કોઈ પણ વ્યાવહારિક કામકાજ કે સંકટો વચ્ચે પણ જો જીવનો ભગવાન અને ગુરુ પરનો વિશ્વાસ દ્રઢ રહે, તો પ્રભુ સાક્ષાત તેનું રક્ષણ કરે છે.',
  ),

  VartaModel(
    id: '34',
