    titleGujarati: 'શ્રી નારાયણદાસ ભાટિયાની વાર્તા',
    titleBraj: 'નારાયણદાસ ભાટિયા કી વાર્તા',
    shloka: 'सर्वस्वं भगवत्पादे समर्पितं मया सदा ॥ ३४ ॥',
    arth:
        'અહંકાર, મમતા અને લૌકિક પદ-પ્રતિષ્ઠાનો ત્યાગ કરીને પોતાનું સર્વસ્વ ભગવાન અને ગુરુદેવના ચરણોમાં સમર્પિત કરવું.',
    vartaContent:
        '''શ્રી નારાયણદાસજી ભાટિયા જ્ઞાતિના એક અત્યંત પ્રતિષ્ઠિત અને ધનવાન વેપારી હતા. તેઓ સ્વભાવે અત્યંત સરસ, નમ્ર, શાંત અને દાનવીર હતા. લૌકિક રીતે તેમની પાસે વૈભવ અને સમૃદ્ધિની કોઈ કમી નહોતી, પરંતુ પૂર્વજન્મના સત્સંસ્કારોને કારણે તેમના અંતરમાં સદા ભગવદ્-પ્રાપ્તિની અદમ્ય તીવ્રતા રહેતી હતી.

જ્યારે શ્રીઆચાર્યજી મહાપ્રભુજી પોતાની ભારત પરિક્રમા દરમિયાન તે ક્ષેત્રમાં પધાર્યા, ત્યારે નારાયણદાસજી તેમના અલૌકિક સ્વરૂપ દર્શન માટે આવ્યા. શ્રીમહાપ્રભુજીના મુખારવિંદમાંથી ઝરતી કથા અને સુબોધિનીજીનો દિવ્ય ઉપદેશ સાંભળીને નારાયણદાસજીનું મન ભક્તિભાવમાં ભીંજાઈ ગયું. તેમણે તુરંત શ્રીઆચાર્યજીના ચરણોમાં સાષ્ટાંગ પ્રણામ કર્યા અને શરણાગતિ સ્વીકારીને બ્રહ્મસંબંધ પ્રાપ્ત કર્યો.

દીક્ષા લીધા બાદ નારાયણદાસજીએ પોતાના ધન કે વૈભવનો સહેજ પણ અહંકાર ન રાખ્યો. તેમણે પોતાના ઘરમાં શ્રીઆચાર્યજીની આજ્ઞાનુસાર શ્રીજીનું દિવ્ય સ્વરૂપ પધરાવ્યું. તેઓ નિત્ય સવારે વહેલા જાગીને અત્યંત સાવધાની, પવિત્રતા અને સ્નેહપૂર્વક શ્રીજીની સેવા અર્પિત કરતા. પોતાની મોટી વ્યાપારિક પ્રવૃત્તિઓ સંભાળતી વખતે પણ તેમનું મન સદા પોતાના શ્રીજીના ચરણારવિંદમાં જ લીન રહેતું.

એકવાર તેમના વેપારમાં મોટું લૌકિક સંકટ ઊભું થયું અને આર્થિક નુકસાન થવાની સ્થિતિ આવી, પરંતુ નારાયણદાસજીએ સહેજ પણ અધીરા થયા વિના તમામ ભાર પોતાના શ્રીજી પર છોડી દીધો. તેમની અનન્ય નિષ્ઠા જોઈને શ્રીજીએ પોતે સાક્ષાત તેમનું સંકટ દૂર કર્યું. નારાયણદાસજીએ પોતાનું આખું જીવન અનન્ય આશ્રય, ભગવદ્-સેવા અને સાધુ-વૈષ્ણવોની સેવામાં જ વિતાવ્યું.''',
    saar:
        'લૌકિક વૈભવ કે ધન-સંપત્તિ ભક્તિમાં ક્યારેય બાધક બનતા નથી, જો મનુષ્ય પોતાના અહંકારનો ત્યાગ કરીને મનથી સાચા અર્થમાં ગુરુ અને ભગવાનનો આશ્રય સ્વીકારે.',
  ),

