    shloka: 'कीर्तनेन च कृष्णेन लभ्यते भक्तिरुत्तमा ॥ ३६ ॥',
    arth:
        'શ્રીકૃષ્ણની લીલા અને ગુણગાનનું પ્રેમપૂર્વક કીર્તન કરવાથી અનન્ય અને ઉત્તમોત્તમ ભક્તિભાવ પ્રાપ્ત થાય છે.',
    vartaContent:
        '''શ્રી પરમાનંદદાસજી અષ્ટછાપ કવિઓમાંના એક મહાન રસિક ભક્ત-કવિ હતા. તેઓ ઉત્તર પ્રદેશના કનોજ ક્ષેત્રના કાન્યકુબ્જ બ્રાહ્મણ હતા. બાળપણથી જ તેમનામાં સંગીત અને કાવ્યની અદભુત દિવ્ય શક્તિ હતી. તેઓ વિરક્ત થઈને રેણુકા ક્ષેત્ર (રેણુકા ઘાટ, આગ્રા) ખાતે વિરાજતા હતા અને ભગવદ્-વિપ્રયોગના કરુણ રસથી સભર પદો રચતા તથા ગાતા હતા.

જ્યારે શ્રીઆચાર્યજી મહાપ્રભુજી પોતાની ભારત પરિક્રમા દરમિયાન રેણુકા ક્ષેત્ર પધાર્યા, ત્યારે પરમાનંદદાસજી તેમના દર્શને આવ્યા. તેમણે શ્રીઆચાર્યજી સમક્ષ વિપ્રયોગનું પદ ગાયું. શ્રીમહાપ્રભુજીએ તેમને વિપ્રયોગમાંથી સંયોગરસ (બાલલીલા અને રાસલીલા) તરફ વાળવા માટે સુબોધિનીજી અને શ્રીમદ્ ભાગવતજીના દશમ સ્કંધનું અલૌકિક રહસ્ય સંભળાવ્યું. શ્રીમહાપ્રભુજીના દિવ્ય મુખારવિંદથી કથા સાંભળીને પરમાનંદદાસજીનું હૃદય પૂર્ણાનંદથી ભરાઈ ગયું.

તેમણે તુરંત જ શ્રીઆચાર્યજી મહાપ્રભુજીના ચરણોમાં સાષ્ટાંગ પ્રણામ કર્યા અને શરણાગતિ સ્વીકારીને બ્રહ્મસંબંધ પ્રાપ્ત કર્યો. શ્રીમહાપ્રભુજીની કૃપાથી તેમની કાવ્યધારા વાત્સલ્ય અને માધુર્ય રસમાં પરિણમી. તેમણે શ્રીજીના બાલચરિત્રના હજારો પદોની રચના કરી, જે 'પરમાનંદ સાગર' તરીકે પ્રસિદ્ધ થયા.

શ્રીઆચાર્યજી મહાપ્રભુજીએ તેમને શ્રીનાથજીના મંદિર (ગિરિરાજજી) માં કીર્તન સેવાની જવાબદારી સોંપી. પરમાનંદદાસજીએ આખું જીવન સુરભિ કુંડ પાસે રહીને શ્રીજીના અખંડ દર્શન, સેવા અને કીર્તનમાં જ વિતાવ્યું.''',
    saar:
        'માનવની કળા અને સંગીતની સાચી સાર્થકતા ભગવાનના ચરણોમાં જ સમર્પિત થવામાં છે. ગુરુકૃપાથી જીવનો વિપ્રયોગ અને કરુણા પરમાનંદમાં બદલાઈ જાય છે.',
  ),

