    arth:
        'સંતોષ જ પરમ લાભ છે અને લૌકિક પદ-પ્રતિષ્ઠાના ત્યાગપૂર્વક શ્રીકૃષ્ણના ચરણોમાં અવિચળ ભક્તિ રાખવી એ જ જીવનનું સર્વોચ્ચ લક્ષ્ય છે.',
    vartaContent:
        '''શ્રી કુંભનદાસજી અષ્ટછાપ કવિઓમાંના સૌથી જ્યેષ્ઠ ભક્ત-કવિ હતા. તેઓ જામુનાવતો ગામ (વ્રજભૂમિ) ના નિવાસી હતા અને જ્ઞાતિએ ક્ષત્રિય (રાજપૂત) હતા. તેઓ સ્વભાવે અત્યંત સરળ, પરમ વિરક્ત, નિષ્કામ અને અપરિગ્રહી હતા. લૌકિક ધન-સંપત્તિ કે માન-સન્માન પ્રત્યે તેમને સહેજ પણ મોહ નહોતો.

જ્યારે શ્રીઆચાર્યજી મહાપ્રભુજી પોતાની ભારત પરિક્રમા દરમિયાન વ્રજ પધાર્યા અને ગિરિરાજજી પર શ્રીનાથજીની સેવા પધરાવી, ત્યારે કુંભનદાસજી તેમના અલૌકિક દર્શને આવ્યા. શ્રીમહાપ્રભુજીના તેજોમય સ્વરૂપ અને અમૃતવાણીથી પ્રભાવિત થઈને તેમણે શરણાગતિ સ્વીકારી અને બ્રહ્મસંબંધ પ્રાપ્ત કર્યો. શ્રીઆચાર્યજીએ તેમને શ્રીનાથજીના મુખ્ય કીર્તનકાર તરીકે નિયુક્ત કર્યા.

કુંભનદાસજીની ભક્તિ અને વૈરાગ્ય એટલાં ઉચ્ચ કક્ષાના હતા કે બાદશાહ અકબરે પણ તેમની કીર્તનકળાની પ્રશંસા સાંભળીને તેમને ફતેહપુર સીકરી પોતાના દરબારમાં બોલાવ્યા. જ્યારે બાદશાહે તેમને ગાન સંભળાવવા કહ્યું, ત્યારે કુંભનદાસજીએ ગાયું:

"સંતન કો સીકરી સો કહા કામ? આવત જાત પનહિયાં ટૂટી, બિસરી ગયો હરિ નામ..."

તેમણે બાદશાહની સામે સ્પષ્ટ કહ્યું કે "અમારો સંબંધ તો માત્ર શ્રીગિરિરાજધરણ સાથે છે, રાજા-મહારાજાઓ સાથે અમારે શું કામ?" તેમની આવી અવિચળ અને નિષ્કામ ભગવદ્-નિષ્ઠા જોઈને બાદશાહ અકબર પણ દંગ રહી ગયા અને નતમસ્તક થયા. કુંભનદાસજીએ પોતાનું સમગ્ર જીવન વ્રજમાં રહીને શ્રીનાથજીના નિત્ય કીર્તન અને સેવામાં જ સમર્પિત કર્યું.''',
    saar:
        'સાચો ભક્ત ક્યારેય લૌકિક રાજ-વૈભવ કે સન્માનની કામના કરતો નથી. શ્રીજીના ચરણોમાં જ તેને પરમ વિશ્રામ અને સંતોષ પ્રાપ્ત થાય છે.',
  ),

  VartaModel(
