    titleBraj: 'ચતુર્ભુજદાસજી કી વાર્તા (દૂસરી)',
    shloka: 'पितृपादप्रसादेन लभ्यते भक्तिरुत्तमा ॥ ३८ ॥',
    arth:
        'પિતા અને ગુરુના ચરણોની કૃપા અને આશીર્વાદથી જીવને સાચી ભક્તિ, જ્ઞાન અને ભગવદ્-રસની પ્રાપ્તિ થાય છે.',
    vartaContent:
        '''શ્રી ચતુર્ભુજદાસજી અષ્ટછાપ કવિઓમાંના એક પ્રસિદ્ધ રસિક ભક્ત-કવિ હતા. તેઓ અષ્ટછાપના જ્યેષ્ઠ કવિ શ્રી કુંભનદાસજીના સૌથી નાના પુત્ર હતા. બાળપણથી જ તેમને ઘરમાં પિતાના ભગવદ્-રસ, સત્સંગ અને શ્રીનાથજીની કીર્તનસેવાનું ઉત્તમોત્તમ વાતાવરણ મળ્યું હતું.

જ્યારે શ્રીગુસાઈંજી (શ્રી વિઠ્ઠલનાથજી) એ તેમના પર કૃપા કરી, ત્યારે ચતુર્ભુજદાસજીએ બ્રહ્મસંબંધ પ્રાપ્ત કર્યો. પિતા શ્રી કુંભનદાસજીના ભક્તિસંસ્કારો અને શ્રીગુસાઈંજીની અલૌકિક કૃપાથી તેમનામાં સંગીત અને કાવ્ય રચનાની અદભુત દિવ્ય શક્તિ પ્રગટ થઈ.

ચતુર્ભુજદાસજીએ શ્રીનાથજીના બાલચરિત્ર, શ્રી ગિરિરાજધારણની લીલાઓ અને શ્રીગુસાઈંજીના ગુણગાનના અત્યંત મધુર પદોની રચના કરી. તેમની કાવ્યધારામાં વાત્સલ્ય અને માધુર્ય રસ છલકાતો હતો. તેઓ પોતાના પિતાની જેમ જ અપરિગ્રહી અને સંસારના લૌકિક મોહથી પર વિરક્ત હતા.

શ્રીગુસાઈંજીએ તેમને શ્રીજીના અષ્ટછાપ કીર્તનકારોમાં સ્થાન આપ્યું. ચતુર્ભુજદાસજી નિત્ય શ્રીનાથજી સમક્ષ નવીન પદો રચતા અને સંગીતના દિવ્ય રાગોમાં ગાતા. સાક્ષાત શ્રીજી તેમની કીર્તનસેવાથી અત્યંત પ્રસન્ન રહેતા. તેમણે પોતાનું સમગ્ર આયુષ્ય વ્રજધામમાં રહીને શ્રીનાથજીના નિત્ય કીર્તન, દર્શન અને ગુરુભક્તિમાં જ સમર્પિત કર્યું.''',
    saar:
        'સત્સંગ, પિતૃકૃપા અને શ્રીગુરુચરણનો આશ્રય મળી જાય તો મનુષ્યનું આખું જીવન પ્રભુના દિવ્ય પ્રેમરસમાં રંગાઈ જાય છે.',
  ),

