    vartaContent:
        '''શ્રી ગોવિંદસ્વામી અષ્ટછાપ કવિઓમાંના એક અત્યંત પ્રખ્યાત ભક્ત-કવિ હતા. તેઓ આંત્રી (રાજસ્થાન/મધ્ય પ્રદેશ સરહદ ક્ષેત્ર) ના સનાઢ્ય બ્રાહ્મણ હતા. પ્રારંભિક જીવનમાં તેઓ સંન્યાસી (વૈરાગી) હતા અને મહાવન (ગોકુલ) માં આવીને કદંબ ખંડી પાસે રહેતા હતા. તેઓ કાવ્ય અને સંગીત શાસ્ત્રના અસાધારણ આચાર્ય હતા અને શાસ્ત્રીય રાગ-રાગિણીઓમાં અત્યંત પ્રવીણ હતા.

જ્યારે શ્રીઆચાર્યજી મહાપ્રભુજીના દ્વિતીય પુત્ર ચરણકમળ શ્રીગુસાઈંજી (શ્રી વિઠ્ઠલનાથજી) એ તેમના પર કૃપા કરી, ત્યારે ગોવિંદસ્વામીએ શ્રીગુસાઈંજીના ચરણોમાં શરણાગતિ સ્વીકારીને બ્રહ્મસંબંધ પ્રાપ્ત કર્યો. શ્રીગુસાઈંજીની કૃપાથી તેમના જ્ઞાન અને સંગીતનો શુષ્ક વૈરાગ્ય મટીને સાચા ભગવદ્-રસ અને માધુર્ય ભાવમાં પરિણમ્યો.

શ્રીગુસાઈંજીએ ગોવિંદસ્વામીને શ્રીજીના અષ્ટછાપ કીર્તનિકાઓમાં સ્થાન આપ્યું. ગોવિંદસ્વામીએ ગોકુલના કદંબ ખંડી (જે આજે પણ 'ગોવિંદ કુંડ' અને 'ગોવિંદસ્વામીની કદંબ ખંડી' તરીકે ઓળખાય છે) ખાતે રહીને શ્રીનાથજીની લીલાઓ, બાલચરિત્ર અને રાસલીલાના અદભુત પદોની રચના કરી. તેમની સંગીત સાધના એટલી ઉચ્ચ કક્ષાની હતી કે સંગીત સમ્રાટ તાનસેન પણ ગુપ્ત વેશ ધારણ કરીને ગોવિંદસ્વામી પાસેથી રાગ-રાગિણીઓનો ગૂઢ ભેદ શીખવા માટે તેમના આશ્રમે આવતા હતા.

જ્યારે તાનસેને તેમની કળા જોઈને આશ્ચર્ય વ્યક્ત કર્યું, ત્યારે ગોવિંદસ્વામીએ કહ્યું કે "અમારું ગાન કોઈ લૌકિક રાજા-મહારાજાને રીઝવવા માટે નથી, પરંતુ અખિલ બ્રહ્માંડના નાથ શ્રીગિરિરાજધરણને પ્રસન્ન કરવા માટે છે." ગોવિંદસ્વામીએ પોતાનું સમગ્ર આયુષ્ય વ્રજધામમાં રહીને શ્રીનાથજીના નિત્ય કીર્તન, દર્શન અને ગુરુભક્તિમાં જ સમર્પિત કર્યું.''',
    saar:
