    vartaContent:
        '''શ્રી છીતસ્વામી અષ્ટછાપ કવિઓમાંના એક પ્રખ્યાત અને રસિક ભક્ત-કવિ હતા. તેઓ મથુરાના ચોબે (ચતુર્વેદી બ્રાહ્મણ) હતા. પ્રારંભિક જીવનમાં તેઓ અત્યંત અહંકારી, ટીખળી અને સ્વછંદી સ્વભાવના હતા. તેઓ રાજા-મહારાજાઓ અને સાધુ-સંતોની મજાક ઉડાવવામાં જ પોતાની ચતુરાઈ માનતા હતા.

જ્યારે શ્રીગુસાઈંજી (શ્રી વિઠ્ઠલનાથજી) મથુરા પધાર્યા, ત્યારે છીતસ્વામીએ તેમની મજાક ઉડાવવાના હેતુથી એક ખોટો નાણો (ખૂટો સિક્કો) અને નાળિયેર લઈને પરીક્ષા કરવા માટે પહોંચ્યા. પરંતુ જેવા તેઓ શ્રીગુસાઈંજીના સાનિધ્યમાં આવ્યા અને દિવ્ય સ્વરૂપના દર્શન કર્યા, કે તુરંત જ તેમનો તમામ અહંકાર, છળ-કપટ અને ટીખળ ક્ષણવારમાં ભસ્મ થઈ ગયા. તેમને સાક્ષાત પૂર્ણપુરુષોત્તમનો અનુભવ થયો.

છીતસ્વામીએ તુરંત જ શ્રીગુસાઈંજીના ચરણોમાં પડીને પોતાની ભૂલની ક્ષમા માંગી. શ્રીગુસાઈંજીએ કરુણા કરીને તેમને અભયદાન આપ્યું અને બ્રહ્મસંબંધ દીક્ષા પ્રદાન કરી. ગુરુકૃપા થતાં જ છીતસ્વામીનું હૃદય સંપૂર્ણપણે બદલાઈ ગયું અને તેમની તમામ કાવ્યશક્તિ પ્રભુના ગુણગાનમાં પરિણમી.

શ્રીગુસાઈંજીએ તેમને શ્રીનાથજીના અષ્ટછાપ કીર્તનકારોમાં સ્થાન આપ્યું. છીતસ્વામીએ વ્રજમાં પૂછરી નજીક રહેઠાણ બનાવીને શ્રીજીના અદભુત પદોની રચના કરી. તેમણે શ્રીગુસાઈંજીના ચરણોની અનન્ય મહિમા ગાતા ગાયું:

"અહો શ્રીવિઠ્ઠલ દીનદયાલ..."

તેમણે પોતાનું સમગ્ર શેષ આયુષ્ય શ્રીનાથજીના નિત્ય કીર્તન, દર્શન અને ગુરુભક્તિમાં જ વ્યતીત કર્યું.''',
    saar:
        'જીવ ગમે તેટલો અહંકારી કે પતિત હોય, પરંતુ જો તે સંત કે ગુરુના શરણમાં નિષ્કપટ ભાવે નમી જાય, તો ગુરુકૃપા તેનું જીવન અમૃતમય બનાવી દે છે.',
  ),

  VartaModel(
    id: '41',
    number: '૪૧',
    titleGujarati: 'શ્રી નંદદાસજીની વાર્તા (બીજી)',
    titleBraj: 'નંદદાસજી કી વાર્તા (દૂસરી)',
    shloka: 'लौकिकस्नेहतः श्रेष्ठो अलौकिकश्च केशव ॥ ४१ ॥',
    arth:
        'ક્ષણભંગુર લૌકિક મોહ-માયા કરતાં પરબ્રહ્મ શ્રીકૃષ્ણ પ્રત્યેનો અલૌકિક પ્રેમ જ જીવને પરમ આનંદ અને કલ્યાણ તરફ દોરી જાય છે.',
    vartaContent:
        '''શ્રી નંદદાસજી અષ્ટછાપ કવિઓમાંના એક પરમ વિદ્વાન અને અત્યંત પ્રખ્યાત ભક્ત-કવિ હતા. તેઓ ઉત્તર પ્રદેશના શૂકરક્ષેત્ર (સોરોં/રામપુર) ના સનાઢ્ય બ્રાહ્મણ હતા અને પ્રસિદ્ધ સંત કવિ ગોસ્વામી તુલસીદાસજીના ભાઈ (ચચેરા ભાઈ) થતા હતા. તેઓ કાવ્ય, વ્યાકરણ અને શાસ્ત્રોના પરમ વિદ્વાન હતા.

પ્રારંભિક જીવનમાં નંદદાસજી એક ક્ષત્રિય સ્ત્રી તરફ લૌકિક પ્રેમ અને આસક્તિમાં બદ્ધ થઈ ગયા હતા. તેમની આ આસક્તિ છોડાવવા માટે તેમના હૃદયમાં ભગવદ્-ભાવ જગાડવો આવશ્યક હતો. જ્યારે તેઓ વ્રજમાં પધાર્યા અને શ્રીગુસાઈંજી (શ્રી વિઠ્ઠલનાથજી) ના દિવ્ય દર્શન કર્યા, ત્યારે શ્રીગુસાઈંજીએ તેમના પર અત્યંત કૃપા કરી. શ્રીગુસાઈંજીના તેજોમય સ્વરૂપ અને સુબોધિનીજીના ઉપદેશથી નંદદાસજીનો લૌકિક મોહ ક્ષણવારમાં ભસ્મ થઈ ગયો અને તેમનો પ્રેમ સાક્ષાત પ્રભુ શ્રીકૃષ્ણના ચરણોમાં સ્થિર થયો.

નંદદાસજીએ શ્રીગુસાઈંજી પાસે બ્રહ્મસંબંધ પ્રાપ્ત કર્યો. શ્રીગુસાઈંજીએ તેમને શ્રીનાથજીના અષ્ટછાપ કીર્તનકારોમાં સ્થાન આપ્યું. તેમની કાવ્યકળા અને ભાષા માધુર્ય એટલાં અદભુત હતાં કે વ્રજભાષામાં કહેવત પડી: "ઔર સબ કવિયા ગઢિયા, નંદદાસ જડિયા."

તેમણે 'રાસપંચાધ્યાયી', 'ભંવરગીત', 'રૂક્મિણી મંગલ' અને 'સિદ્ધાંત પંચાધ્યાયી' જેવા મહાન ગ્રંથો અને અલૌકિક પદોની રચના કરી. તેમણે પોતાનું આખું જીવન વ્રજમાં રહીને શ્રીનાથજીની નિત્ય કીર્તનસેવા, ગુરુભક્તિ અને ભગવદ્-રસના પાનમાં જ સમર્પિત કર્યું.''',
    saar:
        'માનવનું હૃદય જ્યારે લૌકિક આસક્તિમાંથી મુક્ત થઈને ગુરુકૃપા દ્વારા પ્રભુના ચરણારવિંદમાં અર્પિત થાય છે, ત્યારે તેનું જીવન દિવ્ય અને અમર બની જાય છે.',
  ),

