    titleBraj: 'કૃષ્ણદાસ અધિકારી કી વાર્તા (દૂસરી)',
    shloka: 'सेवाविधानकुशलो निष्कामः कृष्णतत्परः ॥ ४२ ॥',
    arth:
        'ભગવદ્-સેવા અને વ્યવસ્થાપનમાં અતિ નિપુણ, નિષ્કામ ભાવવાળા અને સદા શ્રીકૃષ્ણના સ્મરણમાં તલ્લીન રહેતા વૈષ્ણવ શ્રેષ્ઠ છે.',
    vartaContent:
        '''શ્રી કૃષ્ણદાસજી અષ્ટછાપ કવિઓ અને શ્રીનાથજી મંદિરના મુખ્ય પ્રબંધક (અધિકારી) હતા. તેઓ ગુજરાતના કડી-પાટણ ક્ષેત્રના નિવાસી બ્રાહ્મણ હતા. પ્રારંભિક જીવનમાં તેઓ વ્યવહારકુશળ, વહિવટી કામકાજમાં ચતુર અને અત્યંત બુદ્ધિમાન હતા.

જ્યારે શ્રીઆચાર્યજી મહાપ્રભુજી ગુજરાત પધાર્યા, ત્યારે કૃષ્ણદાસજી તેમના દિવ્ય દર્શને આવ્યા. શ્રીમહાપ્રભુજીના અલૌકિક સ્વરૂપ અને અમૃત ઉપદેશથી પ્રભાવિત થઈને તેમણે શરણાગતિ સ્વીકારી બ્રહ્મસંબંધ પ્રાપ્ત કર્યો. શ્રીઆચાર્યજીએ તેમની ક્ષમતા અને વિવેક જોઈને શ્રીનાથજી મંદિર (ગિરિરાજજી) ના મુખ્ય 'અધિકારી' (મંદિરના સમગ્ર વહિવટ અને સેવાની વ્યવસ્થા સંભાળનાર) તરીકેની મોટી જવાબદારી સોંપી.

કૃષ્ણદાસજીએ શ્રીનાથજીના મંદિરના નિર્માણ અને વહિવટની સેવા અદભુત નિષ્ઠાપૂર્વક સંભાળી. તેમણે બાદશાહ અને અકબરના મંત્રીઓ સાથે વ્યાવહારિક સંબંધો જાળવીને મંદિર અને વ્રજભૂમિ માટે રાજાજ્ઞા (ફરમાન) પણ મેળવ્યા હતા. તેઓ મહાન સંગીતકાર અને કવિ પણ હતા. તેમણે પણ શ્રીનાથજીની કીર્તનસેવા માટે મધુર પદોની રચના કરી.

વહિવટ કરતી વખતે એકવાર તેમનાથી અન્ય વૈષ્ણવો કે ગુરુજનો પ્રત્યે ક્ષણિક કઠોરતા દર્શાવાઈ જતાં શ્રીગુસાઈંજીએ તેમને મંદિરના અધિકારી પદેથી મુક્ત કર્યા હતા. પરંતુ કૃષ્ણદાસજીએ સહેજ પણ મનમાં રોષ કે અહંકાર ન લાવતાં શ્રીજી અને ગુરુચરણનો અનન્ય આશ્રય પકડી રાખ્યો. પાછળથી તેમની અનન્ય ક્ષમા, નમ્રતા અને નિષ્કામ ભક્તિ જોઈને શ્રીગુસાઈંજીએ તેમને ફરીથી પૂર્વવત સન્માન આપ્યું. કૃષ્ણદાસજીએ પોતાનું આખું જીવન શ્રીજીની અપ્રતિમ સેવા અને ગુરુચરણની નિષ્ઠામાં જ સમર્પિત કર્યું.''',
    saar:
        'મોટી જવાબદારીઓ કે લૌકિક સત્તા મળ્યા છતાં જીવે પોતાનામાં અહંકાર ન આવવા દેવો જોઈએ. ગુરુ અને પ્રભુની સામે સદા દાસભાવ રાખવાથી જ જીવનું પરમ કલ્યાણ થાય છે.',
