        'જેનું ચિત્ત સદા શ્રીમદ્ ભાગવતજી, શ્રીકૃષ્ણની લીલા કથા અને ગુરુચરણમાં લીન રહે છે, તેને લૌકિક વૈભવ કરતાં ભગવદ્-રસ અતિ પ્રિય લાગે છે.',
    vartaContent:
        '''શ્રી સેઠ પુરુષોત્તમદાસજી ગુજરાતના એક અત્યંત પ્રતિષ્ઠિત અને ધનવાન વેપારી હતા. તેઓ સ્વભાવે અત્યંત સરસ, ઉદાર, દયાવાન અને બાલ્યાવસ્થાથી જ ભગવદ્-ભાવથી સંપન્ન હતા. લૌકિક રીતે તેમની પાસે અઢળક સંપત્તિ અને મોટો વ્યાપાર હતો, પરંતુ તેમના અંતરમાં સદા હરિચર્ચા અને સેવા માટે અદમ્ય તીવ્રતા રહેતી હતી.

જ્યારે શ્રીઆચાર્યજી મહાપ્રભુજી પોતાની ભારત પરિક્રમા દરમિયાન ગુજરાત પધાર્યા, ત્યારે પુરુષોત્તમદાસજી તેમના અલૌકિક દર્શને આવ્યા. શ્રીમહાપ્રભુજીના દિવ્ય મુખારવિંદના દર્શન અને અમૃત વાણી સાંભળીને તેમનું હૃદય સંપૂર્ણપણે કૃષ્ણમય બની ગયું. તેમણે તુરંત શ્રીઆચાર્યજીના ચરણોમાં સાષ્ટાંગ પ્રણામ કર્યા અને શરણાગતિ સ્વીકારીને બ્રહ્મસંબંધ પ્રાપ્ત કર્યો.

બ્રહ્મસંબંધ લીધા બાદ સેઠ પુરુષોત્તમદાસજીએ પોતાના ધન અને લક્ષ્મીનો મોહ છોડીને તેને સાક્ષાત પ્રભુની સંપત્તિ માની. તેમણે પોતાના ઘરમાં શ્રીઆચાર્યજીની આજ્ઞાનુસાર શ્રીજીનું દિવ્ય સ્વરૂપ પધરાવ્યું. તેઓ નિત્ય વહેલા જાગીને અત્યંત સાવધાની, પવિત્રતા અને સ્નેહપૂર્વક શ્રીજીની સેવા અર્પિત કરતા અને આવનારા સાધુ-સંતો તથા દેશ-દેશાવરના વૈષ્ણવોની નમ્ર ભાવે ભગવદ્-સ્મરણ સાથે સેવા કરતા.

એકવાર તેમના વ્યાપારિક કામકાજમાં ભારે કટોકટી અને આર્થિક મુશ્કેલી ઊભી થઈ, પરંતુ પુરુષોત્તમદાસજીએ સહેજ પણ ચિંતિત થયા વગર પોતાનો તમામ ભાર શ્રીજી અને ગુરુશ્રીમહાપ્રભુજીના ચરણો પર છોડી દીધો. તેમની અનન્ય ભક્તિ અને દ્રઢ આશ્રય જોઈને શ્રીજીએ સાક્ષાત તેમની રક્ષા કરી અને સર્વ મુશ્કેલીઓ આપોઆપ દૂર કરી દીધી. સેઠ પુરુષોત્તમદાસજીએ પોતાનું સમગ્ર આયુષ્ય નિષ્કામ ભગવદ્-સેવા, વૈષ્ણવ-સેવા અને સત્સંગમાં જ વ્યતીત કર્યું.''',
    saar:
        'ધન કે વૈભવ ભક્તિમાં ક્યારેય બાધક બનતા નથી, જો મનુષ્ય ધનનો અહંકાર છોડીને તેનો ઉપયોગ ભગવાનની સેવા અને ભગવદ્-જનના સત્સંગ માટે કરે.',
  ),

  VartaModel(
    id: '44',
