    titleGujarati: 'શ્રી પદ્મનાભદાસજીની વાર્તા (બીજી)',
    titleBraj: 'પદ્મનાભદાસજી કી વાર્તા (દૂસરી)',
    shloka: 'अनन्य आश्रयः कार्यः श्रीकृष्णचरणे सदा ॥ ४४ ॥',
    arth:
        'અન્ય તમામ લૌકિક તથા આસુરી આશ્રયોનો ત્યાગ કરીને સદા શ્રીકૃષ્ણના ચરણારવિંદનો જ એકમાત્ર અવિચળ આશ્રય રાખવો.',
    vartaContent:
        '''શ્રી પદ્મનાભદાસજી કનૌજ (ઉત્તર પ્રદેશ) ના એક પરમ ઉત્તમ બ્રાહ્મણ હતા. તેઓ કનૌજના રાજાના દરબારમાં માનવંત અને શાસ્ત્રજ્ઞ વિદ્વાન તરીકે પૂજાતા હતા. તેઓ સ્વભાવે અત્યંત સુશીલ, ગંભીર, દયાવાન અને બાલ્યાવસ્થાથી જ ભગવદ્-ભક્તિના ઉત્તમોત્તમ સંસ્કાર ધરાવનારા આત્મા હતા.

જ્યારે શ્રીઆચાર્યજી મહાપ્રભુજી પોતાની ભારત પરિક્રમા દરમિયાન કનૌજ પધાર્યા, ત્યારે પદ્મનાભદાસજી તેમના દર્શને આવ્યા. શ્રીમહાપ્રભુજીના અલૌકિક મુખારવિંદના દર્શન અને વચનામૃત સાંભળતાં જ તેમનું હૃદય સંપૂર્ણપણે પ્રભુભક્તિના રસમાં ભીંજાઈ ગયું. તેમણે તુરંત શ્રીઆચાર્યજીના ચરણોમાં સાષ્ટાંગ પ્રણામ કર્યા અને શરણાગતિ સ્વીકારી બ્રહ્મસંબંધ પ્રાપ્ત કર્યો.

બ્રહ્મસંબંધ દીક્ષા લીધા બાદ પદ્મનાભદાસજીએ પોતાના રાજકીય સ્થાન અને પાંડિત્યના અહંકારનો ત્યાગ કર્યો. તેમણે પોતાના ઘરમાં શ્રીઆચાર્યજીની આજ્ઞાનુસાર શ્રીજીનું દિવ્ય સ્વરૂપ પધરાવ્યું. તેઓ નિત્ય અત્યંત સાવધાની, ભાવ અને પવિત્રતા સાથે શ્રીજીની સેવા-અર્ચના કરતા.

એકવાર રાજદરબાર અને લૌકિક સગાસંબંધીઓ દ્વારા તેમના પર શ્રીજીની સેવા છોડીને લૌકિક કાર્યોમાં લીન થવાનું ભારે દબાણ કરવામાં આવ્યું. પરંતુ પદ્મનાભદાસજીએ ક્રોધ કર્યા વિના સ્પષ્ટ કહ્યુ કે "મારું જીવન અને સર્વસ્વ હવે માત્ર શ્રીજી અને શ્રીઆચાર્યજીના ચરણોમાં અર્પિત છે." તેમની આવી અનન્ય અને દ્રઢ ભક્તિ જોઈને સાક્ષાત શ્રીજીએ તેમની રક્ષા કરી અને વિરોધીઓ પણ નતમસ્તક થઈ ગયા. પદ્મનાભદાસજીએ પોતાનું આખું આયુષ્ય અનન્ય આશ્રય, ભગવદ્-સેવા અને સત્સંગમાં જ વિતાવ્યું.''',
    saar:
        'માનવનું કલ્યાણ ત્યારે જ શક્ય બને છે જ્યારે તે લોકેષણા અને લૌકિક ભય છોડીને સાચો અનન્ય આશ્રય ગુરુ અને ભગવાનના ચરણોમાં રાખે છે.',
  ),

  VartaModel(
