    shloka: 'ज्योतिषशास्त्रज्ञानं च भक्तीनामग्रतो तृणम् ॥ ४५ ॥',
    arth:
        'શ્રીકૃષ્ણની અનન્ય ભક્તિ અને ગુરુ આશ્રય આગળ તમામ જ્યોતિષ જ્ઞાન અને ભવિષ્યની ગણતરીઓ તૃણ સમાન બની જાય છે.',
    vartaContent:
        '''શ્રી ગડા જોશીજી કનૌજ (ઉત્તર પ્રદેશ) ના એક અત્યંત પ્રખ્યાત બ્રાહ્મણ અને પ્રકાંડ જ્યોતિષી હતા. તેઓ સૂર્યમંડળ, ગ્રહદશા અને કાળ ગણનાના અસાધારણ જ્ઞાની હતા. તેઓ લોકોનું ભવિષ્ય જોઈને ચોક્કસ આગાહીઓ કરવા માટે પ્રખ્યાત હતા, પરંતુ શાસ્ત્ર અને જ્યોતિષનો આટલો મોટો જ્ઞાની હોવા છતાં તેમના હૃદયમાં ભગવદ્-રસ અને આંતરિક શાંતિનો અભાવ હતો.

જ્યારે શ્રીઆચાર્યજી મહાપ્રભુજી પોતાની ભારત પરિક્રમા દરમિયાન કનૌજ પધાર્યા, ત્યારે ગડા જોશીજી પણ અન્ય વિદ્વાનો સાથે શ્રીમહાપ્રભુજીના દિવ્ય દર્શને આવ્યા. તેમણે શ્રીઆચાર્યજીના તેજોમય દિવ્ય સ્વરૂપના દર્શન કર્યા અને તેમના વચનામૃત સાંભળ્યા. શ્રીમહાપ્રભુજીએ તેમને સમજાવ્યું કે ગ્રહ અને કાળ એ સાક્ષાત ભગવાનની શક્તિઓ છે, અને જે જીવ ભગવાન શ્રીકૃષ્ણનો આશ્રય લે છે, તેના તમામ કાળ અને દ્રષ્ટિ દોષ ક્ષણવારમાં નષ્ટ થઈ જાય છે.

ગડા જોશીજીનો તમામ પાંડિત્ય અને જ્યોતિષનો અહંકાર ગળી ગયો. તેમણે તુરંત શ્રીઆચાર્યજી મહાપ્રભુજીના ચરણોમાં સાષ્ટાંગ પ્રણામ કર્યા અને શરણાગતિ સ્વીકારીને બ્રહ્મસંબંધ પ્રાપ્ત કર્યો.

દીક્ષા લીધા બાદ તેમણે પોતાના જ્યોતિષના લૌકિક અહંકારનો સંપૂર્ણ ત્યાગ કર્યો. તેમણે પોતાના ઘરમાં શ્રીઆચાર્યજીની આજ્ઞાનુસાર શ્રીજીનું સ્વરૂપ પધરાવ્યું. તેઓ નિત્ય પ્રભુની સેવામાં તલ્લીન રહેતા અને પોતાની વિદ્યાનો ઉપયોગ માત્ર પ્રભુની સેવા અને ઉત્સવોના શુભ મુહૂર્તો સમજવા પૂરતો જ કરતા. ગડા જોશીજીએ પોતાનું આખું જીવન ગુરુચરણ અને નિષ્કામ ભગવદ્-સેવામાં જ વ્યતીત કર્યું.''',
    saar:
        'માનવનું ભાગ્ય કોઈ ગ્રહ કે નક્ષત્ર નથી બદલી શકતા, પરંતુ જ્યારે જીવ સાચા ગુરુના શરણમાં જઈને ભગવાનનો અનન્ય આશ્રય સ્વીકારે છે, ત્યારે તેનું પરમ કલ્યાણ નિશ્ચિત થઈ જાય છે.',
  ),

