    shloka: 'चित्तस्य शुद्धिः प्रथमा भक्तिमार्गे निरन्तरम् ॥ ४६ ॥',
    arth:
        'ભક્તિમાર્ગમાં પ્રવેશીને જીવના હૃદયની સંપૂર્ણ શુદ્ધિ, કપટહીનતા અને નિષ્કામ ભાવ જ સર્વોચ્ચ સાધન બની રહે છે.',
    vartaContent:
        '''શ્રી ત્રિપુરાદાસજી કાયસ્થ જ્ઞાતિના એક પરમ ઉત્તમ વૈષ્ણવ હતા. તેઓ ઉત્તર પ્રદેશના ક્ષેત્રમાં રહેતા હતા અને લૌકિક રીતે સરકારી વહિવટી કામકાજ તથા કારકુની સંભાળતા હતા. તેઓ સ્વભાવે અત્યંત સરસ, વિવેકી, નમ્ર અને સંસારમાં અનાસક્ત રહીને ભગવદ્-સ્મરણ કરનારા આત્મા હતા.

જ્યારે શ્રીઆચાર્યજી મહાપ્રભુજી પોતાની ભારત પરિક્રમા દરમિયાન તે ક્ષેત્રમાં પધાર્યા, ત્યારે ત્રિપુરાદાસજી તેમના દિવ્ય દર્શને આવ્યા. શ્રીમહાપ્રભુજીના અલૌકિક સ્વરૂપ અને સુબોધિનીજીનો ઉપદેશ સાંભળીને ત્રિપુરાદાસજીનું મન સંપૂર્ણપણે ભક્તિભાવમાં ડૂબી ગયું. તેમણે તુરંત શ્રીઆચાર્યજીના ચરણોમાં સાષ્ટાંગ પ્રણામ કર્યા અને શરણાગતિ સ્વીકારીને બ્રહ્મસંબંધ પ્રાપ્ત કર્યો.

બ્રહ્મસંબંધ લીધા બાદ ત્રિપુરાદાસજીએ પોતાના ઘરમાં શ્રીઆચાર્યજીની આજ્ઞાનુસાર શ્રીજીનું દિવ્ય સ્વરૂપ પધરાવ્યું. તેઓ નોકરી-ધંધો અને વહિવટી કાર્યો માત્ર લૌકિક મર્યાદા જાળવવા માટે કરતા, પરંતુ તેમનું ચિત્ત સદા ઘરમાં વિરાજતા પોતાના ઈષ્ટદેવ શ્રીજીના ચરણારવિંદમાં જ લીન રહેતું.

એકવાર તેમના વ્યાવહારિક કામકાજ દરમિયાન કેટલાક અધિકારીઓએ તેમની ઈમાનદારી અને ભગવદ્-નિષ્ઠા પર વિરોધ ઊભો કર્યો, પરંતુ ત્રિપુરાદાસજીએ સહેજ પણ ચિંતા કર્યા વિના તમામ ભાર પોતાના શ્રીજી અને ગુરુદેવના ચરણો પર છોડી દીધો. તેમની અવિચળ અને નિષ્કામ ભક્તિ જોઈને સાક્ષાત શ્રીજીએ તેમની રક્ષા કરી અને વિરોધીઓને શરમાવું પડ્યું. ત્રિપુરાદાસજીએ પોતાનું સમગ્ર શેષ આયુષ્ય નિષ્કામ ભગવદ્-સેવા અને ગુરુચરણોના દ્રઢ આશ્રયમાં જ વ્યતીત કર્યું.''',
    saar:
        'સંસારના વ્યાવહારિક દાવપેચ કે નોકરી-ધંધા વચ્ચે પણ જે જીવ મનથી સાચો, ઈમાનદાર અને ભગવાન તથા ગુરુ પર અવિચળ ભરોસો રાખનારો છે, તેની સાક્ષાત પ્રભુ સદા રક્ષા કરે છે.',
  ),

  VartaModel(
    id: '47',
    number: '૪૭',
    titleGujarati: 'શ્રી દામોદરદાસ સંભલવાળાની વાર્તા (બીજી)',
    titleBraj: 'દામોદરદાસ સંભલવાળા કી વાર્તા (દૂસરી)',
    shloka: 'निष्कपटभावेन लभ्यते श्रीकृष्ण कृपा सदा ॥ ४७ ॥',
    arth:
        'સંપૂર્ણ નિષ્કપટ ભાવ, પરમ વિવેક અને ગુરુવાક્ય પર અવિચળ વિશ્વાસ રાખવાથી જીવ પર શ્રીકૃષ્ણ અને શ્રીગુરુની સદા અખંડ કૃપા વરસતી રહે છે.',
    vartaContent:
        '''શ્રી દામોદરદાસજી સંભલ (ઉત્તર પ્રદેશ) ક્ષેત્રના નિવાસી એક અત્યંત ઉત્તમ અને પવિત્ર ક્ષત્રિય વૈષ્ણવ હતા. તેઓ સ્વભાવે અત્યંત કોમળ, વિવેકી, સત્યનિષ્ઠ અને બાલ્યાવસ્થાથી જ સંસારના લૌકિક રાગ-દ્વેષથી પર રહીને પ્રભુભક્તિના આંતરિક ભાવમાં રમમાણ રહેનારા હતા.

જ્યારે શ્રીઆચાર્યજી મહાપ્રભુજી પોતાની ભારત પરિક્રમા દરમિયાન સંભલ પધાર્યા, ત્યારે દામોદરદાસજી તેમના દિવ્ય દર્શનાર્થે આવ્યા. શ્રીમહાપ્રભુજીના તેજોમય સ્વરૂપ અને અમૃતમય વચનામૃત સાંભળીને તેમનું હૃદય પૂર્ણપણે શ્રીકૃષ્ણરસમાં ડૂબી ગયું. તેમણે તુરંત શ્રીઆચાર્યજીના ચરણોમાં શરણાગતિ સ્વીકારીને બ્રહ્મસંબંધ પ્રાપ્ત કર્યો.

દીક્ષા લીધા બાદ શ્રી દામોદરદાસજીએ પોતાના ઘરમાં શ્રીઆચાર્યજીની આજ્ઞા અનુસાર શ્રીજીનું દિવ્ય સ્વરૂપ પધરાવ્યું. તેઓ નિત્ય અત્યંત પવિત્રતા, સાવધાની અને સ્નેહપૂર્વક શ્રીજીની સેવા અર્પિત કરતા. પોતાની લૌકિક આજીવિકા સંભાળતી વખતે પણ તેમનું મન સદા ઘરમાં વિરાજતા પોતાના ઈષ્ટદેવ શ્રીજી અને શ્રીઆચાર્યજીના ચરણારવિંદમાં જ તલ્લીન રહેતું.

એકવાર તેમના નગર પર લૌકિક ઉપદ્રવ અને મુશ્કેલી આવી પડી, પરંતુ દામોદરદાસજીએ સહેજ પણ વિચલિત થયા વગર અનન્ય આશ્રય રાખીને તમામ ભાર પોતાના શ્રીજી અને ગુરુદેવ પર છોડી દીધો. તેમની અવિચળ અને નિષ્કપટ ભક્તિ જોઈને સાક્ષાત શ્રીજીએ તેમની અને તેમના ઘરની રક્ષા કરી. દામોદરદાસજીએ પોતાનું આખું આયુષ્ય શ્રીજીની અનન્ય સેવા, ગુરુભક્તિ અને સત્સંગમાં જ વ્યતીત કર્યું.''',
    saar:
        'સંસારની પરિસ્થિતિઓ ગમે તેવી વિષમ હોય, પરંતુ જે જીવ મનથી સાચો રહીને ભગવાન અને ગુરુદેવનો દ્રઢ આશ્રય પકડી રાખે છે, તેને કોઈ પણ લૌકિક સંકટ સ્પર્શી શકતું નથી.',
  ),

  VartaModel(
    id: '48',
    number: '૪૮',
    titleGujarati: 'શ્રી રાજા પૂરણમલ્લની વાર્તા',
    titleBraj: 'રાજા પૂરણમલ્લ કી વાર્તા',
    shloka: 'राजलक्ष्मीं परित्यज्य भजेत् श्रीवल्लभं प्रभुम् ॥ ४८ ॥',
    arth:
        'રાજવૈભવ, સત્તા અને પદ-પ્રતિષ્ઠાના અહંકારનો ત્યાગ કરીને શ્રીવલ્લભ પ્રભુના ચરણારવિંદનો અનન્ય આશ્રય સ્વીકારવો.',
    vartaContent:
        '''શ્રી રાજા પૂરણમલ્લજી ક્ષત્રિય કુળના એક અત્યંત પ્રતાપી અને સમૃદ્ધ રાજા હતા. તેમની પાસે વિશાળ રાજ્ય, સેના અને લૌકિક વૈભવની કોઈ કમી નહોતી. પરંતુ પૂર્વજન્મના મહાન સંસ્કારોને કારણે તેમનું મન રાજકાજ કે ભોગ-વિલાસમાં અટવાવાને બદલે સદા ભગવદ્-પ્રાપ્તિ અને અલૌકિક આંતરિક શાંતિની શોધમાં રહેતું હતું.

જ્યારે શ્રીઆચાર્યજી મહાપ્રભુજી પોતાની ભારત પરિક્રમા દરમિયાન તે ક્ષેત્રમાં પધાર્યા, ત્યારે રાજા પૂરણમલ્લજી પોતાના રાજવી ઠાઠ સાથે શ્રીમહાપ્રભુજીના દર્શને આવ્યા. પરંતુ શ્રીઆચાર્યજીના અલૌકિક, દિવ્ય અને તેજોમય સ્વરૂપને જોતાં જ તેમનો સત્તા અને રાજપદનો તમામ અહંકાર ઓગળી ગયો. શ્રીમહાપ્રભુજીના દિવ્ય વચનામૃત સાંભળીને તેમણે શરણાગતિ સ્વીકારી અને બ્રહ્મસંબંધ પ્રાપ્ત કર્યો.

બ્રહ્મસંબંધ લીધા બાદ રાજા પૂરણમલ્લજીએ પોતાના રાજ્ય અને સંપત્તિને ઠાકુરજીની સામગ્રી માનીને નમ્રતાપૂર્વક વર્તવાનું શરૂ કર્યું. તેમણે પોતાના ઘરમાં તથા રાજ્યમાં શ્રીઆચાર્યજીની આજ્ઞાનુસાર ભગવદ્-સેવા પધરાવી. તેઓ નિત્ય રાજકાજના કાર્યો પતાવ્યા બાદ અત્યંત પવિત્રતા, સાવધાની અને સ્નેહભાવે શ્રીજીની સેવા અર્પિત કરતા.

જ્યારે પણ તેમના રાજ્ય પર લૌકિક કે યુદ્ધના પ્રસંગો આવ્યા, ત્યારે તેમણે પોતાની શક્તિ પર ગર્વ કરવાને બદલે સદા શ્રીજી અને શ્રીઆચાર્યજીના ચરણોનો અનન્ય આશ્રય રાખ્યો. શ્રીજીએ સાક્ષાત તેમની અને તેમના રાજ્યની રક્ષા કરી. રાજા પૂરણમલ્લજીએ પોતાનું શેષ આયુષ્ય રાજધર્મ બજાવવાની સાથે સાચા વૈષ્ણવ તરીકે અનન્ય ભગવદ્-સેવામાં જ વ્યતીત કર્યું.''',
    saar:
        'રાજપદ કે લૌકિક સત્તા મળવા છતાં જો મનુષ્ય નમ્ર રહીને પોતાનું સર્વસ્વ ભગવાનના ચરણોમાં સમર્પિત કરે, તો સત્તા પણ ભક્તિમાર્ગમાં બાધક બનતી નથી.',
  ),

