    shloka: 'निष्कपटभावेन लभ्यते श्रीकृष्ण सेवा निरन्तरम् ॥ ४९ ॥',
    arth:
        'સંસારના સર્વ છળ-કપટનો ત્યાગ કરીને નિર્મળ, નિષ્કપટ ભાવે શ્રીકૃષ્ણના ચરણોમાં અર્પિત થવાથી નિત્ય અલૌકિક સેવા પ્રાપ્ત થાય છે.',
    vartaContent:
        '''શ્રી ગોવિંદદાસજી ભલ્લા ક્ષત્રિય જ્ઞાતિના એક અત્યંત ઉત્તમ, વિવેકી અને પવિત્ર આત્મા હતા. તેઓ વ્યવહારમાં અત્યંત પ્રવીણ હોવાની સાથે સ્વભાવે પરમ સરસ, નમ્ર અને સાધુપ્રિય હતા.

જ્યારે શ્રીઆચાર્યજી મહાપ્રભુજી પોતાની ભારત પરિક્રમા દરમિયાન તે ક્ષેત્રમાં પધાર્યા, ત્યારે ગોવિંદદાસજી તેમના દિવ્ય દર્શનાર્થે આવ્યા. શ્રીમહાપ્રભુજીના તેજોમય સ્વરૂપ અને સુબોધિનીજીના દિવ્ય વચનામૃત સાંભળતાં જ તેમનું હૃદય સંપૂર્ણપણે ભક્તિરસથી છલકાઈ ગયું. તેમણે તુરંત શ્રીઆચાર્યજીના ચરણોમાં સાષ્ટાંગ પ્રણામ કર્યા અને શરણાગતિ સ્વીકારીને બ્રહ્મસંબંધ પ્રાપ્ત કર્યો.

બ્રહ્મસંબંધ લીધા બાદ ગોવિંદદાસજીએ પોતાના ઘરમાં શ્રીઆચાર્યજીની આજ્ઞાનુસાર શ્રીજીનું દિવ્ય સ્વરૂપ પધરાવ્યું. તેઓ નિત્ય સવારે વહેલા જાગીને અત્યંત સાવધાની, પવિત્રતા અને દિવ્ય ભાવપૂર્વક શ્રીજીની સેવા અર્પિત કરતા. પોતાના લૌકિક ધંધા-રોજગાર સંભાળતી વખતે પણ તેમનું મન સદા પોતાના ઈષ્ટદેવ શ્રીજીના ચરણારવિંદના ધ્યાનમાં જ પરોવાયેલું રહેતું.

એકવાર તેમના વ્યાવહારિક કામકાજમાં કેટલાક વિરોધીઓએ મુશ્કેલી ઊભી કરી અને આર્થિક નુકસાન પહોંચાડવાનો પ્રયાસ કર્યો, પરંતુ ગોવિંદદાસજીએ સહેજ પણ ચિંતા કર્યા વગર પોતાનો તમામ ભાર શ્રીજી અને ગુરુશ્રીમહાપ્રભુજીના ચરણો પર છોડી દીધો. તેમની અનન્ય નિષ્ઠા અને દ્રઢ આશ્રય જોઈને સાક્ષાત શ્રીજીએ તેમની રક્ષા કરી અને સર્વ વિઘ્નો શાંત કરી દીધા. ગોવિંદદાસજીએ પોતાનું શેષ આયુષ્ય અનન્ય આશ્રય, ભગવદ્-સેવા અને સાધુ-વૈષ્ણવોના સત્સંગમાં જ વ્યતીત કર્યું.''',
    saar:
        'સંસારના લૌકિક વ્યવહારો કે કાવતરાંઓ વચ્ચે પણ જે જીવનું હૃદય નિષ્કપટ રહે છે અને ગુરુ તથા ભગવાન પર અવિચળ વિશ્વાસ રાખે છે, તેનું પ્રભુ સદા કલ્યાણ કરે છે.',
  ),

  VartaModel(
    id: '50',
    number: '૫૦',
    titleGujarati: 'શ્રી માધવદાસ ભાટિયાની વાર્તા',
    titleBraj: 'માધવદાસ ભાટિયા કી વાર્તા',
    shloka: 'सर्वस्वं भगवत्यर्प्य भजेत् श्रीकृष्णमव्ययम् ॥ ५० ॥',
    arth:
        'અહંકાર, વૈભવ અને મમતાનો સંપૂર્ણ ત્યાગ કરીને પોતાનું સર્વસ્વ ભગવાન અને ગુરુદેવના ચરણોમાં અર્પિત કરવું.',
    vartaContent:
        '''શ્રી માધવદાસજી ભાટિયા જ્ઞાતિના એક અત્યંત પ્રતિષ્ઠિત, ઉદાર અને ધનવાન વેપારી હતા. તેઓ સ્વભાવે પરમ સરસ, નમ્ર, શાંત અને પૂર્વજન્મના સંસ્કારોથી સંપન્ન ભગવદ્-ભક્ત હતા. લૌકિક રીતે તેમની પાસે અઢળક સંપત્તિ, વ્યાપાર અને વૈભવની કોઈ કમી નહોતી, પરંતુ તેમના અંતરમાં સદા ભગવદ્-પ્રાપ્તિની અદમ્ય તીવ્રતા અને આંતરિક શાંતિની શોધ રહેતી હતી.

જ્યારે શ્રીઆચાર્યજી મહાપ્રભુજી પોતાની ભારત પરિક્રમા દરમિયાન તે ક્ષેત્રમાં પધાર્યા, ત્યારે માધવદાસજી તેમના અલૌકિક સ્વરૂપના દિવ્ય દર્શને આવ્યા. શ્રીમહાપ્રભુજીના દિવ્ય મુખારવિંદમાંથી ઝરતી કથા અને સુબોધિનીજીનો ઉપદેશ સાંભળીને તેમનું હૃદય સંપૂર્ણપણે કૃષ્ણમય બની ગયું. તેમણે તુરંત શ્રીઆચાર્યજીના ચરણોમાં સાષ્ટાંગ પ્રણામ કર્યા અને શરણાગતિ સ્વીકારીને બ્રહ્મસંબંધ પ્રાપ્ત કર્યો.

બ્રહ્મસંબંધ લીધા બાદ માધવદાસજીએ પોતાના ધન અને લક્ષ્મીનો અહંકાર છોડીને તેને સાક્ષાત પ્રભુની જ સામગ્રી માની. તેમણે પોતાના ઘરમાં શ્રીઆચાર્યજીની આજ્ઞાનુસાર શ્રીજીનું દિવ્ય સ્વરૂપ પધરાવ્યું. તેઓ નિત્ય વહેલા જાગીને અત્યંત સાવધાની, પવિત્રતા અને સ્નેહપૂર્વક શ્રીજીની સેવા અર્પિત કરતા અને દેશ-દેશાવરથી આવતા સાધુ-સંતો તથા વૈષ્ણવોની નમ્ર ભાવે સેવા કરતા.

એકવાર તેમના વ્યાપારિક કાર્યોમાં કેટલીક જટિલ મુશ્કેલીઓ ઊભી થઈ, પરંતુ માધવદાસજીએ સહેજ પણ અધીરા થયા વિના પોતાનો તમામ ભાર શ્રીજી અને ગુરુશ્રીમહાપ્રભુજીના ચરણો પર છોડી દીધો. તેમની અનન્ય નિષ્ઠા અને દ્રઢ આશ્રય જોઈને શ્રીજીએ પોતે સાક્ષાત તેમનું સંકટ દૂર કર્યું. માધવદાસજીએ પોતાનું શેષ આયુષ્ય અનન્ય આશ્રય, ભગવદ્-સેવા અને સત્સંગમાં જ વ્યતીત કર્યું.''',
    saar:
        'ધન કે લૌકિક સમૃદ્ધિ ભક્તિમાં ક્યારેય બાધક બનતી નથી, જો મનુષ્ય અહંકાર છોડીને પોતાની સંપત્તિ અને મન બંને ભગવાનના ચરણોમાં અર્પિત કરે.',
  ),

  VartaModel(
