    titleBraj: 'કલ્યાણભટ્ટ કી વાર્તા',
    shloka: 'कथाश्रवणमात्रेण हृदयं कृष्णतां व्रजेत् ॥ ५१ ॥',
    arth:
        'શ્રીકૃષ્ણની લીલા કથાનું શ્રવણ કરવા માત્રથી જીવનું હૃદય સંપૂર્ણપણે કૃષ્ણમય બનીને પવિત્ર થઈ જાય છે.',
    vartaContent:
        '''શ્રી કલ્યાણભટ્ટજી કાશી (વારાણસી) ના એક અત્યંત પ્રકાંડ શાસ્ત્રજ્ઞ અને વેદાંતી બ્રાહ્મણ હતા. તેઓ પૌરાણિક કથાકાર તરીકે અત્યંત લોકપ્રિય હતા અને સંસ્કૃત ભાષા તથા કથા વાચનમાં અસાધારણ ચતુર હતા. પરંતુ શાસ્ત્રોના અગાધ જ્ઞાની હોવા છતાં તેમના હૃદયમાં ભગવદ્-રસ અને આંતરિક શાંતિનો અભાવ હતો.

જ્યારે શ્રીઆચાર્યજી મહાપ્રભુજી પોતાની ભારત પરિક્રમા દરમિયાન કાશી પધાર્યા, ત્યારે કલ્યાણભટ્ટજી શ્રીમહાપ્રભુજીના દિવ્ય દર્શને આવ્યા. શ્રીમહાપ્રભુજીના મુખારવિંદમાંથી ઝરતી શ્રીમદ્ ભાગવતજીની અમૃતમય કથા અને સુબોધિનીજીનો ઉપદેશ સાંભળીને કલ્યાણભટ્ટજીનો તમામ શાબ્દિક અને વિદ્યાનો અહંકાર ક્ષણવારમાં ભસ્મ થઈ ગયો. તેમને સાક્ષાત ભક્તિરસનો અલૌકિક અનુભવ થયો.

તેમણે તુરંત શ્રીઆચાર્યજી મહાપ્રભુજીના ચરણોમાં સાષ્ટાંગ પ્રણામ કર્યા અને શરણાગતિ સ્વીકારીને બ્રહ્મસંબંધ પ્રાપ્ત કર્યો.

બ્રહ્મસંબંધ દીક્ષા લીધા બાદ કલ્યાણભટ્ટજીએ પોતાના પાંડિત્યનો અહંકાર છોડી દીધો. તેમણે પોતાના ઘરમાં શ્રીઆચાર્યજીની આજ્ઞાનુસાર શ્રીજીનું દિવ્ય સ્વરૂપ પધરાવ્યું. તેઓ નિત્ય શ્રીજીની અનન્ય સેવા અર્પિત કરતા અને ભગવદ્-રસથી છલકાતી વાણીમાં ભાગવત કથા અને શ્રીજીના ગુણગાન કરતા. કલ્યાણભટ્ટજીએ પોતાનું આખું આયુષ્ય શ્રીજીની સેવા અને ગુરુચરણોની દ્રઢ નિષ્ઠામાં જ સમર્પિત કર્યું.''',
    saar:
        'શાસ્ત્રોનું કેવળ શુષ્ક જ્ઞાતિ કે પાંડિત્ય મુક્તિ આપતું નથી, પરંતુ જ્યારે જીવ સંત અને ગુરુના શરણમાં જઈને સાચા ભાવથી ભગવદ્-કથામાં લીન થાય છે, ત્યારે જ જીવન સાર્થક બને છે.',
  ),

  VartaModel(
    id: '52',
    number: '૫૨',
    titleGujarati: 'શ્રી રામદાસજી ખવાજવાળાની વાર્તા',
    titleBraj: 'રામદાસજી ખવાજવાળા કી વાર્તા',
