    arth:
        'ગુરુદેવના ચરણોમાં નિષ્કામ ભાવે અર્પિત થઈને અનન્ય ભાવથી ભગવદ્-સેવામાં તલ્લીન રહેવું.',
    vartaContent:
        '''શ્રી રામદાસજી ખવાજવાળા ઉત્તર પ્રદેશના એક અત્યંત ઉત્તમ, પવિત્ર અને નમ્ર ભાવવાળા વૈષ્ણવ હતા. તેઓ સ્વભાવે અતિ મૃદુ, દયાવાન, વિવેકી અને બાલ્યાવસ્થાથી જ સંસારની લોકેષણાઓથી પર રહીને પ્રભુસ્મરણમાં રમમાણ રહેનારા હતા.

જ્યારે શ્રીઆચાર્યજી મહાપ્રભુજી પોતાની ભારત પરિક્રમા દરમિયાન તે ક્ષેત્રમાં પધાર્યા, ત્યારે રામદાસજી તેમના દિવ્ય દર્શનાર્થે આવ્યા. શ્રીમહાપ્રભુજીના દિવ્ય સ્વરૂપના દર્શન કરતાં જ તેમનું મન સંપૂર્ણપણે પ્રભુના ચરણોમાં સ્થિર થઈ ગયું. તેમણે શ્રીઆચાર્યજી મહાપ્રભુજી પાસે શરણાગતિ સ્વીકારીને બ્રહ્મસંબંધ પ્રાપ્ત કર્યો.

બ્રહ્મસંબંધ લીધા બાદ રામદાસજીએ પોતાના ઘરમાં શ્રીઆચાર્યજીની આજ્ઞાનુસાર શ્રીજીનું સ્વરૂપ પધરાવ્યું. તેઓ નિત્ય વહેલી સવારે જાગીને અત્યંત પવિત્રતા, સાવધાની અને સ્નેહપૂર્વક શ્રીજીની સેવા અર્પિત કરતા. પોતાના લૌકિક કાર્યો પતાવવાની સાથે તેમનું અંતઃકરણ સદા પોતાના ઈષ્ટદેવ શ્રીજી અને શ્રીઆચાર્યજીના ચરણારવિંદમાં જ રહેતું.

એકવાર તેમના જીવનમાં લૌકિક વિઘ્નો અને પરિસ્થિતિઓ કઠિન બની, પરંતુ રામદાસજીએ સહેજ પણ ચિંતિત થયા વિના તમામ ભાર પોતાના શ્રીજી અને ગુરુદેવના ચરણો પર છોડી દીધો. તેમની અવિચળ અને નિષ્કામ ભક્તિ જોઈને શ્રીજીએ તેમની રક્ષા કરી. રામદાસજીએ પોતાનું આખું આયુષ્ય શ્રીજીની અનન્ય સેવા, ગુરુભક્તિ અને સત્સંગમાં જ વિતાવ્યું.''',
    saar:
        'સંસારના વિઘ્નો અને કષ્ટો વચ્ચે પણ જે જીવ ગુરુ અને ભગવાનના ચરણોનો અનન્ય આશ્રય પકડી રાખે છે, તેનું કલ્યાણ સાક્ષાત પ્રભુ કરે છે.',
  ),

  VartaModel(
    id: '53',
    number: '૫૩',
    titleGujarati: 'શ્રી ગોવિંદદાસ ઠક્કોરની વાર્તા',
    titleBraj: 'ગોવિંદદાસ ઠક્કોર કી વાર્તા',
    shloka: 'चित्तस्य निश्चलता ज्ञेया भगवद्भक्तियोगतः ॥ ५३ ॥',
    arth:
        'ભગવાન શ્રીકૃષ્ણની અનન્ય ભક્તિ અને ગુરુચરણના આશ્રયથી જ જીવના ચિત્તને સાચી અવિચળતા અને પરમ શાંતિ પ્રાપ્ત થાય છે.',
    vartaContent:
        '''શ્રી ગોવિંદદાસ ઠક્કોરજી લોહાણા/ક્ષત્રિય વૈષ્ણવ સમુદાયના એક અત્યંત પ્રભાવશાળી અને પવિત્ર આત્મા હતા. તેઓ વ્યવહારિક જીવનમાં અત્યંત પ્રવીણ, વિવેકી, સત્યનિષ્ઠ અને દયાવાન હતા. પોતાની લૌકિક જવાબદારીઓ નિભાવવાની સાથે તેમના અંતરમાં નિત્ય ભગવદ્-સ્મરણ અને ગુરુચરણની સેવા અર્થે તીવ્ર ભાવ રહેતો હતો.

જ્યારે શ્રીઆચાર્યજી મહાપ્રભુજી પોતાની ભારત પરિક્રમા દરમિયાન તે ક્ષેત્રમાં પધાર્યા, ત્યારે ગોવિંદદાસજી શ્રીમહાપ્રભુજીના અલૌકિક દિવ્ય સ્વરૂપના દર્શને આવ્યા. શ્રીમહાપ્રભુજીના દિવ્ય મુખારવિંદના દર્શન અને વચનામૃત સાંભળતાં જ તેમનું અંતઃકરણ સંપૂર્ણપણે કૃષ્ણમય બની ગયું. તેમણે તુરંત શ્રીઆચાર્યજીના ચરણોમાં સાષ્ટાંગ પ્રણામ કર્યા અને બ્રહ્મસંબંધ પ્રાપ્ત કર્યો.

બ્રહ્મસંબંધ લીધા બાદ ગોવિંદદાસ ઠક્કોરજીએ પોતાના ઘરમાં શ્રીઆચાર્યજીની આજ્ઞાનુસાર શ્રીજીનું દિવ્ય સ્વરૂપ પધરાવ્યું. તેઓ નિત્ય અત્યંત પવિત્રતા, સાવધાની અને સ્નેહપૂર્વક શ્રીજીની સેવા અર્પિત કરતા. પોતાના વ્યાપારિક અને ક્ષાત્ર વ્યવહારો પૂરા કરતી વખતે પણ તેમનું મન સદા શ્રીજી અને શ્રીઆચાર્યજીના ચરણારવિંદના ધ્યાનમાં જ તલ્લીન રહેતું.

એકવાર તેમના પર લૌકિક સંકટ અને વ્યાપારિક મુશ્કેલીઓ આવી પડી, પરંતુ ગોવિંદદાસજીએ સહેજ પણ ચિંતિત થયા વિના પોતાનો તમામ ભાર પોતાના ઈષ્ટદેવ શ્રીજી અને શ્રીઆચાર્યજીના ચરણો પર છોડી દીધો. તેમની અનન્ય નિષ્ઠા જોઈને શ્રીજીએ સાક્ષાત તેમની રક્ષા કરી અને વિઘ્નો દૂર કર્યા. ગોવિંદદાસજીએ પોતાનું આખું આયુષ્ય શ્રીજીની નિષ્કામ સેવા, ગુરુભક્તિ અને સાધુ-સંતોના સત્સંગમાં જ વ્યતીત કર્યું.''',
    saar:
        'સંસારના વ્યાવહારિક દાવપેચ કે મુશ્કેલીઓ વચ્ચે પણ જે જીવ મનથી સાચો રહે છે અને ભગવાન તથા ગુરુદેવ પર અવિચળ ભરોસો રાખે છે, તેને સાક્ષાત પ્રભુ સદા છત્રછાયા આપે છે.',
  ),

