    arth:
        'શૂરવીરતા, સાહસ અને શક્તિ જ્યારે ભગવદ્-સેવા અને ધર્મરક્ષા અર્થે યોજાય છે, ત્યારે જ ભક્તિમાર્ગમાં સાચી શોભા પામે છે.',
    vartaContent:
        '''શ્રી ગોવિંદદાસ ચૌહાણજી ક્ષત્રિય ચૌહાણ વંશના એક અત્યંત શૂરવીર, પરાક્રમી અને સ્વમાની પરાક્રમી વ્યક્તિ હતા. તેઓ સૈન્ય અને યુદ્ધ કળામાં પ્રવીણ હતા, પરંતુ ક્ષાત્ર તેજની સાથે તેમનામાં પૂર્વજન્મના સંસ્કારોને લીધે ભગવદ્-ભક્તિનો અદભુત સંસ્કાર અને વિવેક પણ રહેલો હતો.

જ્યારે શ્રીઆચાર્યજી મહાપ્રભુજી પોતાની ભારત પરિક્રમા દરમિયાન તે ક્ષેત્રમાં પધાર્યા, ત્યારે ગોવિંદદાસ ચૌહાણજી શ્રીમહાપ્રભુજીના દિવ્ય દર્શનાર્થે આવ્યા. શ્રીઆચાર્યજીના તેજોમય દિવ્ય સ્વરૂપના દર્શન કરતાં જ તેમનો તમામ ક્ષાત્ર મોહ અને ક્રોધ શાંત થઈ ગયા. શ્રીમહાપ્રભુજીના મુખારવિંદના વચનામૃત સાંભળીને તેમણે સાષ્ટાંગ પ્રણામ કર્યા અને શરણાગતિ સ્વીકારીને બ્રહ્મસંબંધ પ્રાપ્ત કર્યો.

બ્રહ્મસંબંધ લીધા બાદ ગોવિંદદાસ ચૌહાણજીએ પોતાની શક્તિ અને પરાક્રમને શ્રીજીની સેવામાં સમર્પિત કર્યા. તેમણે પોતાના ઘરમાં શ્રીઆચાર્યજીની આજ્ઞાનુસાર શ્રીજીનું સ્વરૂપ પધરાવ્યું. તેઓ નિત્ય અત્યંત શુદ્ધિ, સાવધાની અને દિવ્ય સ્નેહથી શ્રીજીની સેવા અર્પિત કરતા.

જ્યારે પણ વૈષ્ણવો પર કે ભગવદ્-સેવામાં કોઈ વિઘ્ન કે લૌકિક સંકટ આવતું, ત્યારે ગોવિંદદાસજી અવિચળ દ્રઢતા સાથે સાચા દાસ બનીને પ્રભુના આશ્રયે ઊભા રહેતા. તેમની નિર્ભયતા અને દ્રઢ આશ્રય જોઈને સાક્ષાત શ્રીજી સદા તેમની સાથે રહીને રક્ષા કરતા. ગોવિંદદાસ ચૌહાણજીએ પોતાનું શેષ આયુષ્ય અનન્ય આશ્રય, ભગવદ્-સેવા અને ગુરુચરણોમાં જ વ્યતીત કર્યું.''',
    saar:
        'દરેક મનુષ્યની પોતાની શક્તિ કે ગુણ ત્યારે જ સાર્થક બને છે જ્યારે તેનો ઉપયોગ અહંકાર પ્રદર્શિત કરવા માટે નહીં, પરંતુ પ્રભુસેવા અને ધર્મરક્ષા માટે થાય.',
  ),

  VartaModel(
    id: '55',
    number: '૫૫',
    titleGujarati: 'શ્રી રામદાસજી કોઠારીની વાર્તા',
    titleBraj: 'રામદાસજી કોઠારી કી વાર્તા',
    shloka: 'सर्वस्वं भगवत्यर्प्य भजेत् श्रीकृष्णमव्ययम् ॥ ५५ ॥',
    arth:
        'ભગવદ્-સેવા અને ભંડાર (કોઠાર) ના વહિવટમાં પરમ પવિત્રતા, સાવધાની અને નિષ્કામ સેવાભાવ રાખવાથી જ જીવ પ્રભુની દિવ્ય કૃપાનો પાત્ર બને છે.',
    vartaContent:
        '''શ્રી રામદાસજી કોઠારી વૈષ્ણવ સમુદાયના એક પરમ ઉત્તમ અને દિવ્ય ભક્ત હતા. તેઓ શ્રીજીના ભંડાર (કોઠાર) અને સામગ્રીની વ્યવસ્થા સંભાળવામાં અત્યંત નિપુણ, સાવધાન અને ઈમાનદાર હતા. તેઓ સ્વભાવે પરમ સરસ, નમ્ર, વિવેકી અને બાલ્યાવસ્થાથી જ ભગવદ્-ભાવથી સંપન્ન હતા.

જ્યારે શ્રીઆચાર્યજી મહાપ્રભુજી પોતાની ભારત પરિક્રમા દરમિયાન તે ક્ષેત્રમાં પધાર્યા, ત્યારે રામદાસજી તેમના દિવ્ય દર્શનાર્થે આવ્યા. શ્રીમહાપ્રભુજીના દિવ્ય સ્વરૂપના દર્શન કરતાં જ તેમનું મન સંપૂર્ણપણે પ્રભુના ચરણોમાં અર્પિત થઈ ગયું. તેમણે શ્રીઆચાર્યજી મહાપ્રભુજી પાસે શરણાગતિ સ્વીકારીને બ્રહ્મસંબંધ પ્રાપ્ત કર્યો.

શ્રીઆચાર્યજીએ તેમની પવિત્રતા, સાવધાની અને નિષ્ઠા જોઈને તેમને શ્રીજીના ભંડાર (કોઠાર) ની સેવા સોંપી. રામદાસજી કોઠારી નિત્ય અત્યંત પવિત્રતા, શુદ્ધિ અને સાવધાનીપૂર્વક શ્રીજી માટે વપરાતી દરેક સામગ્રીનો હિસાબ અને સંભાળ રાખતા. તેઓ રાત-દિવસ અનન્ય ભાવથી શ્રીજીની સામગ્રી અને વૈષ્ણવોની સેવામાં જ તલ્લીન રહેતા.

એકવાર કોઠારની સામગ્રી અને વ્યવસ્થામાં કોઈ લૌકિક સંકટ કે અછત ઊભી થઈ, પરંતુ રામદાસજીએ સહેજ પણ અધીરા થયા વગર પોતાનો તમામ ભાર શ્રીજી અને શ્રીઆચાર્યજીના ચરણો પર છોડી દીધો. તેમની અનન્ય નિષ્ઠા જોઈને સાક્ષાત શ્રીજીએ ભંડારને અખૂટ બનાવી દીધો અને સર્વ વિઘ્નો દૂર કર્યા. રામદાસજીએ પોતાનું આખું આયુષ્ય શ્રીજીના કોઠારની સેવા, ગુરુભક્તિ અને સત્સંગમાં જ વ્યતીત કર્યું.''',
    saar:
        'ભગવાનની સેવામાં કોઈપણ નાનું કે મોટું કાર્ય નિષ્કામ, ઈમાનદારી અને પવિત્ર ભાવથી કરવામાં આવે, તો સાક્ષાત પ્રભુ તે સેવાનો સ્વીકાર કરીને જીવનું કલ્યાણ કરે છે.',
  ),

  VartaModel(
    id: '57',
    number: '૫૭',
    titleGujarati: 'શ્રી સેઠ પદ્મનાભદાસની વાર્તા',
    titleBraj: 'સેઠ પદ્મનાભદાસ કી વાર્તા',
    shloka: 'सर्वस्वं भगवद् भावैः समर्प्य श्रीगुरुचरो ॥ ५७ ॥',
    arth:
        'પોતાનો વૈભવ, લક્ષ્મી અને મન બધું શ્રીકૃષ્ણ તથા શ્રીગુરુદેવના શરણોમાં સમર્પિત કરીને સદા નિષ્કામ સેવા પરાયણ રહેવું.',
    vartaContent:
        '''શ્રી સેઠ પદ્મનાભદાસજી ગુજરાતના એક અત્યંત પ્રખ્યાત, સમૃદ્ધ અને પરમ ઉદાર વેપારી હતા. તેઓ જ્ઞાતિએ વૈશ્ય/મહાજન હતા અને વ્યાપાર-ધંધામાં તેમની મોટી નામના હતી. અઢળક લક્ષ્મી અને સમૃદ્ધિ હોવા છતાં, તેમનું હૃદય સંસારના વિષય-ભોગોમાં નહોતું ચોંટતું. તેઓ બાલ્યાવસ્થાથી જ સત્ય, દયા અને ભગવદ્-સ્મરણમાં તલ્લીન રહેતા હતા.

જ્યારે શ્રીઆચાર્યજી મહાપ્રભુજી પોતાની ભારત પરિક્રમા દરમિયાન ગુજરાત ક્ષેત્રમાં પધાર્યા, ત્યારે સેઠ પદ્મનાભદાસજી તેમના દર્શનાર્થે આવ્યા. શ્રીમહાપ્રભુજીના દિવ્ય અને અલૌકિક મુખારવિંદના દર્શન કરતાં જ તેમનું મન પ્રભુમય બની ગયું. તેમણે તુરંત શ્રીઆચાર્યજીના ચરણોમાં સાષ્ટાંગ પ્રણામ કર્યા અને શરણાગતિ સ્વીકારીને બ્રહ્મસંબંધ પ્રાપ્ત કર્યો.

બ્રહ્મસંબંધ લીધા બાદ સેઠ પદ્મનાભદાસજીએ પોતાની લક્ષ્મી અને વ્યાપારને સાક્ષાત શ્રીજીની જ સામગ્રી માની. તેમણે પોતાના ઘરમાં શ્રીઆચાર્યજીની આજ્ઞાનુસાર શ્રીજીનું દિવ્ય સ્વરૂપ પધરાવ્યું. તેઓ નિત્ય વહેલી સવારે જાગીને અત્યંત સાવધાની, પવિત્રતા અને દિવ્ય સ્નેહપૂર્વક શ્રીજીની સેવા અર્પિત કરતા. પોતાના વ્યાપારિક કાર્યો સંભાળતી વખતે પણ તેમનું મન સદા પોતાના ઈષ્ટદેવ શ્રીજીના ચરણોમાં જ પરોવાયેલું રહેતું.

એકવાર વ્યાપારમાં મોટી કટોકટી અને સંકટ આવી પડ્યું, પરંતુ પદ્મનાભદાસજીએ સહેજ પણ ચિંતિત થયા વગર પોતાનો તમામ ભાર શ્રીજી અને ગુરુશ્રીમહાપ્રભુજીના ચરણો પર છોડી દીધો. તેમની અવિચળ અને નિષ્કામ ભક્તિ જોઈને સાક્ષાત શ્રીજીએ તેમની અને તેમના વ્યાપારની રક્ષા કરી. સેઠ પદ્મનાભદાસજીએ પોતાનું શેષ આયુષ્ય અનન્ય આશ્રય, ભગવદ્-સેવા અને સત્સંગમાં જ વ્યતીત કર્યું.''',
    saar:
        'ધન, વૈભવ કે વ્યાપાર ક્યારેય ભક્તિમાં બાધક બનતા નથી, જો મનુષ્ય અહંકાર છોડીને પોતાની સંપત્તિ અને મન બંને ભગવાનના ચરણોમાં અર્પિત કરે.',
  ),

  VartaModel(
    id: '58',
    number: '૫૮',
    titleGujarati: 'શ્રી વ્યાસદાસની વાર્તા',
    titleBraj: 'વ્યાસદાસ કી વાર્તા',
    shloka: 'शास्त्रज्ञानं हृदि स्थाप्य भजेत् श्रीवल्लभं प्रभुम् ॥ ५८ ॥',
    arth:
        'શાસ્ત્રો અને વેદોનું જ્ઞાન મેળવ્યા બાદ તેના અહંકારનો ત્યાગ કરી શ્રીવલ્લભ પ્રભુના ચરણારવિંદમાં સદા ભક્તિભાવે લીન રહેવું.',
    vartaContent:
        '''શ્રી વ્યાસદાસજી કાશી (વારાણસી) ના એક અત્યંત પ્રકાંડ વિદ્વાન, શાસ્ત્રજ્ઞ અને પવિત્ર બ્રાહ્મણ હતા. તેઓ વેદ, ઉપનિષદ અને પૌરાણિક સાહિત્યના ઊંડા જ્ઞાની હતા. સંસ્કૃત ભાષા પર તેમનું અસાધારણ પ્રભુત્વ હતું અને તેઓ સદા શાસ્ત્રચર્ચામાં લીન રહેતા. પરંતુ શાસ્ત્રોના અગાધ જ્ઞાન હોવા છતાં તેમના અંતઃકરણમાં ભગવદ્-રસ અને દિવ્ય આંતરિક શાંતિનો અનુભવ થતો નહોતો.

જ્યારે શ્રીઆચાર્યજી મહાપ્રભુજી પોતાની ભારત પરિક્રમા દરમિયાન કાશી પધાર્યા, ત્યારે વ્યાસદાસજી તેમના અલૌકિક અને દિવ્ય દર્શનાર્થે આવ્યા. શ્રીમહાપ્રભુજીના મુખારવિંદમાંથી ઝરતી ભાગવત કથા અને સુબોધિનીજીનો ઉપદેશ સાંભળતાં જ વ્યાસદાસજીનો તમામ વિદ્યા અને પાંડિત્યનો અહંકાર ક્ષણવારમાં ઓગળી ગયો. તેમને સમજાયું કે માત્ર શાબ્દિક જ્ઞાનથી મુક્તિ મળતી નથી, પરંતુ પ્રભુની અનન્ય શરણાગતિ જ પરમ સત્ય છે.

તેમણે તુરંત શ્રીઆચાર્યજી મહાપ્રભુજીના ચરણોમાં સાષ્ટાંગ પ્રણામ કર્યા અને શરણાગતિ સ્વીકારીને બ્રહ્મસંબંધ પ્રાપ્ત કર્યો.

બ્રહ્મસંબંધ લીધા બાદ વ્યાસદાસજીએ પોતાના ઘરમાં શ્રીઆચાર્યજીની આજ્ઞાનુસાર શ્રીજીનું દિવ્ય સ્વરૂપ પધરાવ્યું. તેમણે પોતાના પાંડિત્યના અહંકારનો સંપૂર્ણ ત્યાગ કરીને શ્રીજીની સેવામાં મન પરોવ્યું. તેઓ નિત્ય અત્યંત પવિત્રતા, શુદ્ધિ અને ભાવપૂર્વક શ્રીજીની સેવા અર્પિત કરતા અને પોતાની વાણીનો ઉપયોગ માત્ર પ્રભુની સ્તુતિ અને ભગવદ્-યશ ગાવવામાં જ કરતા. વ્યાસદાસજીએ પોતાનું આખું આયુષ્ય નિષ્કામ ભગવદ્-સેવા અને ગુરુચરણોના દ્રઢ આશ્રયમાં જ વિતાવ્યું.''',
    saar:
        'વિદ્યા કે શાસ્ત્રનું જ્ઞાન મનુષ્યને ત્યારે જ સાર્થક બને છે જ્યારે તે તેનાથી અહંકારી બનવાને બદલે નમ્ર બનીને શ્રીહરિના ચરણોમાં શરણાગતિ સ્વીકારે છે.',
  ),

  VartaModel(
    id: '59',
    number: '૫૯',
    titleGujarati: 'શ્રી પુરુષોત્તમ જોશીની વાર્તા',
    titleBraj: 'પુરુષોત્તમ જોશી કી વાર્તા',
    shloka: 'सर्वं भगवदर्थाय कुर्याद् भक्तिपरायणः ॥ ५९ ॥',
    arth:
        'ભક્તિમાર્ગમાં પરોવાયેલા વૈષ્ણવે પોતાના સર્વ કાર્યો, વિદ્યા અને બુદ્ધિનો ઉપયોગ કેવળ ભગવાન શ્રીકૃષ્ણની પ્રસન્નતા અને સેવા માટે જ કરવો.',
    vartaContent:
        '''શ્રી પુરુષોત્તમ જોશીજી કાશીના એક અત્યંત પ્રકાંડ વિદ્વાન, જ્યોતિષાચાર્ય અને ઉત્કૃષ્ટ બ્રાહ્મણ હતા. તેઓ શાસ્ત્ર, નક્ષત્ર વિજ્ઞાન અને કાળ ગણનાના અસાધારણ જ્ઞાની હતા. તેઓ સમાજમાં ખુબ સન્માનનીય હતા, પરંતુ જ્ઞાન અને વિદ્વત્તાનો અહંકાર હોવાને કારણે તેમના હૃદયમાં વાસ્તવિક શાંતિ અને ભક્તિરસનો અનુભવ થતો નહોતો.

જ્યારે શ્રીઆચાર્યજી મહાપ્રભુજી પોતાની ભારત પરિક્રમા દરમિયાન તે ક્ષેત્રમાં પધાર્યા, ત્યારે પુરુષોત્તમ જોશીજી પણ અન્ય વિદ્વાનો સાથે શ્રીમહાપ્રભુજીના દિવ્ય દર્શને આવ્યા. શ્રીમહાપ્રભુજીના અલૌકિક સ્વરૂપ અને તેમના મુખારવિંદમાંથી ઝરતી ભાગવતજીની સુબોધિની કથા સાંભળીને જોશીજીનો તમામ પાંડિત્યનો અહંકાર ઓગળી ગયો. તેમને સમજાયું કે ભગવાનની ભક્તિ અને અનન્ય શરણાગતિ વિના સંસારના તમામ જ્ઞાન અપૂર્ણ છે.

તેમણે તુરંત શ્રીઆચાર્યજી મહાપ્રભુજીના ચરણોમાં સાષ્ટાંગ પ્રણામ કર્યા અને શરણાગતિ સ્વીકારીને બ્રહ્મસંબંધ પ્રાપ્ત કર્યો.

બ્રહ્મસંબંધ લીધા બાદ પુરુષોત્તમ જોશીજીએ પોતાના ઘરમાં શ્રીઆચાર્યજીની આજ્ઞાનુસાર શ્રીજીનું દિવ્ય સ્વરૂપ પધરાવ્યું. તેમણે પોતાના જ્યોતિષ અને વિદ્યાના લૌકિક અહંકારનો સંપૂર્ણ ત્યાગ કર્યો. તેઓ નિત્ય વહેલા જાગીને અત્યંત પવિત્રતા, શુદ્ધિ અને પ્રેમપૂર્વક શ્રીજીની સેવા અર્પિત કરતા. પોતાની વિદ્યાનો ઉપયોગ તેમણે કેવળ ઉત્સવો અને પ્રભુસેવાના શુભ મુહૂર્તો સમજવા પૂરતો જ રાખ્યો. પુરુષોત્તમ જોશીજીએ પોતાનું આખું આયુષ્ય શ્રીજીની અનન્ય સેવા અને ગુરુચરણોના દ્રઢ આશ્રયમાં જ વિતાવ્યું.''',
    saar:
        'માનવનું કલ્યાણ પોતાની વિદ્યા કે બુદ્ધિના અહંકારમાં નથી, પરંતુ જ્યારે તે વિદ્યાનો ઉપયોગ હરિસેવા અને ગુરુચરણોમાં સમર્પિત થવા માટે કરે છે, ત્યારે જ તેનું આત્મકલ્યાણ થાય છે.',
  ),

  VartaModel(
    id: '60',
    number: '૬૦',
    titleGujarati: 'શ્રી ગોવિંદદાસ ક્ષત્રિયની વાર્તા',
    titleBraj: 'ગોવિંદદાસ ક્ષત્રિય કી વાર્તા',
    shloka: 'क्षत्रियधर्मे स्थितोऽपी भक्तिमार्गे दृढो भवेत् ॥ ६० ॥',
    arth:
        'પોતાના પદ, ક્ષાત્રધર્મ કે લૌકિક કર્તવ્યોનું પાલન કરવાની સાથે ભક્તિમાર્ગમાં સાચો અને અનન્ય દ્રઢ આશ્રય જાળવવો.',
    vartaContent:
        '''શ્રી ગોવિંદદાસ ક્ષત્રિયજી એક ઉત્કૃષ્ટ ક્ષાત્ર કુળના વીર અને દયાવાન ભક્ત હતા. તેઓ રાજવી સેનામાં મહત્વનું પદ સંભાળતા હતા અને શૂરવીરતા માટે જાણીતા હતા. પરંતું ક્ષાત્ર તેજ અને કઠોર લૌકિક જવાબદારીઓ વચ્ચે પણ તેમના અંતરમાં બાલ્યાવસ્થાથી જ ભગવાન શ્રીકૃષ્ણની ભક્તિ અને ગુરુભક્તિના સંસ્કાર ઊંડા ઉતરેલા હતા.

જ્યારે શ્રીઆચાર્યજી મહાપ્રભુજી પોતાની ભારત પરિક્રમા દરમિયાન તે ક્ષેત્રમાં પધાર્યા, ત્યારે ગોવિંદદાસ ક્ષત્રિયજી તેમના અલૌકિક દર્શને આવ્યા. શ્રીમહાપ્રભુજીના દિવ્ય મુખારવિંદના દર્શન અને વચનામૃત સાંભળતાં જ તેમનું અંતઃકરણ પૂર્ણપણે ભક્તિરસથી ભરાઈ ગયું. તેમણે તુરંત શ્રીઆચાર્યજીના ચરણોમાં સાષ્ટાંગ પ્રણામ કર્યા અને શરણાગતિ સ્વીકારીને બ્રહ્મસંબંધ પ્રાપ્ત કર્યો.

બ્રહ્મસંબંધ લીધા બાદ ગોવિંદદાસજીએ પોતાના ઘરમાં શ્રીઆચાર્યજીની આજ્ઞાનુસાર શ્રીજીનું દિવ્ય સ્વરૂપ પધરાવ્યું. તેઓ પોતાની ક્ષાત્ર ફરજો પતાવ્યા પછી અત્યંત શુદ્ધિ, સાવધાની અને સ્નેહભાવે શ્રીજીની સેવા અર્પિત કરતા. પોતાના વીરતા કે સત્તાનો કોઈ પણ અહંકાર રાખ્યા વગર તેઓ સાધુભાવથી નિત્ય ભગવદ્-સ્મરણ કરતા.

એકવાર તેમના રાજ્ય પર અને યુદ્ધના પ્રસંગે વિષમ સ્થિતિ ઊભી થઈ, પરંતુ ગોવિંદદાસજીએ સહેજ પણ ચિંતિત થયા વગર અનન્ય આશ્રય રાખીને તમામ ભાર શ્રીજી અને શ્રીઆચાર્યજીના ચરણો પર છોડી દીધો. તેમની દ્રઢ નિષ્ઠા જોઈને શ્રીજીએ સાક્ષાત તેમની અને તેમના વિજયની રક્ષા કરી. ગોવિંદદાસ ક્ષત્રિયજીએ પોતાનું શેષ આયુષ્ય નિષ્કામ ભગવદ્-સેવા અને ગુરુચરણોના અવિચળ આશ્રયમાં જ વિતાવ્યું.''',
    saar:
        'માનવ ગમે તેવા કઠોર ધંધા કે હોદ્દા પર હોય, પરંતુ જો તેના અંતરમાં ભગવાન અને ગુરુ પ્રત્યે સાચો આશ્રય હોય, તો સાક્ષાત પ્રભુ સદા તેની રક્ષા કરે છે.',
  ),

  VartaModel(
