    shloka: 'साधुभावेन संतप्तं हृदयं यस्य सुस्थिरम् ॥ ६१ ॥',
    arth:
        'જેનું હૃદય સાધુતા, નમ્રતા અને અહંકારહીન ભાવથી શોભે છે, તે જીવ પર શ્રીહરિની સદા અખંડ કૃપા રહે છે.',
    vartaContent:
        '''શ્રી રામદાસજી સાધોરા ક્ષેત્રના નિવાસી એક અત્યંત પરમ પવિત્ર, નમ્ર અને સાધુસ્વભાવ ધરાવતા વૈષ્ણવ હતા. તેઓ સ્વભાવે અતિ મૃદુ, દયાવાન, વિવેકી અને બાલ્યાવસ્થાથી જ સંસારના લૌકિક રાગ-દ્વેષથી પર રહીને પ્રભુસ્મરણમાં દ્રઢ રહેનારા આત્મા હતા.

જ્યારે શ્રીઆચાર્યજી મહાપ્રભુજી પોતાની ભારત પરિક્રમા દરમિયાન તે ક્ષેત્રમાં પધાર્યા, ત્યારે રામદાસજી તેમના દિવ્ય દર્શનાર્થે આવ્યા. શ્રીમહાપ્રભુજીના અલૌકિક સ્વરૂપ અને તેમના મુખારવિંદમાંથી ઝરતી ભાગવતજીની સુબોધિની કથા સાંભળીને રામદાસજીનું મન સંપૂર્ણપણે શ્રીકૃષ્ણ ચરણોમાં અર્પિત થઈ ગયું. તેમણે તુરંત શ્રીઆચાર્યજીના ચરણોમાં સાષ્ટાંગ પ્રણામ કર્યા અને શરણાગતિ સ્વીકારીને બ્રહ્મસંબંધ પ્રાપ્ત કર્યો.

બ્રહ્મસંબંધ લીધા બાદ શ્રી રામદાસજીએ પોતાના ઘરમાં શ્રીઆચાર્યજીની આજ્ઞાનુસાર શ્રીજીનું દિવ્ય સ્વરૂપ પધરાવ્યું. તેઓ નિત્ય વહેલા જાગીને અત્યંત સાવધાની, શુદ્ધિ અને સ્નેહપૂર્વક શ્રીજીની સેવા અર્પિત કરતા. પોતાની લૌકિક ક્રિયાઓ સંભાળતી વખતે પણ તેમનું અંતઃકરણ સદા પોતાના ઈષ્ટદેવ શ્રીજી અને શ્રીઆચાર્યજીના ચરણારવિંદના ધ્યાનમાં જ લીન રહેતું.

એકવાર તેમના જીવનમાં કઠિન લૌકિક વિઘ્નો અને પરિસ્થિતિઓ આવી પડી, પરંતુ રામદાસજીએ સહેજ પણ ચિંતિત થયા વિના અનન્ય આશ્રય રાખીને તમામ ભાર શ્રીજી અને ગુરુશ્રીમહાપ્રભુજીના ચરણો પર છોડી દીધો. તેમની અનન્ય અને દ્રઢ ભક્તિ જોઈને સાક્ષાત શ્રીજીએ તેમની રક્ષા કરી. રામદાસજીએ પોતાનું શેષ આયુષ્ય અનન્ય સેવા, ગુરુભક્તિ અને સત્સંગમાં જ વ્યતીત કર્યું.''',
    saar:
        'માનવનું સાચું ભૂષણ તેની નમ્રતા અને સાધુતા છે. જ્યારે જીવ અહંકાર છોડીને દ્રઢ ભાવે ભગવાનના શરણમાં રહે છે, ત્યારે પ્રભુ પોતે તેનું રક્ષણ કરે છે.',
  ),

