    shloka: 'ज्योतिषज्ञानं परित्यज्य भजेत् श्रीवल्लभं प्रभुम् ॥ ६२ ॥',
    arth:
        'પોતાના જ્યોતિષ વિદ્યા કે શાસ્ત્ર જ્ઞાનના અહંકારનો ત્યાગ કરીને શ્રીવલ્લભ પ્રભુના દિવ્ય ચરણારવિંદનો જ અનન્ય આશ્રય સ્વીકારવો.',
    vartaContent:
        '''શ્રી નરહર્યો જોશીજી કાશીના એક અત્યંત પ્રકાંડ શાસ્ત્રજ્ઞ અને પ્રખ્યાત જ્યોતિષાચાર્ય હતા. તેઓ નક્ષત્ર ગણના અને ભવિષ્ય કથનમાં અત્યંત કુશળ હતા, જેના કારણે સમાજમાં તેમનું મોટું સન્માન હતું. પરંતુ જ્યોતિષ વિદ્યાના અગાધ જ્ઞાન હોવા છતાં તેમના અંતઃકરણમાં આંતરિક શાંતિ અને દિવ્ય ભક્તિરસનો અભાવ હતો.

જ્યારે શ્રીઆચાર્યજી મહાપ્રભુજી પોતાની ભારત પરિક્રમા દરમિયાન તે ક્ષેત્રમાં પધાર્યા, ત્યારે નરહર્યો જોશીજી શ્રીમહાપ્રભુજીના અલૌકિક દિવ્ય દર્શને આવ્યા. શ્રીમહાપ્રભુજીના મુખારવિંદમાંથી ઝરતી ભાગવતજીની સુબોધિની કથા અને ઉપદેશ સાંભળીને જોશીજીનો વિદ્યા અને જ્યોતિષનો અહંકાર ગળી ગયો. તેમને સમજાયું કે પ્રારબ્ધ અને કાળ ચક્રથી પર તો કેવળ સાક્ષાત પરબ્રહ્મ શ્રીકૃષ્ણ જ છે.

તેમણે તુરંત શ્રીઆચાર્યજી મહાપ્રભુજીના ચરણોમાં સાષ્ટાંગ પ્રણામ કર્યા અને શરણાગતિ સ્વીકારીને બ્રહ્મસંબંધ પ્રાપ્ત કર્યો.

બ્રહ્મસંબંધ લીધા બાદ નરહર્યો જોશીજીએ પોતાના ઘરમાં શ્રીઆચાર્યજીની આજ્ઞાનુસાર શ્રીજીનું દિવ્ય સ્વરૂપ પધરાવ્યું. તેમણે પોતાની વિદ્યા પર આધાર રાખવાને બદલે સદા શ્રીજીના ચરણોનો અનન્ય આશ્રય રાખ્યો. તેઓ નિત્ય અત્યંત પવિત્રતા, સાવધાની અને સ્નેહભાવે શ્રીજીની સેવા અર્પિત કરતા. નરહર્યો જોશીજીએ પોતાનું શેષ આયુષ્ય નિષ્કામ ભગવદ્-સેવા અને ગુરુચરણોમાં જ સમર્પિત કર્યું.''',
    saar:
        'માનવનું સાચું કલ્યાણ ગ્રહો કે જ્યોતિષની ગણતરીઓમાં નથી, પરંતુ સાક્ષાત પ્રભુ અને ગુરુદેવના શરણાગત થઈને અનન્ય ભક્તિ કરવાથી જ સઘળા મનોરથ પૂર્ણ થાય છે.',
  ),

  VartaModel(
    id: '63',
    number: '૬૩',
    titleGujarati: 'શ્રી રાજા પૃથ્વીરાજની વાર્તા',
    titleBraj: 'રાજા પૃથ્વીરાજ કી વાર્તા',
    shloka: 'राजसत्तां परित्यज्य भजेत् श्रीवल्लभं प्रभुम् ॥ ६३ ॥',
    arth:
        'રાજસત્તા અને વૈભવના અહંકારનો ત્યાગ કરીને શ્રીવલ્લભ પ્રભુના દિવ્ય ચરણારવિંદનો જ અવિચળ આશ્રય સ્વીકારવો.',
    vartaContent:
        '''શ્રી રાજા પૃથ્વીરાજજી (બીકાનેરના રાઠોડ રાજપૂત રાજા પૃથ્વીરાજજી) ક્ષત્રિય કુળના એક અત્યંત શૂરવીર, પ્રતાપી અને વિદ્વાન રાજા હતા. તેઓ એક સમર્થ કવિ અને ક્ષાત્ર તેજથી સંપન્ન મહાન શાસક હતા. રાજ્યવૈભવ, સેના અને સત્તા હોવા છતાં, પૂર્વજન્મના મહાન સંસ્કારોને કારણે તેમનું હૃદય સંસારના વિષય-ભોગો કે રાજ્યના અહંકારમાં અટવાવાને બદલે સદા શ્રીકૃષ્ણ ભક્તિ અને દિવ્ય રસની શોધમાં રહેતું હતું.

જ્યારે શ્રીઆચાર્યજી મહાપ્રભુજી પોતાની ભારત પરિક્રમા દરમિયાન તે ક્ષેત્રમાં પધાર્યા, ત્યારે રાજા પૃથ્વીરાજજી પોતાના રાજવી પરિવાર સાથે શ્રીમહાપ્રભુજીના દિવ્ય દર્શનાર્થે આવ્યા. શ્રીઆચાર્યજીના તેજોમય દિવ્ય સ્વરૂપના દર્શન કરતાં જ રાજા પૃથ્વીરાજજીનો તમામ રાજવી સત્તાનો અહંકાર ઓગળી ગયો. શ્રીમહાપ્રભુજીના મુખારવિંદના વચનામૃત સાંભળીને તેમણે શરણાગતિ સ્વીકારી અને બ્રહ્મસંબંધ પ્રાપ્ત કર્યો.

બ્રહ્મસંબંધ લીધા બાદ રાજા પૃથ્વીરાજજીએ પોતાના રાજ્ય અને રાજવૈભવને સાક્ષાત શ્રીજીની જ સામગ્રી માનીને અત્યંત દાસભાવે વર્તવાનું શરૂ કર્યું. તેમણે પોતાના ઘરમાં શ્રીઆચાર્યજીની આજ્ઞાનુસાર શ્રીજીનું દિવ્ય સ્વરૂપ પધરાવ્યું. તેઓ રાજકાજના કાર્યો પતાવ્યા બાદ અત્યંત પવિત્રતા, સાવધાની અને સ્નેહભાવે શ્રીજીની સેવા અર્પિત કરતા અને ભગવદ્-રસથી સભર કાવ્યો તથા પદોની રચના કરતા.

જ્યારે પણ તેમના રાજ્ય પર લૌકિક કે યુદ્ધના પ્રસંગો આવ્યા, ત્યારે તેમણે પોતાની શક્તિ પર ગર્વ કરવાને બદલે સદા શ્રીજી અને શ્રીઆચાર્યજીના ચરણોનો અનન્ય આશ્રય રાખ્યો. શ્રીજીએ સાક્ષાત તેમની અને તેમના રાજ્યની રક્ષા કરી. રાજા પૃથ્વીરાજજીએ પોતાનું આખું આયુષ્ય એક ઉત્તમ વૈષ્ણવ તરીકે ભગવદ્-સેવા, કાવ્ય-રચના અને અનન્ય આશ્રયમાં જ વ્યતીત કર્યું.''',
    saar:
        'રાજપદ, સત્તા કે કવિતાનું જ્ઞાન મનુષ્યને ત્યારે જ શોભે છે જ્યારે તે અહંકાર મુક્ત થઈને પોતાનું સર્વસ્વ ભગવાન અને ગુરુદેવના ચરણોમાં સમર્પિત કરે છે.',
  ),

