    arth:
        'પોતાના ક્ષાત્રધર્મ, કૌટુંબિક અને લૌકિક કર્તવ્યો અદા કરવાની સાથે શ્રીવલ્લભ પ્રભુના ચરણારવિંદમાં સદા અવિચળ અને અનન્ય ભક્તિભાવ રાખવો.',
    vartaContent:
        '''શ્રી રામદાસજી ચૌહાણ ક્ષત્રિય ચૌહાણ વંશના એક અત્યંત પ્રતાપી, સાહસિક અને સ્વમાની વીર પુરુષ હતા. તેઓ પોતાની સેના અને વિસ્તારમાં ખુબ સન્માનનીય હતા. ક્ષાત્ર ગુણો જેવા કે પરાક્રમ, દયા અને શૂરવીરતા તેમનામાં ભરેલા હતા, પરંતુ પૂર્વજન્મના સંસ્કારોને લીધે તેમનું હૃદય સંસારના વિષય-ભોગોમાં લીન ન થતાં નિત્ય ભગવદ્-સ્મરણ અને આત્મકલ્યાણની શોધમાં રહેતું હતું.

જ્યારે શ્રીઆચાર્યજી મહાપ્રભુજી પોતાની ભારત પરિક્રમા દરમિયાન તે ક્ષેત્રમાં પધાર્યા, ત્યારે રામદાસજી ચૌહાણ તેમના અલૌકિક અને તેજોમય દિવ્ય દર્શનાર્થે આવ્યા. શ્રીમહાપ્રભુજીના મુખારવિંદના દર્શન અને ભાગવતજીની અમૃતમય વાણી સાંભળતાં જ તેમનો તમામ ક્ષાત્ર મોહ અને અહંકાર દૂર થઈ ગયો. તેમણે તુરંત શ્રીઆચાર્યજી મહાપ્રભુજીના ચરણોમાં સાષ્ટાંગ પ્રણામ કર્યા અને શરણાગતિ સ્વીકારીને બ્રહ્મસંબંધ પ્રાપ્ત કર્યો.

બ્રહ્મસંબંધ લીધા બાદ શ્રી રામદાસજી ચૌહાણે પોતાના ઘરમાં શ્રીઆચાર્યજીની આજ્ઞાનુસાર શ્રીજીનું દિવ્ય સ્વરૂપ પધરાવ્યું. તેઓ પોતાની લૌકિક ફરજો પતાવ્યા પછી અત્યંત શુદ્ધિ, સાવધાની અને સ્નેહભાવે શ્રીજીની સેવા અર્પિત કરતા. જ્યારે પણ તેમના પર કે રાજ્ય પર કોઈ લૌકિક કે સૈન્ય સંકટ આવતું, ત્યારે પોતાની શક્તિ પર ગર્વ કરવાને બદલે સદા શ્રીજી અને ગુરુદેવના ચરણોનો અનન્ય આશ્રય રાખતા. શ્રીજીએ સાક્ષાત તેમની રક્ષા કરી. રામદાસજી ચૌહાણે પોતાનું શેષ આયુષ્ય નિષ્કામ સેવા, ગુરુભક્તિ અને સત્સંગમાં જ વ્યતીત કર્યું.''',
    saar:
        'માનવનું શૂરવીરતા અને પરાક્રમ ત્યારે જ સાર્થક બને છે જ્યારે તે તેનો ઉપયોગ પ્રભુસેવા અને ધર્મરક્ષા માટે કરે છે તથા સદા હરિચરણોમાં નમ્ર રહે છે.',
  ),

