    shloka: 'सर्वस्वं भगवत्यर्प्य भजेत् श्रीवल्लभं प्रभुम् ॥ ६५ ॥',
    arth:
        'સંસારના સર્વ લૌકિક પદ-પ્રતિષ્ઠા કે વૈભવનો મોહ છોડીને શ્રીવલ્લભ પ્રભુના ચરણારવિંદમાં સદા અનન્ય અને નિષ્કામ ભાવે સમર્પિત રહેવું.',
    vartaContent:
        '''શ્રી દામોદરદાસજી સંભલ ઉત્તર પ્રદેશના સંભલ ક્ષેત્રના એક અત્યંત ઉત્તમ, વિવેકી અને પવિત્ર આત્મા હતા. તેઓ સ્વભાવે પરમ સરસ, દયાવાન, નમ્ર અને બાલ્યાવસ્થાથી જ ભગવદ્-સ્મરણમાં રમમાણ રહેનારા દિવ્ય ભક્ત હતા. લૌકિક વ્યવહારોમાં અત્યંત પ્રવીણ હોવા છતાં તેમના અંતરમાં સદા શ્રીજીની સેવા અને ગુરુચરણની પ્રાપ્તિ માટેની તીવ્ર ઝંખના રહેતી હતી.

જ્યારે શ્રીઆચાર્યજી મહાપ્રભુજી પોતાની ભારત પરિક્રમા દરમિયાન તે ક્ષેત્રમાં પધાર્યા, ત્યારે દામોદરદાસજી તેમના અલૌકિક દિવ્ય દર્શનાર્થે આવ્યા. શ્રીમહાપ્રભુજીના દિવ્ય તેજોમય સ્વરૂપ અને તેમના મુખારવિંદમાંથી ઝરતા કથામૃત સાંભળતાં જ દામોદરદાસજીનું મન સંપૂર્ણપણે કૃષ્ણમય બની ગયું. તેમણે તુરંત શ્રીઆચાર્યજીના ચરણોમાં સાષ્ટાંગ પ્રણામ કર્યા અને શરણાગતિ સ્વીકારીને બ્રહ્મસંબંધ પ્રાપ્ત કર્યો.

બ્રહ્મસંબંધ લીધા બાદ દામોદરદાસજીએ પોતાના ઘરમાં શ્રીઆચાર્યજીની આજ્ઞાનુસાર શ્રીજીનું દિવ્ય સ્વરૂપ પધરાવ્યું. તેઓ નિત્ય વહેલા જાગીને અત્યંત પવિત્રતા, શુદ્ધિ, સાવધાની અને સ્નેહપૂર્વક શ્રીજીની સેવા અર્પિત કરતા. પોતાના લૌકિક કામકાજ પતાવતી વખતે પણ તેમનું અંતઃકરણ સદા પોતાના ઈષ્ટદેવ શ્રીજી અને શ્રીઆચાર્યજીના ચરણારવિંદના ધ્યાનમાં જ તલ્લીન રહેતું.

એકવાર તેમના જીવનમાં કઠિન લૌકિક વિઘ્નો અને પરિસ્થિતિઓ ઊભી થઈ, પરંતુ દામોદરદાસજીએ સહેજ પણ ચિંતિત થયા વગર દ્રઢ નિષ્ઠા રાખીને તમામ ભાર શ્રીજી અને ગુરુદેવના ચરણો પર છોડી દીધો. તેમની અનન્ય ભક્તિ જોઈને સાક્ષાત શ્રીજીએ તેમની રક્ષા કરી. દામોદરદાસજીએ પોતાનું આખું આયુષ્ય શ્રીજીની સેવા, ગુરુભક્તિ અને સાધુ-વૈષ્ણવોના સત્સંગમાં જ વિતાવ્યું.''',
    saar:
        'સંસારના રાગ-દ્વેષ કે લૌકિક વિઘ્નો વચ્ચે પણ જે જીવ ગુરુ અને ભગવાન પર અવિચળ ભરોસો રાખે છે, તેને સાક્ષાત પ્રભુ સદા પોતાની છત્રછાયામાં રાખે છે.',
  ),

  VartaModel(
    id: '66',
    number: '૬૬',
    titleGujarati: 'શ્રી પુરુષોત્તમદાસ જોશીની વાર્તા (બીજી)',
    titleBraj: 'પુરુષોત્તમદાસ જોશી કી વાર્તા (દૂસરી)',
    shloka: 'विद्यामदं परित्यज्य भजेत् श्रीवल्लभं प्रभुम् ॥ ६६ ॥',
    arth:
        'પોતાની વિદ્યા, જ્ઞાન કે પાંડિત્યના અહંકારનો સંપૂર્ણ ત્યાગ કરીને શ્રીવલ્લભ પ્રભુના ચરણારવિંદનો જ દ્રઢ આશ્રય સ્વીકારવો.',
    vartaContent:
        '''શ્રી પુરુષોત્તમદાસ જોશીજી કાશી ક્ષેત્રના એક અત્યંત પ્રકાંડ શાસ્ત્રજ્ઞ અને પ્રખ્યાત વિદ્વાન બ્રાહ્મણ હતા. તેઓ શાસ્ત્રો, વેદો તથા પૌરાણિક ગ્રંથોના ઊંડા ગૂઢાર્થ જાણનારા હતા. પોતાની ચતુરતા અને શાસ્ત્રાર્થ કૌશલ્યને કારણે સમાજમાં તેમનો મોટો પ્રભાવ હતો. પરંતુ અગાધ વિદ્યા હોવા છતાં તેમના હૃદયમાં ભક્તિરસ અને આંતરિક શાંતિનો અભાવ હતો.

જ્યારે શ્રીઆચાર્યજી મહાપ્રભુજી પોતાની ભારત પરિક્રમા દરમિયાન કાશી પધાર્યા, ત્યારે પુરુષોત્તમદાસ જોશીજી શ્રીમહાપ્રભુજીના અલૌકિક દિવ્ય દર્શને આવ્યા. શ્રીમહાપ્રભુજીના મુખારવિંદમાંથી ઝરતી ભાગવતજીની સુબોધિની કથા અને ઉપદેશ સાંભળીને જોશીજીનો વિદ્યાનો તમામ અહંકાર ક્ષણવારમાં ઓગળી ગયો. તેમને ભાન થયું કે કેવળ શુષ્ક જ્ઞાનથી ઈશ્વરપ્રાપ્તિ થતી નથી, પરંતુ ગુરુકૃપા અને નિષ્કામ ભક્તિ જ પરમ સાધન છે.

તેમણે તુરંત શ્રીઆચાર્યજી મહાપ્રભુજીના ચરણોમાં સાષ્ટાંગ પ્રણામ કર્યા અને શરણાગતિ સ્વીકારીને બ્રહ્મસંબંધ પ્રાપ્ત કર્યો.

બ્રહ્મસંબંધ લીધા બાદ પુરુષોત્તમદાસ જોશીજીએ પોતાના ઘરમાં શ્રીઆચાર્યજીની આજ્ઞાનુસાર શ્રીજીનું દિવ્ય સ્વરૂપ પધરાવ્યું. તેમણે પાંડિત્યનો અહંકાર છોડીને અત્યંત નમ્ર ભાવે શ્રીજીની સેવા સંભાળી. તેઓ નિત્ય વહેલા જાગીને પરમ શુદ્ધિ, સાવધાની અને પ્રેમથી શ્રીજીની સેવા અર્પિત કરતા. પુરુષોત્તમદાસ જોશીજીએ પોતાનું શેષ આયુષ્ય નિષ્કામ ભગવદ્-સેવા, ગુરુભક્તિ અને સાધુ-વૈષ્ણવોના સત્સંગમાં જ વ્યતીત કર્યું.''',
    saar:
        'વિદ્યા કે જ્ઞાન મનુષ્યને ત્યારે જ શોભે છે જ્યારે તે તેનાથી અહંકારી બનવાને બદલે નમ્ર બનીને શ્રીજી અને ગુરુના શરણમાં પોતાની જાત સમર્પિત કરે છે.',
  ),

  VartaModel(
    id: '67',
    number: '૬૭',
    titleGujarati: 'શ્રી ગોવિંદદાસ ભંડારીની વાર્તા',
    titleBraj: 'ગોવિંદદાસ ભંડારી કી વાર્તા',
    shloka: 'सर्वस्वं भगवद्-भण्डारे निक्षिप्य भजेत् प्रभुम् ॥ ६७ ॥',
    arth:
        'શ્રીજીના ભંડાર અને સામગ્રીની સેવામાં સંપૂર્ણ પવિત્રતા, સાવધાની અને નિષ્કામ ભાવ રાખીને શ્રીજી ચરણોનું નિત્ય સ્મરણ કરવું.',
    vartaContent:
        '''શ્રી ગોવિંદદાસ ભંડારીજી શ્રી મહાપ્રભુજીના એક અત્યંત પ્રિય, વિશ્વાસપાત્ર અને પવિત્ર આત્મા હતા. તેઓ સ્વભાવે અત્યંત સરસ, નમ્ર, ઈમાનદાર અને સાવધાન હતા. શ્રીજીના ભંડાર (સામગ્રી અને વહિવટ) ની સેવા સંભાળવામાં તેમની નિપુણતા અને પવિત્રતા અદભુત હતી.

જ્યારે શ્રીઆચાર્યજી મહાપ્રભુજી પોતાની ભારત પરિક્રમા દરમિયાન તે ક્ષેત્રમાં પધાર્યા, ત્યારે ગોવિંદદાસજી તેમના દિવ્ય દર્શનાર્થે આવ્યા. શ્રીમહાપ્રભુજીના તેજોમય સ્વરૂપ અને દિવ્ય વચનામૃત સાંભળીને તેમનું અંતઃકરણ પૂર્ણપણે ભગવદ્-ભાવથી ભરાઈ ગયું. તેમણે શ્રીઆચાર્યજી મહાપ્રભુજીના ચરણોમાં સાષ્ટાંગ પ્રણામ કર્યા અને શરણાગતિ સ્વીકારીને બ્રહ્મસંબંધ પ્રાપ્ત કર્યો.

શ્રીઆચાર્યજીએ તેમની નિષ્ઠા, સાવધાની અને ઈમાનદારી જોઈને તેમને શ્રીજીના ભંડાર (કોઠાર) ની સેવા સોંપી. ગોવિંદદાસ ભંડારીજી નિત્ય અત્યંત શુદ્ધિ અને સાવધાનીપૂર્વક સામગ્રીની વ્યવસ્થા કરતા. તેઓ ક્યારેય પોતાના માટે કે પોતાના સ્વાર્થ માટે ભંડારમાંથી કશું જ વાપરતા નહીં, પરંતુ સર્વસ્વ શ્રીજી અને વૈષ્ણવોની સેવામાં જ અર્પિત માનતા.

એકવાર ભંડારની સામગ્રીમાં વિઘ્ન અને કટોકટી ઊભી થઈ, પરંતુ ગોવિંદદાસજીએ સહેજ પણ ડગ્યા વગર અનન્ય આશ્રય રાખીને તમામ ભાર શ્રીજી અને ગુરુદેવના ચરણો પર છોડી દીધો. તેમની અચળ ભક્તિ જોઈને સાક્ષાત શ્રીજીએ ભંડારને અખૂટ બનાવી દીધો. ગોવિંદદાસ ભંડારીજીએ પોતાનું શેષ આયુષ્ય શ્રીજીની નિષ્કામ સેવા, ગુરુભક્તિ અને વૈષ્ણવ-સેવામાં જ વ્યતીત કર્યું.''',
    saar:
        'ભગવાનની સેવામાં પ્રાપ્ત થયેલી જવાબદારી કે સેવાનો ઉપયોગ ક્યારેય સ્વાર્થ માટે ન કરવો જોઈએ. ઈમાનદારી અને પવિત્રતાથી કરેલી સેવા જ પ્રભુકૃપાનો માર્ગ ખોલે છે.',
  ),

