    shloka: 'राजकार्ये स्थितोऽपि भजेत् श्रीवल्लभं प्रभुम् ॥ ६८ ॥',
    arth:
        'રાજકાજ અને સંસારના મોટા હોદ્દા કે વ્યવહારો સંભાળતી વખતે પણ અહંકાર મુક્ત થઈને શ્રીવલ્લભ પ્રભુના ચરણોમાં સદા દ્રઢ આશ્રય અને નિષ્કામ સેવાભાવ રાખવો.',
    vartaContent:
        '''શ્રી રામદાસજી મહેતા એક અત્યંત ચતુર, વિવેકી, રાજકીય કાર્યોમાં કુશળ અને ઉચ્ચ હોદ્દો ધરાવતા પ્રખ્યાત મહેતા (દિવાન/પ્રધાન) હતા. તેઓ રાજ્યના આર્થિક અને વ્યાવહારિક સંચાલનમાં અત્યંત પ્રવીણ હતા, જેના કારણે રાજા અને પ્રજા બંનેમાં તેમનો મોટો પ્રભાવ હતો. પરંતુ સત્તા અને મોહમય રાજકીય વાતાવરણ વચ્ચે પણ તેમના અંતરમાં બાલ્યાવસ્થાથી જ ભગવદ્-સ્મરણ અને દિવ્ય શાંતિની ઝંખના રહેતી હતી.

જ્યારે શ્રીઆચાર્યજી મહાપ્રભુજી પોતાની ભારત પરિક્રમા દરમિયાન તે ક્ષેત્રમાં પધાર્યા, ત્યારે રામદાસજી મહેતા શ્રીમહાપ્રભુજીના અલૌકિક દર્શનાર્થે આવ્યા. શ્રીમહાપ્રભુજીના દિવ્ય તેજોમય સ્વરૂપ અને તેમના મુખારવિંદમાંથી ઝરતા કથામૃત સાંભળીને રામદાસજીનો તમામ લૌકિક પદ અને સત્તાનો અહંકાર ક્ષણવારમાં દૂર થઈ ગયો. તેમણે તુરંત શ્રીઆચાર્યજી મહાપ્રભુજીના ચરણોમાં સાષ્ટાંગ પ્રણામ કર્યા અને શરણાગતિ સ્વીકારીને બ્રહ્મસંબંધ પ્રાપ્ત કર્યો.

બ્રહ્મસંબંધ લીધા બાદ રામદાસજી મહેતાએ પોતાના ઘરમાં શ્રીઆચાર્યજીની આજ્ઞાનુસાર શ્રીજીનું દિવ્ય સ્વરૂપ પધરાવ્યું. તેઓ રાજ્યના તમામ મહત્વના કાર્યો પૂરા કર્યા બાદ અત્યંત પવિત્રતા, સાવધાની અને દાસભાવે શ્રીજીની સેવા અર્પિત કરતા. પોતાના પદ કે પ્રતિષ્ઠાનો કોઈ અહંકાર રાખ્યા વિના તેઓ સદા દીન ભાવે શ્રીજીના ચરણોમાં લીન રહેતા.

એકવાર રાજ્યમાં કઠિન રાજકીય કટોકટી અને સંકટની સ્થિતિ ઊભી થઈ, પરંતુ રામદાસજીએ પોતાની ચતુરાઈ કે સત્તા પર ભરોસો કરવાને બદલે અનન્ય આશ્રય રાખીને તમામ ભાર શ્રીજી અને ગુરુદેવના ચરણો પર છોડી દીધો. તેમની અવિચળ ભક્તિ અને સમર્પણ જોઈને સાક્ષાત શ્રીજીએ તેમની અને તેમના કાર્યોની રક્ષા કરી. રામદાસજી મહેતાએ પોતાનું આખું આયુષ્ય શ્રીજીની નિષ્કામ સેવા, ગુરુભક્તિ અને વૈષ્ણવ-સત્સંગમાં જ વ્યતીત કર્યું.''',
    saar:
        'માનવ ગમે તેવા મોટા પદ કે સત્તા પર હોય, પણ જો તેનું મન અહંકાર રહિત બનીને ભગવાન અને ગુરુદેવના શરણાગત રહે, તો સાક્ષાત પ્રભુ તેના સઘળા લૌકિક અને અલૌકિક કાર્યો સિદ્ધ કરે છે.',
  ),

  VartaModel(
    id: '69',
    number: '૬૯',
    titleGujarati: 'શ્રી રઘુનાથદાસ કાયસ્થની વાર્તા',
    titleBraj: 'રઘુનાથદાસ કાયસ્થ કી વાર્તા',
    shloka: 'कायस्थकुलजातोऽपि भजेत् श्रीवल्लभं प्रभुम् ॥ ६९ ॥',
    arth:
        'પોતાના કૌટુંબિક હોદ્દા, હિસાબી કૌશલ્ય કે લૌકિક ચતુરતાના અહંકારનો ત્યાગ કરીને શ્રીવલ્લભ પ્રભુના દિવ્ય ચરણારવિંદનો જ દ્રઢ આશ્રય સ્વીકારવો.',
    vartaContent:
        '''શ્રી રઘુનાથદાસજી કાયસ્થ કુળના એક અત્યંત ચતુર, વિવેકી અને હિસાબી કાર્યોમાં અત્યંત નિપુણ ભક્ત હતા. તેઓ રાજ્ય અને વ્યાપારી વર્ગમાં લેખન તથા હિસાબ-કિતાબના કામકાજ માટે ખુબ આદરણીય માનવામાં આવતા હતા. લૌકિક દૃષ્ટિએ અત્યંત બુદ્ધિશાળી અને વ્યવહારુ હોવા છતાં, પૂર્વજન્મના પુણ્ય પ્રભાવથી તેમના હૃદયમાં નિત્ય ભગવદ્-સ્મરણ અને આત્મકલ્યાણની તીવ્ર ઝંખના રહેતી હતી.

જ્યારે શ્રીઆચાર્યજી મહાપ્રભુજી પોતાની ભારત પરિક્રમા દરમિયાન તે ક્ષેત્રમાં પધાર્યા, ત્યારે રઘુનાથદાસજી શ્રીમહાપ્રભુજીના અલૌકિક દિવ્ય દર્શનાર્થે આવ્યા. શ્રીમહાપ્રભુજીના મુખારવિંદમાંથી ઝરતાં વચનામૃત અને ભગવદ્-લીલાનું સુબોધિની અમૃત સાંભળીને તેમનો તમામ લૌકિક બુદ્ધિ અને ચતુરતાનો અહંકાર ઓગળી ગયો. તેમણે તુરંત શ્રીઆચાર્યજીના ચરણોમાં સાષ્ટાંગ પ્રણામ કર્યા અને શરણાગતિ સ્વીકારીને બ્રહ્મસંબંધ પ્રાપ્ત કર્યો.

બ્રહ્મસંબંધ લીધા બાદ રઘુનાથદાસજીએ પોતાના ઘરમાં શ્રીઆચાર્યજીની આજ્ઞાનુસાર શ્રીજીનું દિવ્ય સ્વરૂપ પધરાવ્યું. તેઓ પોતાના લૌકિક કાર્યો પતાવ્યા બાદ અત્યંત પવિત્રતા, સાવધાની અને દાસભાવે શ્રીજીની સેવા અર્પિત કરતા. પોતાની ચતુરતાનો ઉપયોગ તેમણે કેવળ પ્રભુસેવાના હિસાબ અને સામગ્રીની વ્યવસ્થા માટે જ કર્યો.

એકવાર તેમના જીવનમાં કઠિન લૌકિક અડચણો અને વિઘ્નો ઊભા થયા, પરંતુ રઘુનાથદાસજીએ પોતાની બુદ્ધિ કે લૌકિક ઉપાયો પર આધાર રાખવાને બદલે સદા શ્રીજી અને ગુરુદેવના ચરણોનો દ્રઢ આશ્રય રાખ્યો. સાક્ષાત શ્રીજીએ તેમની રક્ષા કરી અને સઘળા વિઘ્નો દૂર કર્યા. રઘુનાથદાસજીએ પોતાનું આખું આયુષ્ય નિષ્કામ ભગવદ્-સેવા અને સાધુ-સંતોના સત્સંગમાં જ વ્યતીત કર્યું.''',
    saar:
        'માનવની ચતુરતા કે બુદ્ધિ ત્યારે જ સાર્થક બને છે જ્યારે તે તેનો ઉપયોગ પોતાના અહંકાર માટે નહીં, પરંતુ ભગવદ્-સેવા અને ગુરુચરણોના આશ્રયમાં સમર્પિત થવા માટે કરે છે.',
  ),

  VartaModel(
    id: '70',
    number: '૭૦',
    titleGujarati: 'શ્રી ભગવાનદાસ વૈશ્યની વાર્તા',
    titleBraj: 'ભગવાનદાસ વૈશ્ય કી વાર્તા',
    shloka: 'वैश्यधर्मे स्थितोऽपि भजेत् श्रीवल्लभं प्रभुम् ॥ ७० ॥',
    arth:
        'પોતાના વ્યાપાર-ધંધા અને વૈશ્યધર્મનું પાલન કરતી વખતે લક્ષ્મી કે ધનનો મોહ છોડીને શ્રીવલ્લભ પ્રભુના ચરણારવિંદમાં સદા અનન્ય અને નિષ્કામ ભક્તિભાવ રાખવો.',
    vartaContent:
        '''શ્રી ભગવાનદાસજી વૈશ્ય સમુદાયના એક અત્યંત પ્રખ્યાત, નીતિવાન અને પરમ દયાવાન વેપારી હતા. તેઓ પોતાના વ્યાપારમાં સત્ય, પવિત્રતા અને ઈમાનદારી માટે ખુબ જાણીતા હતા. અઢળક સમૃદ્ધિ અને ધન-દોલત હોવા છતાં, તેમના અંતરમાં સંસારના વિષય-ભોગો પ્રત્યે કોઈ આસક્તિ નહોતી. તેઓ બાલ્યાવસ્થાથી જ નિત્ય પ્રભુસ્મરણ અને સત્સંગમાં રસ ધરાવતા હતા.

જ્યારે શ્રીઆચાર્યજી મહાપ્રભુજી પોતાની ભારત પરિક્રમા દરમિયાન તે ક્ષેત્રમાં પધાર્યા, ત્યારે ભગવાનદાસજી શ્રીમહાપ્રભુજીના દિવ્ય દર્શનાર્થે આવ્યા. શ્રીમહાપ્રભુજીના અલૌકિક દિવ્ય સ્વરૂપના દર્શન કરતાં જ તેમનું અંતઃકરણ શ્રીકૃષ્ણમય બની ગયું. તેમણે તુરંત શ્રીઆચાર્યજી મહાપ્રભુજીના ચરણોમાં સાષ્ટાંગ પ્રણામ કર્યા અને શરણાગતિ સ્વીકારીને બ્રહ્મસંબંધ પ્રાપ્ત કર્યો.

બ્રહ્મસંબંધ લીધા બાદ ભગવાનદાસ વૈશ્યજીએ પોતાની સંપત્તિ અને વ્યાપારને સાક્ષાત શ્રીજીની જ સેવા સામગ્રી માની. તેમણે પોતાના ઘરમાં શ્રીઆચાર્યજીની આજ્ઞાનુસાર શ્રીજીનું દિવ્ય સ્વરૂપ પધરાવ્યું. તેઓ વ્યાપારિક કામકાજ પતાવ્યા બાદ અત્યંત પવિત્રતા, સાવધાની અને દાસભાવે શ્રીજીની સેવા અર્પિત કરતા. પોતાની કમાણીનો ઉપયોગ તેઓ સદા વૈષ્ણવોની સેવા અને શ્રીજીના ઉત્સવો ઉજવવામાં જ કરતા.

એકવાર વ્યાપારમાં મોટી કટોકટી અને લૌકિક સંકટ ઊભું થયું, પરંતુ ભગવાનદાસજીએ પોતાની ચતુરાઈ કે ધન પર ભરોસો કરવાને બદલે સદા શ્રીજી અને શ્રીઆચાર્યજીના ચરણોનો અનન્ય આશ્રય રાખ્યો. તેમની દ્રઢ ભક્તિ જોઈને સાક્ષાત શ્રીજીએ તેમની રક્ષા કરી. ભગવાનદાસ વૈશ્યજીએ પોતાનું આખું આયુષ્ય નિષ્કામ ભગવદ્-સેવા, ગુરુભક્તિ અને સત્સંગમાં જ વ્યતીત કર્યું.''',
    saar:
        'વ્યાપાર કે ધન-સંપત્તિ ક્યારેય ભક્તિમાં બાધક બનતા નથી, જો મનુષ્ય લોભ અને અહંકારનો ત્યાગ કરીને પોતાની કમાણી અને હૃદય ભગવાનના ચરણોમાં સમર્પિત કરે.',
  ),

