    vartaContent:
        '''શ્રી ગંગાબાઈજી ક્ષત્રિય કુળના એક અત્યંત પરમ પવિત્ર, શુદ્ધ અને ઉત્કૃષ્ટ વૈષ્ણવ સદગૃહસ્થ સ્ત્રી હતા. તેઓ સ્વભાવે અત્યંત મૃદુ, દયાવાન, વિવેકી અને બાલ્યાવસ્થાથી જ ભગવદ્-સ્મરણમાં તલ્લીન રહેનારા દિવ્ય આત્મા હતા. લૌકિક સંસારમાં રહેવા છતાં તેમના અંતઃકરણમાં સંસારના ભોગો પ્રત્યે સહેજ પણ આસક્તિ નહોતી.

જ્યારે શ્રીઆચાર્યજી મહાપ્રભુજી પોતાની ભારત પરિક્રમા દરમિયાન તે ક્ષેત્રમાં પધાર્યા, ત્યારે ગંગાબાઈજી શ્રીમહાપ્રભુજીના અલૌકિક દિવ્ય દર્શનાર્થે આવ્યા. શ્રીમહાપ્રભુજીના તેજોમય દિવ્ય સ્વરૂપના દર્શન કરતાં જ તેમનું મન સંપૂર્ણપણે કૃષ્ણમય બની ગયું. તેમણે તુરંત શ્રીઆચાર્યજી મહાપ્રભુજીના ચરણોમાં સાષ્ટાંગ પ્રણામ કર્યા અને શરણાગતિ સ્વીકારીને બ્રહ્મસંબંધ પ્રાપ્ત કર્યો.

બ્રહ્મસંબંધ લીધા બાદ શ્રી ગંગાબાઈજીએ પોતાના ઘરમાં શ્રીઆચાર્યજીની આજ્ઞાનુસાર શ્રીજીનું દિવ્ય સ્વરૂપ પધરાવ્યું. તેઓ નિત્ય વહેલા જાગીને અત્યંત પવિત્રતા, શુદ્ધિ, સાવધાની અને વાત્સલ્યભાવે શ્રીજીની સેવા અર્પિત કરતા. પોતાની લૌકિક જવાબદારીઓ નિભાવતી વખતે પણ તેમનું અંતઃકરણ સદા પોતાના ઈષ્ટદેવ શ્રીજી અને શ્રીઆચાર્યજીના ચરણારવિંદના ધ્યાનમાં જ ઓતપ્રોત રહેતું.

એકવાર તેમના જીવનમાં કઠિન લૌકિક સંકટો અને વિઘ્નો ઊભા થયા, પરંતુ ગંગાબાઈજીએ સહેજ પણ ચિંતિત કે અધીરા થયા વગર અનન્ય આશ્રય રાખીને તમામ ભાર શ્રીજી અને ગુરુદેવના ચરણો પર છોડી દીધો. તેમની અચળ ભક્તિ જોઈને સાક્ષાત શ્રીજીએ તેમની રક્ષા કરી. ગંગાબાઈજીએ પોતાનું આખું આયુષ્ય નિષ્કામ ભગવદ્-સેવા, ગુરુભક્તિ અને સત્સંગમાં જ વ્યતીત કર્યું.''',
