        '''શ્રી હરિદાસીજી એક અત્યંત પરમ ભગવદીય, સાધ્વી અને નમ્ર સ્વભાવના વૈષ્ણવ સદગૃહસ્થ મહિલા હતા. તેઓ સ્વભાવે અત્યંત કોમળ, દયાવાન અને બાલ્યાવસ્થાથી જ શ્રીકૃષ્ણની લીલા અને કથા-સકીર્તનમાં રસ ધરાવતા હતા. સંસારના રાગ-દ્વેષ કે લૌકિક મોહ-માયાથી અલિપ્ત રહીને તેઓ નિત્ય ભગવદ્-ચિંતનમાં જ પોતાનો સમય વિતાવતા હતા.

જ્યારે શ્રીઆચાર્યજી મહાપ્રભુજી પોતાની ભારત પરિક્રમા દરમિયાન તે ક્ષેત્રમાં પધાર્યા, ત્યારે હરિદાસીજી તેમના દિવ્ય દર્શનાર્થે આવ્યા. શ્રીમહાપ્રભુજીના અલૌકિક તેજોમય સ્વરૂપ અને તેમના મુખારવિંદમાંથી ઝરતાં ભાગવતજીના અમૃત વચનો સાંભળીને તેમનું હૃદય પૂર્ણપણે કૃષ્ણરસમાં ડૂબી ગયું. તેમણે શ્રીઆચાર્યજીના ચરણોમાં શરણાગતિ સ્વીકારીને બ્રહ્મસંબંધ પ્રાપ્ત કર્યો.

બ્રહ્મસંબંધ લીધા બાદ શ્રી હરિદાસીજીએ પોતાના ઘરમાં શ્રીઆચાર્યજીની આજ્ઞાનુસાર શ્રીજીનું દિવ્ય સ્વરૂપ પધરાવ્યું. તેઓ નિત્ય પરમ શુદ્ધિ, સાવધાની અને વાત્સલ્યભાવે શ્રીજીની સેવા અર્પિત કરતા. પોતાના ઘરકામ અને લૌકિક ક્રિયાઓ સંભાળતી વખતે પણ તેમનું મન નિત્ય શ્રીજીના ચરણારવિંદના ધ્યાનમાં જ તલ્લીન રહેતું.

એકવાર તેમના જીવનમાં કઠિન લૌકિક પરિસ્થિતિ અને વિઘ્નો આવ્યા, પરંતુ હરિદાસીજીએ પોતાના મનને સહેજ પણ ચલિત થવા દીધું નહીં. તેમણે અનન્ય દ્રઢ આશ્રય રાખીને સર્વ ભાર શ્રીજી અને શ્રીઆચાર્યજીના ચરણો પર છોડી દીધો. તેમની અચળ ભક્તિ જોઈને સાક્ષાત શ્રીજીએ તેમની રક્ષા કરી અને તેમના ઘરમાં પોતાના પ્રત્યક્ષ હોવાનો અનુભવ કરાવ્યો. શ્રી હરિદાસીજીએ પોતાનું આખું આયુષ્ય શ્રીજીની નિષ્કામ સેવા, ગુરુભક્તિ અને વૈષ્ણવ-સત્સંગમાં જ વ્યતીત કર્યું.''',
