        'પોતાની જ્ઞાતિ, કુળ, વેપાર કે લૌકિક ઓળખના અહંકારનો સંપૂર્ણ ત્યાગ કરીને શ્રીવલ્લભ પ્રભુના ચરણારવિંદમાં સદા અચળ અને અનન્ય શરણાગતિ રાખવી.',
    vartaContent:
        '''શ્રી રામદાસજી ખત્રી ક્ષેત્રના એક અત્યંત સજ્જન, નીતિવાન અને ભગવદ્-પરાયણ વૈષ્ણવ હતા. તેઓ ખત્રી સમાજના ઉત્તમોત્તમ ગૃહસ્થ હતા અને વ્યાપાર-રોજગારમાં અત્યંત ઈમાનદાર અને વિવેકી માનવામાં આવતા હતા. લૌકિક કાર્યોમાં પ્રવીણ હોવા છતાં, પૂર્વજન્મના સંસ્કારોના પ્રભાવથી તેમનું ચિત્ત સંસારના વિષય-ભોગોમાં ન રચતાં-પચતાં નિત્ય શ્રીકૃષ્ણ ચરણોના ધ્યાનમાં જ લીન રહેતું હતું.

જ્યારે શ્રીઆચાર્યજી મહાપ્રભુજી પોતાની ભારત પરિક્રમા દરમિયાન તે ક્ષેત્રમાં પધાર્યા, ત્યારે રામદાસજી ખત્રી પોતાના પરિવાર સાથે શ્રીમહાપ્રભુજીના દિવ્ય દર્શનાર્થે આવ્યા. શ્રીઆચાર્યજી મહાપ્રભુજીના અલૌકિક તેજોમય સ્વરૂપ અને તેમના મુખારવિંદમાંથી ઝરતાં ભાગવતજીની કથાનું અમૃત સાંભળીને તેમનો તમામ લૌકિક મોહ અને અહંકાર ક્ષણવારમાં ઓગળી ગયો. તેમણે તુરંત શ્રીઆચાર્યજી મહાપ્રભુજીના ચરણોમાં સાષ્ટાંગ પ્રણામ કર્યા અને શરણાગતિ સ્વીકારીને બ્રહ્મસંબંધ પ્રાપ્ત કર્યો.

બ્રહ્મસંબંધ લીધા બાદ શ્રી રામદાસજી ખત્રીએ પોતાના ઘરમાં શ્રીઆચાર્યજીની આજ્ઞાનુસાર શ્રીજીનું દિવ્ય સ્વરૂપ પધરાવ્યું. તેમણે પોતાના ધંધા-રોજગારને શ્રીજીની સેવા સામગ્રી મેળવવાનું માધ્યમ જ માન્યું. તેઓ નિત્ય વહેલા જાગીને અત્યંત પવિત્રતા, સાવધાની અને સ્નેહભાવે શ્રીજીની સેવા અર્પિત કરતા અને નિત્ય ભગવદ્-સ્મરણમાં જ પોતાનો સમય વિતાવતા.

એકવાર તેમના વ્યાપાર અને જીવનમાં કઠિન લૌકિક વિઘ્નો અને સંકટો આવ્યા, પરંતુ રામદાસજીએ સહેજ પણ ચિંતિત કે અધીરા થયા વગર દ્રઢ નિષ્ઠા રાખીને સઘળો ભાર શ્રીજી અને ગુરુદેવના ચરણો પર છોડી દીધો. તેમની દ્રઢ ભક્તિ જોઈને સાક્ષાત શ્રીજીએ તેમની રક્ષા કરી. રામદાસજી ખત્રીએ પોતાનું શેષ આયુષ્ય નિષ્કામ ભગવદ્-સેવા, ગુરુભક્તિ અને વૈષ્ણવ-સત્સંગમાં જ સફળ કર્યું.''',
    saar:
        'માણસનું કુળ કે વ્યવસાય ગમે તે હોય, જો તેના અંતઃકરણમાં ભગવાન અને ગુરુદેવ પ્રત્યે સાચો અનુરાગ અને આશ્રય હોય, તો સાક્ષાત પ્રભુ તેના સઘળા સંકટો હરી લે છે.',
  ),

  VartaModel(
    id: '74',
    number: '૭૪',
    titleGujarati: 'શ્રી ગોવિંદદાસ ખત્રીની વાર્તા',
    titleBraj: 'ગોવિંદદાસ ખત્રી કી વાર્તા',
    shloka: 'गोविन्ददासभक्तस्य भक्तिर्भवति निष्कला ॥ ७४ ॥',
    arth:
        'સંસારના સર્વ લૌકિક પદ, ચતુરતા કે વ્યાપારના અહંકારનો ત્યાગ કરીને શ્રીવલ્લભ પ્રભુના ચરણારવિંદમાં નિષ્કામ અને અનન્ય ભક્તિ અર્પિત કરવી.',
    vartaContent:
        '''શ્રી ગોવિંદદાસજી ખત્રી ક્ષત્રિય ખત્રી કુળના એક અત્યંત પ્રભાવશાળી, વિવેકી અને નીતિવાન ભક્ત હતા. તેઓ પોતાના વ્યાપાર-વ્યવસાયમાં અત્યંત ચતુર અને સત્યનિષ્ઠ હતા, જેના કારણે સમાજમાં તેમનું મોટું સન્માન હતું. સમૃદ્ધિ અને સન્માન હોવા છતાં તેમના અંતરમાં સંસારના ભોગ-વિલાસ પ્રત્યે કોઈ આસક્તિ નહોતી, પરંતુ સદા શ્રીકૃષ્ણ ચરણોના ધ્યાનમાં જ લીન રહેવાની તીવ્ર ઈચ્છા હતી.

જ્યારે શ્રીઆચાર્યજી મહાપ્રભુજી પોતાની ભારત પરિક્રમા દરમિયાન તે ક્ષેત્રમાં પધાર્યા, ત્યારે ગોવિંદદાસજી ખત્રી શ્રીમહાપ્રભુજીના દિવ્ય દર્શનાર્થે આવ્યા. શ્રીમહાપ્રભુજીના અલૌકિક તેજોમય સ્વરૂપ અને તેમના મુખારવિંદમાંથી ઝરતાં અમૃત વચનો સાંભળીને તેમનો તમામ લૌકિક અહંકાર દૂર થઈ ગયો. તેમણે તુરંત શ્રીઆચાર્યજી મહાપ્રભુજીના ચરણોમાં સાષ્ટાંગ પ્રણામ કર્યા અને શરણાગતિ સ્વીકારીને બ્રહ્મસંબંધ પ્રાપ્ત કર્યો.

બ્રહ્મસંબંધ લીધા બાદ ગોવિંદદાસજીએ પોતાના ઘરમાં શ્રીઆચાર્યજીની આજ્ઞાનુસાર શ્રીજીનું દિવ્ય સ્વરૂપ પધરાવ્યું. તેમણે પોતાના ધંધા અને સંપત્તિને સાક્ષાત શ્રીજીની જ સામગ્રી માની. તેઓ નિત્ય પરમ પવિત્રતા, સાવધાની અને વાત્સલ્યભાવે શ્રીજીની સેવા અર્પિત કરતા.

એકવાર તેમના વ્યાપારમાં મોટી કટોકટી અને સંકટ ઊભું થયું, પરંતુ ગોવિંદદાસજીએ પોતાની બુદ્ધિ કે લૌકિક ઉપાયો પર ભરોસો કરવાને બદલે સદા શ્રીજી અને શ્રીઆચાર્યજીના ચરણોનો અનન્ય આશ્રય રાખ્યો. તેમની દ્રઢ ભક્તિ જોઈને સાક્ષાત શ્રીજીએ તેમની રક્ષા કરી. ગોવિંદદાસજી ખત્રીએ પોતાનું શેષ આયુષ્ય નિષ્કામ ભગવદ્-સેવા, ગુરુભક્તિ અને વૈષ્ણવ-સત્સંગમાં જ વ્યતીત કર્યું.''',
    saar:
        'માણસનું સાચું ભૂષણ તેની સમૃદ્ધિ નથી, પણ પ્રભુ અને ગુરુ પ્રત્યેની નિષ્કામ ભક્તિ છે. જે જીવ સદા પ્રભુના ચરણોના ભરોસે રહે છે, તેની રક્ષા સાક્ષાત શ્રીજી કરે છે.',
  ),

  VartaModel(
