    titleGujarati: 'શ્રી રામદાસજી રાજપૂતની વાર્તા',
    titleBraj: 'રામદાસજી રાજપૂત કી વાર્તા',
    shloka: 'क्षत्रियधर्मे स्थितोऽपि भजेत् श्रीवल्लभं प्रभुम् ॥ ७५ ॥',
    arth:
        'પોતાના ક્ષાત્રધર્મ, શૂરવીરતા અને પરાક્રમ વચ્ચે પણ અહંકારનો ત્યાગ કરીને શ્રીવલ્લભ પ્રભુના ચરણારવિંદમાં સદા દ્રઢ અને અનન્ય આશ્રય રાખવો.',
    vartaContent:
        '''શ્રી રામદાસજી રાજપૂત રાજપૂત ક્ષત્રિય કુળના એક અત્યંત સાહસિક, પ્રતાપી અને ઉત્કૃષ્ટ વીર પુરુષ હતા. તેઓ પોતાની શૂરવીરતા, નીતિમત્તા અને પરાક્રમ માટે પ્રખ્યાત હતા. ક્ષાત્ર તેજથી સંપન્ન હોવા છતાં, પૂર્વજન્મના સંસ્કારોના પ્રભાવથી તેમનું હૃદય લૌકિક અહંકાર કે વિષય-ભોગોમાં રાચવાને બદલે સદા શ્રીકૃષ્ણ ભક્તિ અને ગુરુચરણોના આશ્રયની તીવ્ર ઝંખના રાખતું હતું.

જ્યારે શ્રીઆચાર્યજી મહાપ્રભુજી પોતાની ભારત પરિક્રમા દરમિયાન તે ક્ષેત્રમાં પધાર્યા, ત્યારે રામદાસજી રાજપૂત શ્રીમહાપ્રભુજીના અલૌકિક દિવ્ય દર્શનાર્થે આવ્યા. શ્રીઆચાર્યજી મહાપ્રભુજીના તેજોમય સ્વરૂપ અને તેમના મુખારવિંદમાંથી ઝરતી કથા-સુધા સાંભળીને તેમનો ક્ષાત્ર મોહ અને સત્તાનો અહંકાર ક્ષણવારમાં ગળી ગયો. તેમણે તુરંત શ્રીઆચાર્યજીના ચરણોમાં સાષ્ટાંગ પ્રણામ કર્યા અને શરણાગતિ સ્વીકારીને બ્રહ્મસંબંધ પ્રાપ્ત કર્યો.

બ્રહ્મસંબંધ લીધા બાદ શ્રી રામદાસજી રાજપૂતે પોતાના ઘરમાં શ્રીઆચાર્યજીની આજ્ઞાનુસાર શ્રીજીનું દિવ્ય સ્વરૂપ પધરાવ્યું. તેમણે પોતાની શૂરવીરતા અને બળને શ્રીજી અને ધર્મની સેવામાં જ સમર્પિત કર્યા. તેઓ લૌકિક કર્તવ્યો અદા કર્યા બાદ અત્યંત પવિત્રતા, સાવધાની અને નમ્ર ભાવે શ્રીજીની સેવા અર્પિત કરતા.

એકવાર યુદ્ધ અને વિષમ લૌકિક પરિસ્થિતિ ઊભી થઈ, પરંતુ રામદાસજીએ પોતાની અસ્ત્ર-શસ્ત્ર શક્તિ કે બાહુબળ પર ગર્વ કરવાને બદલે સદા શ્રીજી અને શ્રીઆચાર્યજીના ચરણોનો દ્રઢ આશ્રય રાખ્યો. સાક્ષાત શ્રીજીએ તેમની અને તેમના સત્યની રક્ષા કરી. રામદાસજી રાજપૂતે પોતાનું શેષ આયુષ્ય નિષ્કામ ભગવદ્-સેવા, ગુરુભક્તિ અને સત્સંગમાં જ વ્યતીત કર્યું.''',
    saar:
        'માનવનું પરાક્રમ અને શૂરવીરતા ત્યારે જ સાર્થક બને છે જ્યારે તે અહંકાર મુક્ત થઈને પ્રભુના શરણાગત રહે છે. ભગવાન સદા પોતાના અનન્ય ભક્તની રક્ષા કરે છે.',
  ),

  VartaModel(
