    titleBraj: 'ગંગાબાઈ રાજપૂતાણી કી વાર્તા (દૂસરી)',
    shloka: 'अनन्यभावेन भजेत् श्रीवल्लभं प्रभुम् ॥ ७६ ॥',
    arth:
        'સંસારના સર્વ લૌકિક સંબંધો, ભોગો અને અહંકારનો ક્ષાત્રાવસ્થામાં પણ ત્યાગ કરીને શ્રીવલ્લભ પ્રભુના ચરણારવિંદમાં સદા અનન્ય અને પવિત્ર ભાવે સમર્પિત રહેવું.',
    vartaContent:
        '''શ્રી ગંગાબાઈ રાજપૂતાણી ક્ષત્રિય કુળના એક અત્યંત શૂરવીર, પવિત્ર અને પરમ ભગવદીય મહિલા હતા. ક્ષાત્ર કુળમાં જન્મ હોવા છતાં તેમના સ્વભાવમાં અત્યંત નમ્રતા, દયા અને વિવેક હતા. સંસારના મોહ-માયા કે રાજવી ઠાઠમાઠ પ્રત્યે તેમને કોઈ આસક્તિ નહોતી અને બાલ્યાવસ્થાથી જ તેમનું ચિત્ત સદા શ્રીકૃષ્ણ ચરણોના ધ્યાનમાં જ લીન રહેતું હતું.

જ્યારે શ્રીઆચાર્યજી મહાપ્રભુજી પોતાની ભારત પરિક્રમા દરમિયાન તે ક્ષેત્રમાં પધાર્યા, ત્યારે ગંગાબાઈ રાજપૂતાણી શ્રીમહાપ્રભુજીના અલૌકિક દિવ્ય દર્શનાર્થે આવ્યા. શ્રીઆચાર્યજીના તેજોમય સ્વરૂપના દર્શન કરતાં જ તેમના અંતઃકરણમાંથી લૌકિક મોહ ઓગળી ગયો. તેમણે તુરંત શ્રીઆચાર્યજી મહાપ્રભુજીના ચરણોમાં સાષ્ટાંગ પ્રણામ કર્યા અને શરણાગતિ સ્વીકારીને બ્રહ્મસંબંધ પ્રાપ્ત કર્યો.

બ્રહ્મસંબંધ લીધા બાદ તેમણે પોતાના ઘરમાં શ્રીઆચાર્યજીની આજ્ઞાનુસાર શ્રીજીનું દિવ્ય સ્વરૂપ પધરાવ્યું. તેઓ નિત્ય પરમ પવિત્રતા, સાવધાની, શુદ્ધિ અને વાત્સલ્યભાવે શ્રીજીની સેવા અર્પિત કરતા. પોતાની કૌટુંબિક અને લૌકિક જવાબદારીઓ નિભાવતી વખતે પણ તેમનું મન સદા શ્રીજીના ધ્યાનમાં જ ઓતપ્રોત રહેતું.

એકવાર તેમના જીવનમાં વિષમ લૌકિક સંકટો અને પરિવારિક પરિસ્થિતિઓ આવી પડી, પરંતુ ગંગાબાઈજીએ સહેજ પણ ચિંતિત કે ચલિત થયા વગર અનન્ય દ્રઢ આશ્રય રાખીને તમામ ભાર શ્રીજી અને ગુરુદેવના ચરણો પર છોડી દીધો. તેમની અચળ ભક્તિ અને સમર્પણ જોઈને સાક્ષાત શ્રીજીએ તેમની રક્ષા કરી. ગંગાબાઈ રાજપૂતાણીએ પોતાનું આખું આયુષ્ય નિષ્કામ ભગવદ્-સેવા, ગુરુભક્તિ અને સત્સંગમાં જ સફળ કર્યું.''',
    saar:
        'માનવનું કુળ કે પદ ગમે તે હોય, જો હૃદયમાં પવિત્રતા અને ભગવાન તથા ગુરુદેવ પ્રત્યે અનન્ય દ્રઢ આશ્રય હોય, તો સાક્ષાત પ્રભુ નિત્ય તેની સાથે રહીને રક્ષા કરે છે.',
  ),

