    vartaContent:
        '''શ્રી દામોદરદાસજી સાધોરા (સાધોરા ગામના નિવાસી) એક અત્યંત પરમ વિવેકી, શાંત અને ઉત્કૃષ્ટ ભગવદીય વૈષ્ણવ હતા. તેઓ પોતાના ગ્રામીણ અને ગૃહસ્થ જીવનમાં અત્યંત સરળ, ઈમાનદાર અને દયાવાન હતા. અઢળક લૌકિક કામકાજ વચ્ચે પણ તેમનું ચિત્ત સંસારના ભોગ-વિલાસમાં ન અટવાતાં સદા ભગવદ્-સ્મરણ અને ગુરુચરણોના ધ્યાન તરફ જ ખેંચાયેલું રહેતું.

જ્યારે શ્રીઆચાર્યજી મહાપ્રભુજી પોતાની ભારત પરિક્રમા દરમિયાન સાધોરા ક્ષેત્રમાં કે તેની નજીક પધાર્યા, ત્યારે દામોદરદાસજી શ્રીમહાપ્રભુજીના અલૌકિક દર્શનાર્થે આવ્યા. શ્રીમહાપ્રભુજીના દિવ્ય તેજોમય સ્વરૂપના દર્શન કરતાં જ દામોદરદાસજીનો તમામ લૌકિક અહંકાર ક્ષણવારમાં ઓગળી ગયો. તેમણે તુરંત શ્રીઆચાર્યજીના ચરણોમાં સાષ્ટાંગ પ્રણામ કર્યા અને શરણાગતિ સ્વીકારીને બ્રહ્મસંબંધ પ્રાપ્ત કર્યો.

બ્રહ્મસંબંધ લીધા બાદ દામોદરદાસજી સાધોરાવાળાએ પોતાના ઘરમાં શ્રીઆચાર્યજીની આજ્ઞાનુસાર શ્રીજીનું દિવ્ય સ્વરૂપ પધરાવ્યું. તેઓ નિત્ય પરમ શુદ્ધિ, સાવધાની, પવિત્રતા અને દાસભાવથી શ્રીજીની સેવા અર્પિત કરતા. પોતાના લૌકિક વ્યવહારો સાચવતી વખતે પણ તેમનું મન નિત્ય શ્રીજીના ચરણારવિંદમાં જ રહેતું.

એકવાર તેમના જીવનમાં કઠિન લૌકિક કસોટી અને સંકટો આવ્યા, પરંતુ દામોદરદાસજીએ પોતાના મનને સહેજ પણ ચલિત થવા દીધું નહીં. તેમણે અનન્ય દ્રઢ આશ્રય રાખીને તમામ ભાર શ્રીજી અને ગુરુદેવના ચરણો પર છોડી દીધો. તેમની અચળ ભક્તિ જોઈને સાક્ષાત શ્રીજીએ તેમની રક્ષા કરી અને તેમના ઘરમાં દિવ્ય આનંદનો અનુભવ કરાવ્યો. દામોદરદાસજીએ પોતાનું શેષ આયુષ્ય નિષ્કામ ભગવદ્-સેવા, ગુરુભક્તિ અને વૈષ્ણવ-સત્સંગમાં જ વ્યતીત કર્યું.''',
    saar:
