    arth:
        'શાસ્ત્રજ્ઞાન કે વિદ્યાના અહંકારનો ત્યાગ કરીને શ્રીવલ્લભ પ્રભુના દિવ્ય ચરણારવિંદમાં સદા અનન્ય અને પવિત્ર ભાવે સમર્પિત રહેવું.',
    vartaContent:
        '''શ્રી વ્યાસદાસજી એક અત્યંત પ્રકાંડ વિદ્વાન, શાસ્ત્રજ્ઞ અને ધર્મ પરાયણ બ્રાહ્મણ હતા. તેઓ વેદ, પુરાણ અને વિવિધ શાસ્ત્રોના ઊંડા ગૂઢાર્થ જાણનારા હતા. પોતાની પાંડિત્ય અને કથાવચનમાં નિપુણતા હોવા છતાં, તેમનું હૃદય કેવળ શુષ્ક જ્ઞાનથી તૃપ્ત થતું નહોતું. તેમના અંતરમાં સદા શ્રીકૃષ્ણની લીલા અને સાચા ભગવદ્-રસની તીવ્ર તૃષ્ણા રહેતી હતી.

જ્યારે શ્રીઆચાર્યજી મહાપ્રભુજી પોતાની ભારત પરિક્રમા દરમિયાન તે ક્ષેત્રમાં પધાર્યા, ત્યારે વ્યાસદાસજી શ્રીમહાપ્રભુજીના દિવ્ય દર્શનાર્થે આવ્યા. શ્રીમહાપ્રભુજીના મુખારવિંદમાંથી ઝરતી કથા-સુધા અને સુબોધિનીજીના ગૂઢાર્થ સાંભળીને વ્યાસદાસજીનો તમામ વિદ્યા અને પાંડિત્યનો અહંકાર ક્ષણવારમાં ઓગળી ગયો. તેમને સમજાયું કે સાચી વિદ્યા એ જ છે જે શ્રીકૃષ્ણ ચરણોમાં અનન્ય પ્રેમ ઉત્પન્ન કરે.

તેમણે તુરંત શ્રીઆચાર્યજી મહાપ્રભુજીના ચરણોમાં સાષ્ટાંગ પ્રણામ કર્યા અને શરણાગતિ સ્વીકારીને બ્રહ્મસંબંધ પ્રાપ્ત કર્યો.

બ્રહ્મસંબંધ લીધા બાદ વ્યાસદાસજીએ પોતાના ઘરમાં શ્રીઆચાર્યજીની આજ્ઞાનુસાર શ્રીજીનું દિવ્ય સ્વરૂપ પધરાવ્યું. તેમણે પોતાના જ્ઞાન અને કવિતા-શક્તિનો ઉપયોગ કેવળ શ્રીજીના કીર્તન, ગુણગાન અને કથા-સત્સંગ માટે જ કર્યો. તેઓ નિત્ય પવિત્રતા, શુદ્ધિ અને અનન્ય દાસભાવથી શ્રીજીની સેવા અર્પિત કરતા.

એકવાર તેમના જીવનમાં કઠિન લૌકિક અડચણો અને પરીક્ષાઓ આવી, પરંતુ વ્યાસદાસજીએ સહેજ પણ ચિંતિત થયા વગર સઘળો ભાર શ્રીજી અને શ્રીઆચાર્યજીના ચરણો પર છોડી દીધો. તેમની અચળ ભક્તિ અને સમર્પણ જોઈને સાક્ષાત શ્રીજીએ તેમની રક્ષા કરી. વ્યાસદાસજીએ પોતાનું આખું આયુષ્ય નિષ્કામ ભગવદ્-સેવા, ગુરુભક્તિ અને સત્સંગમાં જ વ્યતીત કર્યું.''',
    saar:
