        'સોના-ચાંદીના વ્યાપાર કે પોતાની કલા-કુશળતાના અહંકારનો સંપૂર્ણ ત્યાગ કરીને શ્રીવલ્લભ પ્રભુના દિવ્ય ચરણારવિંદમાં સદા અચળ અને અનન્ય શરણાગતિ રાખવી.',
    vartaContent:
        '''શ્રી રામદાસજી સોની સોની (સુવર્ણકાર) સમાજના એક અત્યંત નીતિવાન, પવિત્ર અને ચતુર ભક્ત હતા. તેઓ સોના-ચાંદીના ઘરેણાં બનાવવાની દિવ્ય કળામાં અત્યંત નિપુણ હતા. વ્યાપારમાં અત્યંત સત્યનિષ્ઠ અને ઈમાનદાર હોવાને કારણે સમાજમાં તેમનો ખુબ આદર હતો. અઢળક સંપત્તિ અને સોના-ચાંદીના વ્યવસાયમાં જોડાયેલા હોવા છતાં, તેમના અંતઃકરણમાં ધન-દોલત કે વિષય-ભોગ પ્રત્યે લેશમાત્ર પણ મોહ નહોતો. તેમનું મન સદા ભગવદ્-ચિંતનમાં રમમાણ રહેતું હતું.

જ્યારે શ્રીઆચાર્યજી મહાપ્રભુજી પોતાની ભારત પરિક્રમા દરમિયાન તે ક્ષેત્રમાં પધાર્યા, ત્યારે રામદાસજી સોની શ્રીમહાપ્રભુજીના અલૌકિક દિવ્ય દર્શનાર્થે આવ્યા. શ્રીમહાપ્રભુજીના તેજોમય સ્વરૂપ અને તેમના મુખારવિંદમાંથી ઝરતાં અમૃત વચનો સાંભળીને તેમનો તમામ અહંકાર દૂર થઈ ગયો. તેમણે તુરંત શ્રીઆચાર્યજીના ચરણોમાં સાષ્ટાંગ પ્રણામ કર્યા અને શરણાગતિ સ્વીકારીને બ્રહ્મસંબંધ પ્રાપ્ત કર્યો.

બ્રહ્મસંબંધ લીધા બાદ રામદાસજી સોનીએ પોતાની ઘરેણાં બનાવવાની કળાનો ઉપયોગ સાક્ષાત શ્રીજીના દિવ્ય આભૂષણો અને શ્રૃંગાર બનાવવામાં કર્યો. તેમણે પોતાના ઘરમાં શ્રીઆચાર્યજીની આજ્ઞાનુસાર શ્રીજીનું દિવ્ય સ્વરૂપ પધરાવ્યું. તેઓ નિત્ય વહેલા જાગીને પરમ શુદ્ધિ, સાવધાની અને સ્નેહભાવથી શ્રીજીની સેવા અર્પિત કરતા.

એકવાર તેમના જીવન અને વ્યાપારમાં કઠિન લૌકિક સંકટો અને પરીક્ષાઓ ઊભી થઈ, પરંતુ રામદાસજી સોનીએ પોતાની કલા કે ધન પર આધાર રાખવાને બદલે સદા શ્રીજી અને શ્રીઆચાર્યજીના ચરણોનો અનન્ય આશ્રય રાખ્યો. તેમની દ્રઢ નિષ્ઠા જોઈને સાક્ષાત શ્રીજીએ તેમની રક્ષા કરી. રામદાસજી સોનીએ પોતાનું શેષ આયુષ્ય નિષ્કામ ભગવદ્-સેવા, ગુરુભક્તિ અને વૈષ્ણવ-સત્સંગમાં જ સાર્થક કર્યું.''',
    saar:
        'માનવની કળા, જ્ઞાન કે સમૃદ્ધિ ત્યારે જ શોભે છે જ્યારે તે અહંકાર મુક્ત થઈને ભગવાન અને ગુરુદેવના ચરણોમાં સાચા ભાવથી સમર્પિત થઈ જાય છે.',
  ),

  VartaModel(
    id: '82',
    number: '૮૨',
    titleGujarati: 'શ્રી કૃષ્ણદાસજી રાજપૂતની વાર્તા',
    titleBraj: 'કૃષ્ણદાસજી રાજપૂત કી વાર્તા',
    shloka: 'क्षत्रियधर्मे स्थितोऽपि भजेत् श्रीवल्लभं प्रभुम् ॥ ८२ ॥',
    arth:
        'પોતાના ક્ષાત્રધર્મ, ક્ષત્રિય તેજ અને પરાક્રમના અહંકારનો ત્યાગ કરીને શ્રીવલ્લભ પ્રભુના દિવ્ય ચરણારવિંદમાં સદા અચળ અને નિષ્કામ ભક્તિભાવ રાખવો.',
    vartaContent:
        '''શ્રી કૃષ્ણદાસજી રાજપૂત ક્ષત્રિય કુળના એક અત્યંત શૂરવીર, સાહસિક અને નીતિવાન ભક્ત હતા. તેઓ પોતાની વીરતા અને રાજપૂતી આન-બાન-શાન માટે જાણીતા હતા. બાહ્ય દ્રષ્ટિએ ક્ષાત્ર તેજ ધરાવતા હોવા છતાં, પૂર્વજન્મના સંસ્કારોના પ્રભાવથી તેમના અંતઃકરણમાં ક્યારેય સત્તા, પરાક્રમ કે વિષય-ભોગનો અહંકાર આવ્યો નહોતો. તેમના હૃદયમાં સદા શ્રીજી અને ગુરુદેવના આશ્રયની તીવ્ર ઈચ્છા રહેતી હતી.

જ્યારે શ્રીઆચાર્યજી મહાપ્રભુજી પોતાની ભારત પરિક્રમા દરમિયાન તે ક્ષેત્રમાં પધાર્યા, ત્યારે કૃષ્ણદાસજી રાજપૂત શ્રીમહાપ્રભુજીના અલૌકિક દિવ્ય દર્શનાર્થે આવ્યા. શ્રીઆચાર્યજી મહાપ્રભુજીના તેજોમય સ્વરૂપના દર્શન કરતાં જ તેમનો તમામ ક્ષાત્ર અહંકાર ક્ષણવારમાં ઓગળી ગયો. તેમણે તુરંત શ્રીઆચાર્યજીના ચરણોમાં સાષ્ટાંગ પ્રણામ કર્યા અને શરણાગતિ સ્વીકારીને બ્રહ્મસંબંધ પ્રાપ્ત કર્યો.

બ્રહ્મસંબંધ લીધા બાદ કૃષ્ણદાસજી રાજપૂતે પોતાના ઘરમાં શ્રીઆચાર્યજીની આજ્ઞાનુસાર શ્રીજીનું દિવ્ય સ્વરૂપ પધરાવ્યું. તેમણે પોતાની વીરતા અને બળનો ઉપયોગ કેવળ ધર્મ અને શ્રીજીની સેવાની રક્ષા માટે કર્યો. તેઓ નિત્ય પરમ પવિત્રતા, સાવધાની, શુદ્ધિ અને દાસભાવે શ્રીજીની સેવા અર્પિત કરતા અને ભગવદ્-સ્મરણમાં લીન રહેતા.

એકવાર યુદ્ધ અને વિષમ લૌકિક સંકટની ક્ષણ આવી, પરંતુ કૃષ્ણદાસજીએ પોતાના અસ્ત્ર-શસ્ત્ર કે બળ પર ભરોસો કરવાને બદલે સદા શ્રીજી અને શ્રીઆચાર્યજીના ચરણોનો દ્રઢ આશ્રય રાખ્યો. તેમની અચળ ભક્તિ અને અનન્ય શરણાગતિ જોઈને સાક્ષાત શ્રીજીએ તેમની રક્ષા કરી. કૃષ્ણદાસજી રાજપૂતે પોતાનું શેષ આયુષ્ય નિષ્કામ ભગવદ્-સેવા, ગુરુભક્તિ અને વૈષ્ણવ-સત્સંગમાં જ સાર્થક કર્યું.''',
    saar:
        'માણસનું બળ કે શૂરવીરતા ત્યારે જ શોભે છે જ્યારે તે અહંકાર રહિત બનીને ભગવાન અને ગુરુદેવના ચરણોમાં સાચા ભાવથી સમર્પિત થઈ જાય છે.',
  ),

  VartaModel(
    id: '83',
    number: '૮૩',
    titleGujarati: 'શ્રી રામદાસજી બ્રાહ્મણની વાર્તા',
