    arth:
        'પોતાના ઉચ્ચ બ્રાહ્મણ કુળ, શાસ્ત્રજ્ઞાન કે વિપ્રત્વના ગૌરવ/અહંકારનો ત્યાગ કરીને શ્રીવલ્લભ પ્રભુના દિવ્ય ચરણારવિંદમાં સદા અનન્ય, દાસભાવે અને નિષ્કામ ભક્તિમાં સમર્પિત રહેવું.',
    vartaContent:
        '''શ્રી રામદાસજી બ્રાહ્મણ એક પરમ પવિત્ર, વેદ-શાસ્ત્રોના મર્મજ્ઞ અને આચારવાન વિપ્ર હતા. તેઓ નિત્ય સંધ્યા, ગાયત્રી જપ અને ધર્મ-શાસ્ત્રોના અધ્યયનમાં રત રહેતા હતા. ઉચ્ચ બ્રાહ્મણ કુળમાં જન્મ અને શાસ્ત્રજ્ઞાન હોવા છતાં, તેમના અંતઃકરણમાં ક્યારેય વિદ્યા કે જ્ઞાનનો અહંકાર આવ્યો નહોતો. તેમના હૃદયમાં સદા સાચા ભગવદ્-રસ અને અનન્ય શરણાગતિની તીવ્ર ઝંખના રહેતી હતી.

જ્યારે શ્રીઆચાર્યજી મહાપ્રભુજી પોતાની ભારત પરિક્રમા દરમિયાન તે ક્ષેત્રમાં પધાર્યા, ત્યારે રામદાસજી બ્રાહ્મણ શ્રીમહાપ્રભુજીના અલૌકિક દિવ્ય દર્શનાર્થે આવ્યા. શ્રીમહાપ્રભુજીના મુખારવિંદમાંથી ઝરતાં સુબોધિનીજીના ગૂઢાર્થ અને પ્રભુલીલાનું અમૃત પાન કરીને રામદાસજીનો સઘળો શુષ્ક જ્ઞાનનો અહંકાર ક્ષણવારમાં ઓગળી ગયો. તેમને સમજાયું કે શ્રીકૃષ્ણ ચરણોનો નિષ્કામ અનુરાગ જ સર્વોચ્ચ ધર્મ છે. તેમણે તુરંત શ્રીઆચાર્યજીના ચરણોમાં સાષ્ટાંગ પ્રણામ કર્યા અને શરણાગતિ સ્વીકારીને બ્રહ્મસંબંધ પ્રાપ્ત કર્યો.

બ્રહ્મસંબંધ લીધા બાદ રામદાસજીએ પોતાના ઘરમાં શ્રીઆચાર્યજીની આજ્ઞાનુસાર શ્રીજીનું દિવ્ય સ્વરૂપ પધરાવ્યું. પોતાના શાસ્ત્રજ્ઞાન અને મંત્રોચ્ચારનો ઉપયોગ તેમણે કેવળ શ્રીજીની સેવા, સ્તુતિ અને સત્સંગમાં જ કર્યો. તેઓ વહેલી સવારે જાગીને અત્યંત પવિત્રતા, પરા શુદ્ધિ અને દાસભાવથી શ્રીજીની નિત્ય સેવા અર્પિત કરતા.

એકવાર તેમના જીવનમાં કઠિન લૌકિક સંકટ અને પરીક્ષાઓ આવી, પરંતુ રામદાસજી બ્રાહ્મણે પોતાની બુદ્ધિ કે જ્ઞાન પર ભરોસો કરવાને બદલે સદા શ્રીજી અને શ્રીઆચાર્યજીના ચરણોનો દ્રઢ આશ્રય રાખ્યો. તેમની અવિચળ ભક્તિ જોઈને સાક્ષાત શ્રીજીએ તેમની રક્ષા કરી. રામદાસજી બ્રાહ્મણે પોતાનું શેષ આયુષ્ય નિષ્કામ ભગવદ્-સેવા, ગુરુભક્તિ અને વૈષ્ણવ-સત્સંગમાં જ સાર્થક કર્યું.''',
    saar:
        'માણસનો ઉચ્ચ વંશ કે વિદ્યા ત્યારે જ સાર્થક બને છે જ્યારે તે અહંકાર રહિત બનીને ભગવાન અને ગુરુદેવના ચરણોમાં સાચા ભાવથી સમર્પિત થઈ જાય છે.',
  ),

  VartaModel(
