    titleGujarati: 'શ્રી સૂરદાસજીની વાર્તા',
    titleBraj: 'સૂરદાસજી કી વાર્તા',
    shloka: 'सूरदासस्य भक्तेश्च भक्तिर्भवति वैष्णवी ॥ ८४ ॥',
    arth:
        'બાહ્ય નેત્રો ન હોવા છતાં દિવ્ય અંતર્દ્રષ્ટિથી શ્રીકૃષ્ણની બાલ અને કિશોર લીલાના અલૌકિક દર્શન કરીને, અહંકારનો સંપૂર્ણ ત્યાગ કરી શ્રીવલ્લભ પ્રભુના ચરણારવિંદમાં સદા અનન્ય અને પરા ભક્તિ સમર્પિત કરવી.',
    vartaContent:
        '''શ્રી સૂરદાસજી અષ્ટછાપના મુખ્ય કવિઓ અને શ્રીમહાદેવજીના પરમ કૃપાપાત્ર ભગવદીય ભક્ત હતા. તેઓ જન્મથી અંધ (અથવા નેત્રહીન) હોવા છતાં તેમના અંતરમાં દિવ્ય ભગવદ્-જ્ઞાન અને અદ્ભુત કાવ્યશક્તિ પ્રગટ થયેલી હતી. બાલ્યાવસ્થાથી જ તેઓ વિરાગી થઈને પ્રભુના ચિંતન અને વૈરાગ્યપૂર્ણ પદોની રચના કરતા હતા.

જ્યારે શ્રીઆચાર્યજી મહાપ્રભુજી પોતાની ભારત પરિક્રમા દરમિયાન ગૌઘાટ પધાર્યા, ત્યારે સૂરદાસજી શ્રીમહાપ્રભુજીના દિવ્ય દર્શનાર્થે આવ્યા. સૂરદાસજીએ શ્રીમહાપ્રભુજી સમક્ષ પોતાનું દૈન્યપદ ગાવાનું શરૂ કર્યું. શ્રીઆચાર્યજીએ તેમને અટકાવીને કહ્યું — "સૂર હોકે એસો ઘિઘિયાત કાહે કો હૈ? કછુ ભગવદ્-લીલા વર્ણન કરો!" (સૂર હોવા છતાં આવી દીનતા અને કરુણતા શા માટે ગાય છે? કઈ ભગવદ્-લીલાનું વર્ણન કર!)

શ્રીમહાપ્રભુજીના આ અલૌકિક વચન સાંભળતા જ સૂરદાસજીનું અજ્ઞાન અને દીનતા દૂર થઈ ગયા. તેમણે શ્રીઆચાર્યજી મહાપ્રભુજીના ચરણોમાં શરણાગતિ સ્વીકારીને બ્રહ્મસંબંધ પ્રાપ્ત કર્યો. શ્રીમહાપ્રભુજીએ તેમને શ્રીમદ ભાગવતજીની દશમ સ્કંધની કથાનો ગૂઢાર્થ સંભળાવ્યો અને ભગવદ્-લીલાનું જ્ઞાન આપ્યું.

બ્રહ્મસંબંધ અને શ્રીમહાપ્રભુજીની કૃપાદ્રષ્ટિ પ્રાપ્ત થતાં જ સૂરદાસજીના અંતઃકરણમાં શ્રીનાથજીની બાલ અને નિત્ય લીલા પ્રત્યક્ષ પ્રગટ થઈ. શ્રીમહાપ્રભુજીએ તેમને શ્રીનાથજીની સેવામાં કીર્તનકાર તરીકે નિયુક્ત કર્યા. સૂરદાસજી શ્રીનાથજીના નિત્ય દર્શન કરીને એવા અલૌકિક અને અદ્ભુત શ્રૃંગાર તથા બાલ-લીલાના પદો રચતા કે સાક્ષાત શ્રીજી તેમના પદો સાંભળીને અત્યંત પ્રસન્ન થતા. શ્રીજીનો કયો શ્રૃંગાર ધરાવ્યો છે તે નેત્રો વગર પણ સૂરદાસજી પોતાના પદોમાં આબેહૂબ વર્ણવી દેતા.

સૂરદાસજીએ પોતાનું સંપૂર્ણ જીવન શ્રીજીની નિષ્કામ સેવા, કીર્તન અને ગુરુચરણોમાં સમર્પિત કર્યું. તેમણે શ્રીકૃષ્ણ લીલાના હજારો પદો રચ્યા, જે 'સૂરસાગર' તરીકે અમર થઈ ગયા.''',
    saar:
