  factory DatabaseHelper() => _instance;
  DatabaseHelper._internal();

  static Database? _database;

  // Single source of truth for table name
  static const String tableName = 'bethakji';

  // --- Database Initialization ---
  Future<Database> get database async {
    if (_database != null) return _database!;
    _database = await initDatabase();
    return _database!;
  }

  Future<Database> initDatabase() async {
    String path = join(await getDatabasesPath(), 'bethakji_yadi.db');

    return await openDatabase(
      path,
      version: 6, // Incremented version for Varta table
      onCreate: (db, version) async {
        await _createBethakjiTable(db);
        await _createPathavaliTable(db);
        await _createKirtanTable(db);
        await _createVarta84Table(db);
      },
      onUpgrade: (db, oldVersion, newVersion) async {
        // A non-destructive upgrade.
        if (oldVersion < 3) {
          // If the old version didn't have the pathavali table, add it.
          await _createPathavaliTable(db);
        }
        if (oldVersion < 4) {
          // If the old version doesn't have the audioAsset column, add it and populate it.
          await db.execute('ALTER TABLE pathavali ADD COLUMN audioAsset TEXT');
          final batch = db.batch();
          for (final item in pathavaliList) {
            if (item.audioAsset != null) {
              batch.update(
                'pathavali',
                {'audioAsset': item.audioAsset},
                where: 'id = ?',
                whereArgs: [item.id],
              );
            }
          }
          await batch.commit(noResult: true);
        }
        if (oldVersion < 5) {
          await _createKirtanTable(db);
        }
        if (oldVersion < 6) {
          await _createVarta84Table(db);
        }
      },
    );
  }

  Future<void> _createBethakjiTable(Database db) async {
    await db.execute('''
      CREATE TABLE IF NOT EXISTS $tableName (
        id INTEGER PRIMARY KEY,
        number TEXT,
        name TEXT NOT NULL,
        address TEXT,
        contacts TEXT,
        mahatmy TEXT,
        directions TEXT,
        rules TEXT,
        isFavorite INTEGER DEFAULT 0
      )
    ''');
    final batch = db.batch();
    for (final item in bethakji84List) {
      batch.insert(
        tableName,
        item.toMap(),
        conflictAlgorithm: ConflictAlgorithm.replace,
      );
    }
    await batch.commit(noResult: true);
  }

  Future<void> _createPathavaliTable(Database db) async {
    await db.execute('''
      CREATE TABLE IF NOT EXISTS pathavali(
        id TEXT PRIMARY KEY,
        title TEXT NOT NULL,
        content TEXT NOT NULL,
        isFavorite INTEGER NOT NULL DEFAULT 0,
        audioAsset TEXT
      )
    ''');
    final batch = db.batch();
    for (final item in pathavaliList) {
      batch.insert(
        'pathavali',
        item.toMap(),
        conflictAlgorithm: ConflictAlgorithm.replace,
      );
    }
    await batch.commit(noResult: true);
  }

  Future<void> _createKirtanTable(Database db) async {
    await db.execute('''
      CREATE TABLE IF NOT EXISTS kirtan(
        id TEXT PRIMARY KEY,
        number TEXT,
        title TEXT NOT NULL,
        imageAsset TEXT,
        audioAsset TEXT,
        isFavorite INTEGER NOT NULL DEFAULT 0
      )
    ''');
    final batch = db.batch();
    for (final item in kirtanList) {
      batch.insert(
        'kirtan',
        item.toMap(),
        conflictAlgorithm: ConflictAlgorithm.replace,
      );
    }
    await batch.commit(noResult: true);
  }

  Future<void> _createVarta84Table(Database db) async {
    await db.execute('''
      CREATE TABLE IF NOT EXISTS varta84(
        id TEXT PRIMARY KEY,
        number TEXT,
        titleGujarati TEXT,
        titleBraj TEXT,
        shloka TEXT,
        arth TEXT,
        vartaContent TEXT,
        saar TEXT,
        isFavorite INTEGER NOT NULL DEFAULT 0
      )
    ''');
    final batch = db.batch();
    for (final item in varta84List) {
      batch.insert(
        'varta84',
        item.toMap(),
        conflictAlgorithm: ConflictAlgorithm.replace,
      );
    }
    await batch.commit(noResult: true);
  }

  // --- Bethakji Methods ---

  Future<List<BethakjiModel>> getAllBethakji() async {
    final db = await database;

    // Standardized table name
    final List<Map<String, dynamic>> maps = await db.query(tableName);

    debugPrint("RAW DB MAPS COUNT: ${maps.length}");
    if (maps.isNotEmpty) {
      debugPrint("FIRST ROW SAMPLE: ${maps.first}");
    }

    return List.generate(maps.length, (i) {
      return BethakjiModel.fromMap(maps[i]);
    });
  }

  // Insert or update individual item
  Future<int> insertBethakji(BethakjiModel bethakji) async {
    final db = await database;
    return await db.insert(
      tableName,
      bethakji.toMap(),
      conflictAlgorithm: ConflictAlgorithm.replace,
    );
  }

  // Update favorite status
  Future<int> updateFavoriteStatus(String id, int isFavorite) async {
    final db = await database;
    return await db.update(
      tableName,
      {'isFavorite': isFavorite},
      where: 'id = ?',
      whereArgs: [int.tryParse(id) ?? id], // Safe parse for INTEGER primary key
    );
  }

  // Fetch only favorite Bethakji items
  Future<List<BethakjiModel>> getFavoriteBethakji() async {
    final db = await database;
    final List<Map<String, dynamic>> maps = await db.query(
      tableName,
      where: 'isFavorite = ?',
      whereArgs: [1],
    );
    return List.generate(maps.length, (i) => BethakjiModel.fromMap(maps[i]));
  }

  // --- Pathavali Methods ---

  /// Fetches all Pathavali items from the database.
  Future<List<PathavaliItem>> getAllPathavalis() async {
    final db = await database;
    final List<Map<String, dynamic>> maps = await db.query('pathavali');
    return List.generate(maps.length, (i) {
      return PathavaliItem.fromMap(maps[i]);
    });
  }

  /// Fetches a single Pathavali item by its ID.
  Future<PathavaliItem?> getPathavaliItem(String id) async {
    final db = await database;
    final List<Map<String, dynamic>> maps = await db.query(
      'pathavali',
      where: 'id = ?',
      whereArgs: [id],
